# 324-QA fan voice whitelist RSS source registration scaffolding (2026-05-12)
# Adds source_type="fan_voice_pool" recognition. Entries from fan_voice_pool
# sources are fetched via feedparser and cached here, NOT articleized and NOT
# added to media_quote_pool. The picker (325-QA, gated by
# ENABLE_FAN_VOICE_WHITELIST) consumes this cache. With no config entries of
# type=fan_voice_pool, the cache stays empty and the cache has no effect on
# any existing fetch / publish / picker path.
_FAN_VOICE_POOL_CACHE_LIMIT = 200
_FAN_VOICE_POOL_CACHE: list[dict] = []


def _reset_fan_voice_pool_cache() -> None:
    """Clear fan_voice_pool cache. Called at run start to drop stale entries."""
    global _FAN_VOICE_POOL_CACHE
    _FAN_VOICE_POOL_CACHE = []


def _record_fan_voice_pool_entries(source_name: str, entries) -> int:
    """Normalize and append fan_voice_pool entries to the cache.

    Returns the count of entries actually appended (after dedupe and cap).
    """
    if not entries:
        return 0
    added = 0
    cap = _FAN_VOICE_POOL_CACHE_LIMIT
    seen_urls = {item.get("url") for item in _FAN_VOICE_POOL_CACHE if item.get("url")}
    for entry in entries:
        if len(_FAN_VOICE_POOL_CACHE) >= cap:
            break
        if not isinstance(entry, dict) and not hasattr(entry, "get"):
            continue
        url = ""
        if hasattr(entry, "get"):
            url = entry.get("link", "") or entry.get("url", "") or ""
        if url and url in seen_urls:
            continue
        text = ""
        if hasattr(entry, "get"):
            text = entry.get("summary", "") or entry.get("description", "") or entry.get("title", "") or ""
        text = text.strip()
        if not text:
            continue
        handle = _extract_handle_from_tweet_url(url) if url else ""
        normalized = {
            "source_name": source_name,
            "handle": handle,
            "text": text,
            "url": url,
            "created_at": entry.get("published_parsed") if hasattr(entry, "get") else None,
        }
        _FAN_VOICE_POOL_CACHE.append(normalized)
        if url:
            seen_urls.add(url)
        added += 1
    return added


def get_fan_voice_pool_entries() -> list[dict]:
    """Return a defensive copy of currently cached fan_voice_pool entries.

    Consumers: 325-QA picker integration (gated by ENABLE_FAN_VOICE_WHITELIST).
    Returns an empty list when no fan_voice_pool source has fired.
    """
    return list(_FAN_VOICE_POOL_CACHE)


def get_fan_voice_whitelist_enabled() -> bool:
    """Return True iff ENABLE_FAN_VOICE_WHITELIST=1.

    Default OFF. Picker integration (325-QA) reads this flag; with no callers
    yet wired, this helper is dead-but-safe.
    """
    return _env_flag("ENABLE_FAN_VOICE_WHITELIST", False)


def _fan_reaction_subject_context_required_enabled() -> bool:
    """Require fan reaction text to contain article subject (player/topic name).

    Default OFF (opt-in via env). Existing test fixtures use generic-keyword
    mocks; enabling by default would regress them. Prod env sets =1 to
    actively drop generic 巨人 chatter that doesn't mention the article subject.
    """
    return _env_flag("ENABLE_FAN_REACTION_SUBJECT_CONTEXT_REQUIRED", False)


def _fan_reaction_handle_cap_enabled() -> bool:
    """Cap how many reactions a single X handle can occupy in one article.

    Default OFF (opt-in via env). Prod env sets =1 (cap=2 default) to prevent
    a single handle dominating the fan voice block (e.g. noraneko0122 x4 in
    post 66788, 2026-05-13 audit).
    """
    return _env_flag("ENABLE_FAN_REACTION_HANDLE_CAP", False)


def _fan_reaction_handle_cap() -> int:
    return max(1, _env_int("FAN_REACTION_HANDLE_CAP", 2))


def _fan_reaction_time_decay_enabled() -> bool:
    """Exponential-tier time decay on fan reaction ranking (default ON).

    Industry standard for news / social aggregators: newer posts rank higher.
    Implemented as bucket tier (3=<6h, 2=<24h, 1=<48h, 0=>=48h) inserted into
    the sort key between focus_score and commentary_score, so fresh posts of
    same focus_score win over older equivalents. Flag OFF reverts to the
    legacy ordering (created_at only as final tiebreaker)."""
    return _env_flag("ENABLE_FAN_REACTION_TIME_DECAY", True)


def _reaction_recency_bucket(created_at: int | None, now_ts: int) -> int:
    """Return 0..3 recency tier from post age. Bigger = fresher."""
    if not created_at:
        return 0
    try:
        age_h = (int(now_ts) - int(created_at)) / 3600.0
    except (TypeError, ValueError):
        return 0
    if age_h < 0:
        return 3
    if age_h < 6:
        return 3
    if age_h < 24:
        return 2
    if age_h < 48:
        return 1
    return 0


def _aggressive_title_name_backfill_enabled() -> bool:
    """329-QA: 316-A backfill が unresolved になる時、giants_roster.json で
    再 scan して exactly 1 player match があれば強制 backfill する。
    default ON、ENABLE_AGGRESSIVE_TITLE_NAME_BACKFILL=0 で無効化可能。"""
    return _env_flag("ENABLE_AGGRESSIVE_TITLE_NAME_BACKFILL", True)


def _fan_reaction_ner_bonus_enabled() -> bool:
    """NER-based player entity overlap bonus on fan reactions (default ON).

    Industry standard for news matching: shared named entities are strong
    relevance signal. We reuse giants_roster.json player alias index to
    detect player name overlap between article subject (title+summary) and
    the candidate reaction text. Each shared player adds +1 to the bonus
    (capped at 3). Inserted into the sort key after focus_score so NER
    overlap promotes posts that mention the same player as the article."""
    return _env_flag("ENABLE_FAN_REACTION_NER_BONUS", True)


def _reaction_roster_overlap(text: str, title: str, summary: str) -> int:
    """Count of giants roster player names shared between article
    (title+summary) and the candidate reaction text. Capped at 3."""
    try:
        article_entities = set(_matching_giants_roster_names(f"{title} {summary}"))
    except Exception:
        return 0
    if not article_entities:
        return 0
    try:
        reaction_entities = set(_matching_giants_roster_names(text or ""))
    except Exception:
        return 0
    overlap = article_entities & reaction_entities
    if not overlap:
        return 0
    return min(3, len(overlap))


