def _social_quote_count(title: str, summary: str, article_text: str = "") -> int:
    quote_count = len(_extract_quote_phrases(f"{title}\n{summary}", max_phrases=4))
    body_quote_count = (article_text or "").count("『")
    return max(quote_count, body_quote_count)


def _split_render_lines_into_sections(
    render_lines: list[str],
    *,
    body_category: str,
    has_game: bool,
    body_subtype: str,
) -> list[tuple[str, list[str]]]:
    sections: list[tuple[str, list[str]]] = []
    seen_headings: set[str] = set()
    current_heading = ""
    current_paragraphs: list[str] = []

    def _flush() -> None:
        nonlocal current_heading, current_paragraphs
        if current_heading or current_paragraphs:
            sections.append((current_heading, list(current_paragraphs)))
        current_heading = ""
        current_paragraphs = []

    for line in render_lines:
        if line.startswith("【") or line.startswith("■") or line.startswith("▶"):
            heading_text = _normalize_article_heading(
                line,
                body_category,
                has_game,
                article_subtype=body_subtype,
            )
            if heading_text in seen_headings:
                continue
            _flush()
            seen_headings.add(heading_text)
            current_heading = heading_text
        elif "コメント" in line and ("意見" in line or "教えてください" in line):
            continue
        else:
            current_paragraphs.append(line)

    _flush()
    return sections


def _flatten_render_sections(sections: list[tuple[str, list[str]]]) -> list[str]:
    flattened: list[str] = []
    for heading, paragraphs in sections:
        if heading:
            flattened.append(heading)
        flattened.extend(paragraphs)
    return flattened


def _maybe_remove_social_v1_visible_heading_lines(
    render_lines: list[str],
    *,
    body_category: str,
    has_game: bool,
    body_subtype: str,
    logger: logging.Logger,
) -> list[str]:
    target_subtypes = {"social_news", "player_notice", "player_recovery"}
    target_headings = ("【発信内容の要約】", "【文脈と背景】")
    if not _social_v1_heading_removal_enabled():
        return render_lines
    if body_subtype not in target_subtypes:
        return render_lines

    sections = _split_render_lines_into_sections(
        render_lines,
        body_category=body_category,
        has_game=has_game,
        body_subtype=body_subtype,
    )
    flattened_before = _flatten_render_sections(sections)
    filtered_sections = [
        (heading, paragraphs)
        for heading, paragraphs in sections
        if heading not in target_headings
    ]
    flattened_after = _flatten_render_sections(filtered_sections)
    if not flattened_after:
        flattened_after = flattened_before
    logger.info(
        json.dumps(
            {
                "event": "social_v1_visible_heading_removed",
                "subtype": body_subtype,
                "removed_headings": ["発信内容の要約", "文脈と背景"],
                "body_length_before": len("\n".join(flattened_before)),
                "body_length_after": len("\n".join(flattened_after)),
                "severity": "INFO",
            },
            ensure_ascii=False,
        )
    )
    return flattened_after


def _notice_section_count(text: str) -> int:
    normalized = _normalize_article_text_structure(text or "", "選手情報", False, article_subtype="player_notice")
    return sum(1 for heading in _notice_required_headings() if heading in normalized)


def _notice_body_has_required_structure(text: str) -> bool:
    normalized = _normalize_article_text_structure(text or "", "選手情報", False, article_subtype="player_notice")
    return all(heading in normalized for heading in _notice_required_headings())


def _notice_has_player_name(text: str, title: str, summary: str) -> bool:
    subject, _notice_type = _extract_notice_subject_and_type(title, summary)
    candidate = subject or _short_subject_name(title, summary, "選手情報")
    if not candidate or candidate in {"巨人", "選手", "出場選手"}:
        return False
    return _re.sub(r"\s+", "", candidate) in _re.sub(r"\s+", "", text or "")


def _notice_has_numeric_record(text: str) -> bool:
    body = text or ""
    return any(marker in body for marker in NOTICE_RECORD_MARKERS) or bool(_re.search(r"(?:\.\d{3}|防御率\d+\.\d+|\d+試合|\d+打点|\d+本塁打)", body))


def _starts_with_starmen_prefix(text: str) -> bool:
    clean = _collapse_ws(_strip_html(text or ""))
    return bool(_re.search(rf"^[\s\u3000【\[\(（「『]*{_re.escape(LIVE_UPDATE_LINEUP_TITLE_PREFIX)}", clean))


def _build_game_strict_prompt(
    title: str,
    summary: str,
    article_subtype: str,
    source_fact_block: str,
    source_day_label: str = "",
    team_stats_block: str = "",
) -> str:
    source_text = f"{title} {summary}"
    opponent = _extract_game_opponent_label(source_text)
    venue = _extract_game_venue_label(source_text)
    start_time = _extract_game_time_token(source_text)
