def _build_game_parts_prompt_postgame(
    title: str,
    summary: str,
    source_fact_block: str,
    score: str,
    win_loss_hint: str,
    team_stats_reference: str,
    source_name: str = "",
    source_url: str = "",
) -> str:
    score_block = f"・score: {score}\n" if score else ""
    win_loss_block = f"・win_loss_hint: {win_loss_hint}\n" if win_loss_hint else ""
    source_attribution_block = ""
    if source_name or source_url:
        source_attribution_block = (
            f"・source_name: {source_name}\n"
            f"・source_url: {source_url}\n"
        )
    team_stats_block = ""
    if team_stats_reference:
        team_stats_block = (
            "\n【参考メモ】\n"
            f"{team_stats_reference}\n"
            "・参考メモを使う場合も、source / 材料 に明示された事実だけを採用する\n"
        )

    return f"""あなたは読売ジャイアンツ専門ブログの編集者です。
以下の source / 材料だけを使って、postgame 記事用の部品 JSON を1つ返してください。
全文の HTML や template 構造は書かないでください。JSON object で返してください。コードフェンスも不要です。

【source / 材料】
・title: {title}
・summary: {summary}
{score_block}{win_loss_block}【source_fact_block】
{source_fact_block}
{source_attribution_block}{team_stats_block}

【返却 JSON schema】
{{
  "title": "str",
  "fact_lead": "str",
  "body_core": ["str"],
  "game_context": "str",
  "fan_view": "str",
  "source_attribution": {{
    "source_name": "str",
    "source_url": "str"
  }}
}}

【field rules】
・title: 記事タイトル。H1 相当の文字列のみ。H タグを含めない
・fact_lead: 事実リード。1〜2文。source / 材料にある事実だけで書く
・body_core: 本文核。2〜5段落。各要素は1段落ぶんの文字列にし、source / 材料にある事実の言い換えだけで構成する
・game_context: 試合文脈。1〜2文。source / 材料にある時系列または前後比較だけを書く
・fan_view: ファン視点。1文のみ。source / 材料にある事実に基づく短い感想だけを書く。close marker の語尾は許可する
・source_attribution: {{"source_name":"str","source_url":"str"}} の dict。source / 材料に明示された値だけを入れ、無い場合は空文字にする

【禁止事項】
・source / 材料 にない事実・数字・比較・推測は禁止
・fan_view 以外で感想は禁止
・H タグ禁止
・全文 HTML 禁止
・template 構造の文章化禁止
・source_attribution 以外の追加 field 禁止
・body_core を1段落だけにしない
・source_attribution を文字列にしない
"""


def _fetch_team_stats_block_for_strict_article(category: str, logger: logging.Logger) -> str:
    team_stats_block = ""
    if os.environ.get("ARTICLE_INJECT_TEAM_STATS", "1") == "1" and category in ("試合速報", "首脳陣"):
        try:
            team_stats = fetch_giants_batting_stats_from_yahoo()
            team_stats_block = _format_team_batting_stats_block(team_stats)
        except Exception as e:
            logger.warning("team batting stats 取得失敗: %s", e)
            team_stats_block = ""
    if team_stats_block:
        logger.info(
            json.dumps(
                {
                    "event": "article_team_stats_injected",
                    "category": category,
                    "line_count": team_stats_block.count("\n") + 1,
                },
                ensure_ascii=False,
            )
        )
    return team_stats_block


def _request_gemini_strict_text(
    *,
    api_key: str,
    prompt: str,
    logger: logging.Logger,
    attempt_limit: int,
    min_chars: int,
    log_label: str = "Gemini strict fact mode",
    source_url: str | None = None,
    budget_post_id: int | None = None,
    budget_content_hash: str | None = None,
    budget_prompt_template_id: str | None = None,
    budget_source_url_hash: str | None = None,
    budget_record_enabled: bool = False,
    now: datetime | None = None,
) -> str:
    import urllib.request
    from src import llm_cost_emitter as _llm_cost

    payload = json.dumps(
        {
            "contents": [{"parts": [{"text": prompt}]}],
            "generationConfig": {
                "maxOutputTokens": 1536,
                "temperature": 0.35,
                "thinkingConfig": {"thinkingBudget": GEMINI_FLASH_THINKING_BUDGET},
            },
        }
    ).encode("utf-8")
    logger.info("%s で記事生成中（最大%d回試行）...", log_label, attempt_limit)
    for attempt in range(attempt_limit):
        try:
            if budget_record_enabled and budget_post_id is not None:
                _llm_call_dedupe.record_gemini_call_attempt(
                    post_id=budget_post_id,
                    content_hash=budget_content_hash,
                    prompt_template_id=budget_prompt_template_id,
                    source_url_hash=budget_source_url_hash,
                    provider="gemini",
                    model="gemini-2.5-flash",
                    now=now,
                )
            url = f"https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key={api_key}"
            req = urllib.request.Request(url, data=payload, headers={"Content-Type": "application/json"})
            with urllib.request.urlopen(req, timeout=90) as res:
                data = json.load(res)
            parts = data["candidates"][0]["content"].get("parts", [])
            raw_text = "".join(p.get("text", "") for p in parts if "text" in p).strip()
            raw_text = _strip_prompt_role_echo(raw_text)
            token_in, token_out = _llm_cost.extract_usage_metadata(data)
            _emit_llm_cost_with_observability(
                logger,
                "rss_fetcher._request_gemini_strict_text.success",
                lane="rss_fetcher_strict",
                call_site="rss_fetcher._request_gemini_strict_text",
                post_id=None,
                source_url=source_url,
                content_hash=None,
                model="gemini-2.5-flash",
                input_chars=len(prompt),
                output_chars=len(raw_text),
                token_in=token_in,
                token_out=token_out,
                cache_hit=False,
                skip_reason=None,
                success=True,
                error_class=None,
            )
            if raw_text and len(raw_text) >= min_chars:
                logger.info("%s 生成成功 %d文字", log_label, len(raw_text))
                return raw_text
            logger.warning(
                "%s 応答が短すぎる（%d文字, 必要%d文字）、試行 %d/%d",
                log_label,
                len(raw_text),
                min_chars,
                attempt + 1,
                attempt_limit,
            )
        except Exception as e:
            _emit_llm_cost_with_observability(
                logger,
                "rss_fetcher._request_gemini_strict_text.error",
                lane="rss_fetcher_strict",
                call_site="rss_fetcher._request_gemini_strict_text",
                post_id=None,
                source_url=source_url,
                content_hash=None,
                model="gemini-2.5-flash",
                input_chars=len(prompt),
                output_chars=0,
                token_in=None,
                token_out=None,
                cache_hit=False,
                skip_reason=None,
                success=False,
                error_class=type(e).__name__,
            )
            logger.warning("%s 失敗 試行%d/%d: %s", log_label, attempt + 1, attempt_limit, e)
    logger.error("%s が上限回数に達したため記事生成スキップ", log_label)
    return ""


def _get_gemini_cache_cooldown_hours() -> int:
    raw = str(os.environ.get(GEMINI_CACHE_COOLDOWN_HOURS_ENV, GEMINI_CACHE_COOLDOWN_HOURS_DEFAULT)).strip()
    try:
        parsed = int(raw)
    except ValueError:
        return GEMINI_CACHE_COOLDOWN_HOURS_DEFAULT
    return max(parsed, 0)


def _get_gemini_cache_manager() -> GeminiCacheManager | None:
    if _get_gemini_cache_cooldown_hours() <= 0:
        return None
    return GeminiCacheManager.from_env()


def _gemini_prompt_template_id(category: str, article_subtype: str) -> str:
    safe_category = _re.sub(r"[^a-z0-9一-龯ぁ-んァ-ヴー]+", "_", str(category or "").strip().lower()) or "unknown"
    safe_subtype = _re.sub(r"[^a-z0-9_]+", "_", str(article_subtype or "").strip().lower()) or "general"
    return f"strict_article_{GEMINI_STRICT_PROMPT_TEMPLATE_VERSION}_{safe_category}_{safe_subtype}"


def _build_gemini_cache_content_text(*parts: object) -> str:
    return "\n".join(str(part).strip() for part in parts if str(part or "").strip())


def _build_gemini_cache_key(
    *,
    source_url: str,
    content_text: str,
    prompt_template_id: str,
) -> GeminiCacheKey:
    return GeminiCacheKey(
        source_url_hash=_hash_duplicate_guard_value(source_url),
        content_hash=_compute_gemini_content_hash(content_text),
        prompt_template_id=str(prompt_template_id or "").strip(),
    )


def _resolve_cache_metric_post_id(candidate_meta: dict[str, Any] | None) -> int | None:
    if not isinstance(candidate_meta, dict):
        return None
    for key in ("post_id", "wp_post_id", "id"):
        value = candidate_meta.get(key)
        try:
            return int(value)
        except (TypeError, ValueError):
            continue
    return None


def _coerce_candidate_metric_post_id(value: Any) -> int | None:
    try:
        resolved = int(value)
    except (TypeError, ValueError):
        return None
    return resolved if resolved > 0 else None


def _derive_stable_candidate_metric_post_id(*parts: object) -> int | None:
    normalized_parts = [str(part).strip() for part in parts if str(part or "").strip()]
    if not normalized_parts:
        return None
    stable_hash = _hash_duplicate_guard_value("|".join(normalized_parts))
    if not stable_hash:
        return None
    return int(stable_hash[:15], 16)


def _resolve_gemini_candidate_post_identifiers(
    *,
    title: str,
    category: str,
    article_subtype: str,
    source_name: str,
    source_url: str,
    post_context: dict | None = None,
    source_entry: dict | None = None,
) -> dict[str, int]:
    contexts = [
        context
        for context in (post_context, source_entry)
        if isinstance(context, dict)
    ]
    explicit_post_id: int | None = None
    explicit_wp_post_id: int | None = None
    explicit_id: int | None = None
    for context in contexts:
        if explicit_post_id is None:
            explicit_post_id = _coerce_candidate_metric_post_id(context.get("post_id"))
        if explicit_wp_post_id is None:
            explicit_wp_post_id = _coerce_candidate_metric_post_id(context.get("wp_post_id"))
        if explicit_id is None:
            explicit_id = _coerce_candidate_metric_post_id(context.get("id"))

    resolved: dict[str, int] = {}
    if explicit_post_id is not None:
        resolved["post_id"] = explicit_post_id
    if explicit_wp_post_id is not None:
        resolved["wp_post_id"] = explicit_wp_post_id
    if explicit_id is not None:
        resolved["id"] = explicit_id
    if resolved:
        if "post_id" not in resolved:
            if explicit_wp_post_id is not None:
                resolved["post_id"] = explicit_wp_post_id
            elif explicit_id is not None:
                resolved["post_id"] = explicit_id
        return resolved

    if not contexts:
        return {}

    history_url = ""
    if isinstance(post_context, dict):
        history_urls = post_context.get("history_urls")
        if isinstance(history_urls, list):
            history_url = next((str(url).strip() for url in history_urls if str(url).strip()), "")
    stable_post_id = _derive_stable_candidate_metric_post_id(
        history_url,
        source_url,
        category,
        article_subtype,
        title,
        source_name,
    )
    return {"post_id": stable_post_id} if stable_post_id is not None else {}


def _build_gemini_preflight_candidate_meta(
    *,
    title: str,
    summary: str,
    category: str,
    article_subtype: str,
    source_name: str,
    source_url: str,
    source_type: str,
    has_game: bool,
    source_links: list[dict] | None = None,
    source_entry: dict | None = None,
    post_context: dict | None = None,
    published_at: datetime | None = None,
    duplicate_guard_context: dict | None = None,
) -> dict[str, Any]:
    resolved_source_url = str(source_url or "").strip()
    if not resolved_source_url and isinstance(source_entry, dict):
        resolved_source_url = str(source_entry.get("url") or source_entry.get("link") or "").strip()
    source_handle = _extract_handle_from_tweet_url(resolved_source_url) if resolved_source_url else ""
    source_blob = " ".join(part for part in (title, summary, source_name) if part)
    existing_publish_same_source_url = False
    if isinstance(duplicate_guard_context, dict):
        existing_publish_same_source_url = bool(
            duplicate_guard_context.get("existing_publish_same_source_url")
            or duplicate_guard_context.get("source_url_already_published")
        )
    candidate_meta = {
        "title": title,
        "summary": summary,
        "body_text": summary,
        "source_body": summary,
        "category": category,
        "article_subtype": article_subtype,
        "source_name": source_name,
        "source_handle": source_handle,
        "source_url": resolved_source_url,
        "post_url": resolved_source_url,
        "source_type": source_type,
        "source_links": list(source_links or []),
        "published_at": published_at,
        "has_game": has_game,
        "duplicate_guard_context": duplicate_guard_context if isinstance(duplicate_guard_context, dict) else None,
        "existing_publish_same_source_url": existing_publish_same_source_url,
        "is_giants_related": is_giants_related(source_blob, source_name=source_name, post_url=resolved_source_url),
    }
    candidate_meta.update(
        _resolve_gemini_candidate_post_identifiers(
            title=title,
            category=category,
            article_subtype=article_subtype,
            source_name=source_name,
            source_url=resolved_source_url,
            post_context=post_context,
            source_entry=source_entry,
        )
    )
    return candidate_meta


def _gemini_cache_lookup(
    cache_key: GeminiCacheKey,
    *,
    cache_manager: GeminiCacheManager,
    cooldown_hours: int,
    now: datetime | None,
) -> tuple[GeminiCacheValue | None, str, int]:
    return cache_manager.lookup(
        cache_key,
        cooldown_hours=cooldown_hours,
        now=now,
    )


def _gemini_cache_save(
    cache_key: GeminiCacheKey,
    *,
    generated_text: str,
    cache_manager: GeminiCacheManager,
    now: datetime | None,
) -> int:
    return cache_manager.save(
        cache_key,
        generated_text,
        now=now,
        model=GEMINI_CACHE_MODEL_NAME,
    )


def _log_gemini_cache_lookup(
    logger: logging.Logger,
    *,
    source_url: str,
    cache_key: GeminiCacheKey,
    cache_hit: bool,
    cache_hit_reason: str,
    cache_hit_kind: str = "unknown",
    gemini_call_made: bool,
    cache_size_bytes: int,
) -> None:
    payload = {
        "event": "gemini_cache_lookup",
        "post_url": str(source_url or ""),
        "source_url_hash": str(cache_key.source_url_hash or ""),
        "content_hash": str(cache_key.content_hash or ""),
        "prompt_template_id": str(cache_key.prompt_template_id or ""),
        "cache_hit": bool(cache_hit),
        "cache_hit_reason": str(cache_hit_reason or ""),
        "cache_hit_kind": str(cache_hit_kind or "unknown"),
        "gemini_call_made": bool(gemini_call_made),
        "cache_size_bytes": int(cache_size_bytes or 0),
    }
    if _fetcher_log_sampling_v1_enabled():
        if gemini_call_made:
            _log_sampling_state["gemini_cache_lookup_call_made"] += 1
            logger.info(json.dumps(payload, ensure_ascii=False))
            return
        if cache_hit:
            _log_sampling_state["gemini_cache_lookup_hit"] += 1
        else:
            _log_sampling_state["gemini_cache_lookup_miss"] += 1
        return
    logger.info(json.dumps(payload, ensure_ascii=False))


def _log_gemini_cache_backend_error(
    logger: logging.Logger,
    *,
    source_url: str,
    cache_key: GeminiCacheKey,
    stage: str,
    error: Exception,
) -> None:
    payload = {
        "event": "gemini_cache_backend_error",
        "post_url": str(source_url or ""),
        "source_url_hash": str(cache_key.source_url_hash or ""),
        "content_hash": str(cache_key.content_hash or ""),
        "prompt_template_id": str(cache_key.prompt_template_id or ""),
        "stage": str(stage or ""),
        "error_class": type(error).__name__,
        "error": str(error),
    }
    logger.warning(json.dumps(payload, ensure_ascii=False))


