def _gemini_text_with_cache(
    *,
    api_key: str,
    prompt: str,
    logger: logging.Logger,
    attempt_limit: int,
    min_chars: int,
    source_url: str,
    content_text: str,
    prompt_template_id: str,
    cache_manager: GeminiCacheManager | None,
    candidate_meta: dict[str, Any] | None = None,
    now: datetime | None = None,
    log_label: str = "Gemini strict fact mode",
) -> tuple[str, dict[str, Any]]:
    cache_key = _build_gemini_cache_key(
        source_url=source_url,
        content_text=content_text,
        prompt_template_id=prompt_template_id,
    )
    telemetry: dict[str, Any] = {
        "cache_hit": False,
        "cache_hit_reason": "cache_disabled",
        "cache_hit_kind": "unknown",
        "source_url_hash": cache_key.source_url_hash,
        "content_hash": cache_key.content_hash,
        "cache_size_bytes": 0,
        "gemini_call_made": True,
    }
    preflight_candidate: dict[str, Any] | None = None
    budget_post_id = _resolve_cache_metric_post_id(candidate_meta)
    logger.info(
        "per_post_budget_meta_resolution: post_id=%s",
        budget_post_id if budget_post_id is not None else "None",
    )
    if candidate_meta is not None:
        preflight_candidate = dict(candidate_meta)
        preflight_candidate.setdefault("source_url", source_url)
        preflight_candidate.setdefault("post_url", source_url)
        preflight_candidate.setdefault("source_url_hash", cache_key.source_url_hash)
        preflight_candidate.setdefault("content_hash", cache_key.content_hash)
        should_skip, skip_reason = should_skip_gemini(preflight_candidate, now=now)
        if should_skip and skip_reason:
            telemetry["cache_hit_reason"] = "preflight_skip"
            telemetry["gemini_call_made"] = False
            telemetry["skip_reason"] = skip_reason
            telemetry["skip_layer"] = PREFLIGHT_SKIP_LAYER
            emit_gemini_call_skipped(logger, candidate=preflight_candidate, skip_reason=skip_reason)
            _record_preflight_skip_history(
                logger,
                candidate=preflight_candidate,
                skip_reason=skip_reason,
            )
            return "", telemetry
    if cache_manager is not None and cache_key.source_url_hash and cache_key.prompt_template_id:
        try:
            cached, hit_reason, cache_size_bytes = _gemini_cache_lookup(
                cache_key,
                cache_manager=cache_manager,
                cooldown_hours=_get_gemini_cache_cooldown_hours(),
                now=now,
            )
        except GeminiCacheBackendError as exc:
            _log_gemini_cache_backend_error(
                logger,
                source_url=source_url,
                cache_key=cache_key,
                stage="lookup",
                error=exc,
            )
            telemetry["cache_hit_reason"] = "cache_backend_error"
        except Exception as exc:
            _log_gemini_cache_backend_error(
                logger,
                source_url=source_url,
                cache_key=cache_key,
                stage="lookup_exception",
                error=exc,
            )
            telemetry["cache_hit_reason"] = "cache_backend_error"
        else:
            telemetry["cache_size_bytes"] = cache_size_bytes
            telemetry["cache_hit_reason"] = hit_reason
            if cached is not None:
                hit_kind = _classify_gemini_cache_hit_kind(
                    cache_key=cache_key,
                    cached_value=cached,
                    hit_reason=hit_reason,
                    expected_model=GEMINI_CACHE_MODEL_NAME,
                )
                telemetry["cache_hit"] = True
                telemetry["cache_hit_kind"] = hit_kind
                telemetry["gemini_call_made"] = False
                _llm_call_dedupe.record_gemini_cache_outcome(
                    cache_hit_reason=hit_reason,
                    hit_kind=hit_kind,
                    post_id=_resolve_cache_metric_post_id(candidate_meta),
                    content_hash=cache_key.content_hash,
                    prompt_template_id=cache_key.prompt_template_id,
                    source_url_hash=cache_key.source_url_hash,
                    now=now,
                )
                _llm_call_dedupe.record_cache_hit_metric(
                    hit_kind=hit_kind,
                    post_id=_resolve_cache_metric_post_id(candidate_meta),
                    content_hash=cache_key.content_hash,
                    prompt_template_id=cache_key.prompt_template_id,
                    model=GEMINI_CACHE_MODEL_NAME,
                    cached_model=cached.model,
                    source_url_hash=cache_key.source_url_hash,
                    cache_hit_reason=hit_reason,
                    layer="gemini_cache",
                    now=now,
                )
                _log_gemini_cache_lookup(
                    logger,
                    source_url=source_url,
                    cache_key=cache_key,
                    cache_hit=True,
                    cache_hit_reason=hit_reason,
                    cache_hit_kind=hit_kind,
                    gemini_call_made=False,
                    cache_size_bytes=cache_size_bytes,
                )
                return cached.generated_text, telemetry
            _llm_call_dedupe.record_gemini_cache_outcome(
                cache_hit_reason="miss",
                hit_kind="unknown",
                post_id=budget_post_id,
                content_hash=cache_key.content_hash,
                prompt_template_id=cache_key.prompt_template_id,
                source_url_hash=cache_key.source_url_hash,
                now=now,
            )
            breaker_state = _llm_call_dedupe.evaluate_gemini_cache_miss_breaker(now=now)
            telemetry["cache_miss_breaker"] = breaker_state
            if breaker_state.get("tripped"):
                skip_reason = _llm_call_dedupe.GEMINI_CACHE_MISS_BREAKER_SKIP_REASON
                telemetry["gemini_call_made"] = False
                telemetry["skip_reason"] = skip_reason
                if breaker_state.get("skip_reason_payload"):
                    telemetry["skip_reason_payload"] = breaker_state.get("skip_reason_payload")
                telemetry["skip_layer"] = PREFLIGHT_SKIP_LAYER
                duplicate_guard_context = (
                    candidate_meta.get("duplicate_guard_context")
                    if isinstance(candidate_meta, dict)
                    else None
                )
                if isinstance(duplicate_guard_context, dict):
                    duplicate_guard_context.setdefault("postgame_strict_review_reason", skip_reason)
                if preflight_candidate is None:
                    preflight_candidate = {
                        "post_url": source_url,
                        "source_url": source_url,
                        "source_url_hash": cache_key.source_url_hash,
                        "content_hash": cache_key.content_hash,
                        "article_subtype": (
                            str(candidate_meta.get("article_subtype") or "").strip()
                            if isinstance(candidate_meta, dict)
                            else ""
                        ),
                    }
                _log_gemini_cache_miss_breaker(
                    logger,
                    source_url=source_url,
                    cache_key=cache_key,
                    breaker_state=breaker_state,
                )
                emit_gemini_call_skipped(logger, candidate=preflight_candidate, skip_reason=skip_reason)
                _record_preflight_skip_history(
                    logger,
                    candidate=preflight_candidate,
                    skip_reason=skip_reason,
                )
                _log_gemini_cache_lookup(
                    logger,
                    source_url=source_url,
                    cache_key=cache_key,
                    cache_hit=False,
                    cache_hit_reason="miss",
                    cache_hit_kind="unknown",
                    gemini_call_made=False,
                    cache_size_bytes=cache_size_bytes,
                )
                return "", telemetry

    budget_state = _llm_call_dedupe.evaluate_per_post_24h_gemini_budget(
        budget_post_id,
        now=now,
    )
    telemetry["per_post_24h_gemini_budget"] = budget_state
    if budget_state.get("tripped"):
        skip_reason = _llm_call_dedupe.PER_POST_24H_GEMINI_BUDGET_SKIP_REASON
        telemetry["gemini_call_made"] = False
        telemetry["skip_reason"] = skip_reason
        telemetry["skip_layer"] = PREFLIGHT_SKIP_LAYER
        duplicate_guard_context = (
            candidate_meta.get("duplicate_guard_context")
            if isinstance(candidate_meta, dict)
            else None
        )
        if isinstance(duplicate_guard_context, dict):
            duplicate_guard_context.setdefault("postgame_strict_review_reason", skip_reason)
        if preflight_candidate is None:
            preflight_candidate = {
                "post_id": budget_post_id,
                "post_url": source_url,
                "source_url": source_url,
                "source_url_hash": cache_key.source_url_hash,
                "content_hash": cache_key.content_hash,
                "article_subtype": (
                    str(candidate_meta.get("article_subtype") or "").strip()
                    if isinstance(candidate_meta, dict)
                    else ""
                ),
            }
        _log_per_post_24h_gemini_budget(
            logger,
            post_id=budget_post_id,
            source_url=source_url,
            cache_key=cache_key,
            budget_state=budget_state,
        )
        emit_gemini_call_skipped(logger, candidate=preflight_candidate, skip_reason=skip_reason)
        _record_preflight_skip_history(
            logger,
            candidate=preflight_candidate,
            skip_reason=skip_reason,
        )
        _log_gemini_cache_lookup(
            logger,
            source_url=source_url,
            cache_key=cache_key,
            cache_hit=False,
            cache_hit_reason=str(telemetry.get("cache_hit_reason") or "miss"),
            cache_hit_kind=str(telemetry.get("cache_hit_kind") or "unknown"),
            gemini_call_made=False,
            cache_size_bytes=int(telemetry.get("cache_size_bytes") or 0),
        )
        return "", telemetry

    effective_attempt_limit = attempt_limit
    if budget_state.get("enabled") and budget_state.get("applicable"):
        effective_attempt_limit = min(
            attempt_limit,
            int(budget_state.get("remaining_calls") or 0),
        )

    text = _request_gemini_strict_text(
        api_key=api_key,
        prompt=prompt,
        logger=logger,
        attempt_limit=effective_attempt_limit,
        min_chars=min_chars,
        log_label=log_label,
        source_url=source_url or None,
        budget_post_id=budget_post_id,
        budget_content_hash=cache_key.content_hash,
        budget_prompt_template_id=cache_key.prompt_template_id,
        budget_source_url_hash=cache_key.source_url_hash,
        budget_record_enabled=bool(budget_state.get("enabled") and budget_state.get("applicable")),
        now=now,
    )

    if cache_manager is not None and cache_key.source_url_hash and cache_key.prompt_template_id and text:
        try:
            telemetry["cache_size_bytes"] = _gemini_cache_save(
                cache_key,
                generated_text=text,
                cache_manager=cache_manager,
                now=now,
            )
        except Exception as exc:
            _log_gemini_cache_backend_error(
                logger,
                source_url=source_url,
                cache_key=cache_key,
                stage="save",
                error=exc,
            )

    _log_gemini_cache_lookup(
        logger,
        source_url=source_url,
        cache_key=cache_key,
        cache_hit=False,
        cache_hit_reason=str(telemetry.get("cache_hit_reason") or "miss"),
        cache_hit_kind=str(telemetry.get("cache_hit_kind") or "unknown"),
        gemini_call_made=True,
        cache_size_bytes=int(telemetry.get("cache_size_bytes") or 0),
    )
    if telemetry["cache_hit_reason"] == "cache_disabled":
        telemetry["cache_hit_reason"] = "cache_disabled"
    elif telemetry["cache_hit_reason"] != "cache_backend_error":
        telemetry["cache_hit_reason"] = "miss"
    return text, telemetry


def _emit_llm_cost_with_observability(
    logger: logging.Logger,
    debug_site: str,
    **emit_kwargs,
) -> None:
    lane = str(emit_kwargs.get("lane") or "")
    call_site = str(emit_kwargs.get("call_site") or "")
    logger.debug(
        "llm_cost emit start: debug_site=%s lane=%s call_site=%s",
        debug_site,
        lane,
        call_site,
    )
    try:
        from src import llm_cost_emitter as _llm_cost

        _llm_cost.emit_llm_cost(**emit_kwargs)
    except Exception as e:
        logger.warning("llm_cost emit failed at %s: %s", debug_site, e)
        raise
    logger.debug(
        "llm_cost emit done: debug_site=%s lane=%s call_site=%s",
        debug_site,
        lane,
        call_site,
    )


