def _rule_based_source_day_is_current(source_day_label: str) -> bool:
    label = (source_day_label or "").strip()
    if not label:
        return True
    match = _re.search(r"(\d{1,2})月(\d{1,2})日", label)
    if not match:
        return True
    now = datetime.now(JST)
    return int(match.group(1)) == now.month and int(match.group(2)) == now.day


def _clip_rule_based_fact(text: str, limit: int = 200) -> str:
    clean = _collapse_ws(_strip_html(text or "")).strip()
    if not clean:
        return ""
    if len(clean) <= limit:
        return clean
    return clean[:limit].rstrip(" 、。") + "…"


def _rule_based_fact_ok(text: str) -> bool:
    clean = _collapse_ws(_strip_html(text or "")).strip()
    if not clean:
        return False
    return not any(marker in clean for marker in RULE_BASED_SPECULATION_MARKERS)


def _rule_based_fact_lines(title: str, summary: str, max_sentences: int = 5, limit: int = 120) -> list[str]:
    lines = []
    for sentence in _extract_source_sentences(title, summary, max_sentences=max_sentences):
        clipped = _clip_rule_based_fact(sentence, limit=limit)
        if clipped and _rule_based_fact_ok(clipped):
            lines.append(clipped.rstrip("。"))
    return _dedupe_preserve_order(lines)


def _extract_rule_based_date_label(text: str, fallback: str = "") -> str:
    if fallback:
        return fallback
    for regex in (DATE_JP_TOKEN_RE, DATE_SLASH_TOKEN_RE):
        match = regex.search(text or "")
        if match:
            return match.group(0)
    return ""


def _extract_rule_based_program_channel(text: str) -> str:
    for marker in RULE_BASED_PROGRAM_CHANNEL_MARKERS:
        if marker in text:
            return marker
    return ""


def _extract_rule_based_program_name(title: str, summary: str, channel: str = "") -> str:
    quoted = _extract_quote_phrases(f"{title}\n{summary}", max_phrases=1)
    if quoted:
        return f"{channel}「{quoted[0]}」" if channel else quoted[0]
    clean_title = _clip_rule_based_fact(_strip_title_prefix(title), limit=80)
    clean_title = _re.sub(r"[（(]?(?:\d{1,2}月\d{1,2}日|\d{1,2}/\d{1,2}).*$", "", clean_title).strip("　 -")
    return clean_title


def _extract_rule_based_program_schedule_label(text: str) -> str:
    date_label = _extract_rule_based_date_label(text)
    time_match = PROGRAM_TIME_TOKEN_RE.search(text or "")
    if date_label and time_match:
        return f"{date_label} {time_match.group(0)}"
    if date_label:
        return date_label
    if time_match and any(keyword in text for keyword in RULE_BASED_PROGRAM_KEYWORDS):
        return time_match.group(0)
    return ""


def _extract_rule_based_program_hosts(title: str, summary: str) -> list[str]:
    text = _strip_html(f"{title} {summary}")
    hosts = []
    for match in RULE_BASED_PROGRAM_PERSON_RE.finditer(text):
        host = match.group(1).strip()
        host = _re.sub(r"^[でがにはをともへ]+(?=[一-龥々ァ-ヴー])", "", host)
        if host:
            hosts.append(host)
    return _dedupe_preserve_order([host.strip() for host in hosts if host.strip()])[:5]


def _looks_like_rule_based_program_story(title: str, summary: str) -> bool:
    text = _strip_html(f"{title} {summary}")
    text_lower = text.lower()
    if _is_promotional_video_entry(title, summary):
        return True
    return (
        any(keyword in text for keyword in RULE_BASED_PROGRAM_KEYWORDS)
        or any(keyword in text_lower for keyword in ("program", "broadcast", "tv", "hulu", "dazn"))
    )


def _resolve_rule_based_target_subtype(
    *,
    title: str,
    summary: str,
    generation_category: str,
    article_subtype: str,
    special_story_kind: str = "",
    source_type: str = "news",
) -> str:
    resolved_subtype = str(article_subtype or "").strip().lower()
    if resolved_subtype == "lineup":
        return "lineup"
    if special_story_kind == "player_notice" and generation_category == "選手情報":
        return "notice"
    if source_type != "social_news" and _looks_like_rule_based_program_story(title, summary):
        return "program"
    return ""


def _render_lineup_rule_based(
    *,
    title: str,
    summary: str,
    source_url: str,
    source_day_label: str = "",
    lineup_rows: list[dict] | None = None,
) -> str | None:
    if source_day_label and not _rule_based_source_day_is_current(source_day_label):
        return None

    source_text = _strip_html(f"{title} {summary}")
    headings = _game_required_headings("lineup")
    game_date = _extract_rule_based_date_label(source_text, fallback=source_day_label)
    opponent = _extract_game_opponent_label(source_text)
    stadium = _extract_game_venue_label(source_text)
    start_time = _extract_game_time_token(source_text)
    starter_lines = _dedupe_lineup_starter_lines(
        [line.rstrip("。") for line in _extract_game_pitcher_lines(title, summary) if _rule_based_fact_ok(line)]
    )
    overview_facts = _rule_based_fact_lines(title, summary, max_sentences=3, limit=100)

    lineup_table: list[str] = []
    focus_lines: list[str] = []
    for row in lineup_rows or []:
        order = str(row.get("order") or "").strip()
        name = str(row.get("name") or "").strip()
        position = str(row.get("position") or "").strip()
        if not order or not name:
            continue
        line = f"{order}番 {name}"
        if position:
            line += f" {position}"
        lineup_table.append(line.strip())
        if order in {"1", "4", "9"}:
            focus_lines.append(line.strip())

    if not lineup_table:
        for fact in overview_facts:
            if LINEUP_ORDER_SLOT_RE.search(fact):
                lineup_table.append(fact)

    if not lineup_table and not starter_lines:
        return None

    overview_lines = [headings[0]]
    details = [item for item in (game_date, f"{opponent}戦" if opponent else "", stadium, f"{start_time}開始" if start_time else "") if item]
    if details:
        overview_lines.append(" / ".join(details))
    overview_lines.extend(f"{fact}。" for fact in overview_facts[:2] if not LINEUP_ORDER_SLOT_RE.search(fact))
    if len(overview_lines) == 1:
        overview_lines.append("巨人の試合前情報です。")

    lineup_section = [headings[1]]
    lineup_section.extend(lineup_table[:9])

    starter_section = [headings[2]]
    starter_section.extend(f"{line}。" for line in starter_lines[:3])
    if len(starter_section) == 1:
        starter_section.append("先発投手の確定情報は元記事で確認できる範囲に限ります。")

    focus_section = [headings[3]]
    for line in _dedupe_preserve_order(focus_lines)[:3]:
        focus_section.append(f"{line}。")
    if not any(line != headings[3] for line in focus_section):
        for fact in overview_facts:
            if fact not in lineup_table:
                focus_section.append(f"{fact}。")
            if len(focus_section) >= 3:
                break
    if source_url:
        focus_section.append(f"出典: {source_url}")
    return "\n".join(overview_lines + lineup_section + starter_section + focus_section)


def _render_program_rule_based(
    *,
    title: str,
    summary: str,
    source_url: str,
) -> str | None:
    source_text = _strip_html(f"{title} {summary}")
    channel = _extract_rule_based_program_channel(source_text)
    schedule_label = _extract_rule_based_program_schedule_label(source_text)
    program_name = _extract_rule_based_program_name(title, summary, channel=channel)
    hosts = _extract_rule_based_program_hosts(title, summary)
    highlights = [
        fact for fact in _rule_based_fact_lines(title, summary, max_sentences=5, limit=120)
        if fact != program_name and fact != schedule_label
    ]
    if not program_name or not schedule_label:
        return None
    if not (channel or hosts or highlights):
        return None

    sections = ["【番組概要】"]
    sections.append(f"番組名は{program_name}です。")
    if channel:
        sections.append(f"媒体は{channel}です。")
    sections.append("【放送・配信日時】")
    sections.append(f"放送・配信日時は{schedule_label}です。")
    if channel:
        sections.append(f"配信先は{channel}です。")
    sections.append("【出演・見どころ】")
    if hosts:
        sections.append("出演者: " + " / ".join(hosts[:5]))
    for fact in highlights[:3]:
        sections.append(f"{fact}。")
    sections.append("【視聴メモ】")
    if source_url:
        sections.append(f"出典: {source_url}")
    return "\n".join(sections)


def _render_notice_rule_based(
    *,
    title: str,
    summary: str,
    source_url: str,
    source_name: str = "",
    source_day_label: str = "",
) -> str | None:
    source_text = _strip_html(f"{title} {summary}")
    notice_subject, notice_type = _extract_notice_subject_and_type(title, summary)
    player_position = _extract_notice_player_position(title, summary, notice_subject) or "選手"
    notice_date = _extract_rule_based_date_label(source_text, fallback=source_day_label)
    notice_fact = _find_source_sentence_with_markers(
        title,
        summary,
        ("登録", "抹消", "合流", "復帰", "昇格", "戦力外", "再出発"),
    )
    notice_fact = _clip_rule_based_fact(notice_fact, limit=200)
    if not _rule_based_fact_ok(notice_fact):
        notice_fact = ""
    record_fact = _clip_rule_based_fact(_extract_notice_record_fact(title, summary), limit=120)
    if not _rule_based_fact_ok(record_fact):
        record_fact = ""
    background_fact = _clip_rule_based_fact(
        _extract_notice_background_fact(
            title,
            summary,
            exclude={fact for fact in (notice_fact, record_fact) if fact},
        ),
        limit=160,
    )
    if not _rule_based_fact_ok(background_fact) or background_fact == notice_fact:
        background_fact = ""

    if not notice_type or not notice_date:
        return None
    if not notice_subject:
        notice_subject = "対象選手"
    if not notice_fact:
        return None

    source_label = _display_source_name(source_name) if source_name else ""
    notice_headings = _notice_required_headings()

    sections = [notice_headings[0]]
    opening = f"（{source_day_label}時点）" if source_day_label else ""
    sections.append(f"{opening}{notice_subject}が{notice_type}となりました。".strip())
    sections.append(f"公示日は{notice_date}です。")
    sections.append(f"{notice_fact}。")
    if source_label:
        sections.append(f"報道 source は{source_label}です。")

    sections.append(notice_headings[1])
    sections.append(f"{notice_subject}は読売ジャイアンツの{player_position}です。")
    if record_fact:
        sections.append(f"{record_fact}。")

    sections.append(notice_headings[2])
    sections.append(f"{background_fact or notice_fact}。")

    sections.append(notice_headings[3])
    sections.append(_notice_next_focus_sentence(notice_type, player_position, notice_subject))
    if source_url:
        sections.append(f"出典: {source_url}")
    return "\n".join(sections)


def _is_short_source_narrow_template_candidate(source_text: str, body_subtype: str) -> bool:
    if not _short_source_narrow_template_enabled():
        return False
    if body_subtype not in SHORT_SOURCE_NARROW_TEMPLATE_SUBTYPES:
        return False
    return len(_collapse_ws(_strip_html(source_text or ""))) < SHORT_SOURCE_NARROW_TEMPLATE_MAX_CHARS


def _is_farm_short_post_template_candidate(source_text: str, body_subtype: str) -> bool:
    if not _farm_short_post_template_enabled():
        return False
    if body_subtype != "farm":
        return False
    return len(_collapse_ws(_strip_html(source_text or ""))) < SHORT_SOURCE_NARROW_TEMPLATE_MAX_CHARS


def _is_source_link_only_template_candidate(source_text: str, body_subtype: str) -> bool:
    if not _source_link_only_template_enabled():
        return False
    if body_subtype not in SOURCE_LINK_ONLY_TEMPLATE_SUBTYPES:
        return False
    return len(_collapse_ws(_strip_html(source_text or ""))) < SOURCE_LINK_ONLY_TEMPLATE_MAX_CHARS


def _short_source_comment_prompt(body_subtype: str) -> str:
    mapping = {
        "player_notice": "今回の動きが次の起用にどうつながるか、コメントで教えてください。",
        "player_recovery": "復帰時期や次の実戦で見たい点を、コメントで教えてください。",
        "social_news": "この発信の受け止め方や次に見たい動きを、コメントで教えてください。",
        "farm": "この内容が一軍昇格や次の起用にどうつながるか、コメントで教えてください。",
        "roster": "この補強・移籍情報をどう見るか、コメントで教えてください。",
    }
    return mapping.get(body_subtype, "続報で見たい点をコメントで教えてください。")


def _build_farm_short_post_body(
    *,
    title: str,
    summary: str,
    source_url: str,
    source_name: str = "",
) -> str | None:
    headings = _farm_required_headings("farm")
    if not headings:
        return None

    source_label = _display_source_name(source_name) if source_name else "元投稿"
    subject = _compact_subject_label(title, summary, "ドラフト・育成") or "対象選手"
    raw_gist = _clean_social_entry_text(_strip_title_prefix(title) or summary or title)
    gist = _clip_rule_based_fact(raw_gist, limit=68)
    replacements = (
        ("２軍", "ファーム"),
        ("二軍", "ファーム"),
        ("2軍", "ファーム"),
        ("ホームスチール", "本塁突入"),
    )
    for old, new in replacements:
        gist = gist.replace(old, new)
    if subject and subject != "対象選手":
        gist = gist.replace(subject, "このプレー")
    gist = gist.strip("。 ・\t")
    if not gist:
        gist = "ファームで起きたプレー場面の共有"

    sections = [
        headings[0],
        f"{source_label}のXが、ファームで起きたプレー場面を短く共有しました。",
        f"要点: {gist}。",
        headings[1],
        f"{subject}が関わったプレーの判断と流れが、この投稿の見どころです。",
        headings[2],
        "投稿で確認できる事実は短文の共有範囲に限り、追加成績は広げません。",
        headings[3],
        f"{subject}が次の出場機会でどんな内容を続けるか気になります。",
    ]
    if source_url:
        sections.append(f"出典: {source_url}")
    return "\n".join(sections)


def _first_body_content_line(body_text: str) -> str:
    for line in str(body_text or "").splitlines():
        stripped = line.strip()
        if stripped and not (stripped.startswith("【") and "】" in stripped):
            return stripped
    return ""


def _body_final_section_has_close_marker(body_text: str) -> bool:
    sections = _split_text_sections(body_text)
    final_section_text = sections[-1][1] if sections else _collapse_ws(_strip_html(body_text or ""))
    return any(marker in final_section_text for marker in POST_GEN_CLOSE_MARKERS)


def _should_prefer_source_link_only_template(
    *,
    title: str,
    body_text: str,
) -> bool:
    if not body_text:
        return True
    if not _body_final_section_has_close_marker(body_text):
        return True
    if find_duplicate_sentence(body_text):
        return True
    first_line = _first_body_content_line(body_text)
    if first_line and _body_dup_reduction_ngram_overlap(title, first_line) >= 0.55:
        return True
    return False


def _source_link_only_template_contract_ok(body_text: str, body_subtype: str) -> tuple[bool, list[str]]:
    if body_subtype == "manager":
        return _manager_body_has_required_structure(body_text, False), ["manager_required_headings"]
    return _short_source_narrow_template_contract_ok(body_text, body_subtype)


def _build_source_link_only_body(
    *,
    title: str,
    summary: str,
    body_subtype: str,
    source_url: str,
    source_name: str = "",
    source_day_label: str = "",
) -> str | None:
    if body_subtype == "manager":
        headings = _manager_required_headings()
        speaker_label = _extract_subject_label(title, summary, "首脳陣") or "ベンチ"
        lead_line = f"{speaker_label}の発言が短く伝えられました。"
        background_line = "元記事にある発言の範囲だけを短く確認します。"
        close_line = "この言葉が次の起用にどう出るかを見たいところです。"
    elif body_subtype == "player_notice":
        headings = _notice_required_headings()
        subject = _compact_subject_label(title, summary, "選手情報") or "対象選手"
        lead_line = f"{subject}に関する公示情報が短く共有されました。"
        background_line = "元記事にある公示内容だけを短く確認します。"
        close_line = "次の公示や起用の変化を見たいところです。"
    elif body_subtype == "player_recovery":
        headings = _recovery_required_headings()
        subject = _compact_subject_label(title, summary, "選手情報") or "対象選手"
        lead_line = f"{subject}の状態変化が短く共有されました。"
        background_line = "元記事にある状態変化だけを短く確認します。"
        close_line = "次の実戦で状態がどう出るかを見たいところです。"
    elif body_subtype == "farm":
        headings = _farm_required_headings("farm")
        subject = _compact_subject_label(title, summary, "ドラフト・育成")
        lead_line = (
            f"{subject}に関するファーム情報が短く共有されました。"
            if subject and subject not in {"巨人", "対象選手"}
            else "ファームの動きが短く共有されました。"
        )
        background_line = "元記事にある範囲だけを短く確認します。"
        close_line = "この内容が次の起用にどうつながるかを見たいところです。"
    else:
        return None

    if not headings:
        return None

    quote_phrases = _extract_quote_phrases(f"{title}\n{summary}", max_phrases=1)
    fact_lines = _rule_based_fact_lines(title, summary, max_sentences=2, limit=72)
    fact_line = fact_lines[0] if fact_lines else _clip_rule_based_fact(_strip_title_prefix(title) or summary or title, limit=72)
    if quote_phrases:
        source_line = f"引用: 「{quote_phrases[0]}」。"
    elif fact_line:
        source_line = f"要点: {fact_line.rstrip('。')}。"
    else:
        source_label = _display_source_name(source_name) if source_name else "元記事"
        source_line = f"{source_label}が伝えた要点だけを短く確認します。"

    opening_prefix = f"（{source_day_label}時点）" if source_day_label else ""
    sections = [
        headings[0],
        f"{opening_prefix}{lead_line}".strip(),
        headings[1],
        source_line,
        headings[2],
        background_line,
        headings[3],
        close_line,
    ]
    if source_url:
        sections.append(f"出典: {source_url}")
    return "\n".join(sections)


def _build_short_source_narrow_body(
    *,
    title: str,
    summary: str,
    category: str,
    body_subtype: str,
    source_url: str,
    source_name: str = "",
    source_day_label: str = "",
) -> str | None:
    facts = _rule_based_fact_lines(title, summary, max_sentences=4, limit=110)
    source_text = _strip_html(f"{title} {summary}")
    quote_phrases = _extract_quote_phrases(f"{title}\n{summary}", max_phrases=1)
    source_label = _display_source_name(source_name) if source_name else "元記事"
    prefix = f"（{source_day_label}時点）" if source_day_label else ""

    if body_subtype == "player_notice":
        notice_subject, notice_type = _extract_notice_subject_and_type(title, summary)
        if not facts:
            return None
        headings = _notice_required_headings()
        sections = [
            headings[0],
            f"{prefix}{facts[0]}。".strip(),
            headings[1],
            f"{notice_subject or '対象選手'}に関する公示・登録情報です。",
            headings[2],
            f"{quote_phrases[0]}。"
            if quote_phrases
            else f"{facts[1]}。" if len(facts) > 1 else f"{source_label}が伝えた範囲で整理します。",
            headings[3],
            f"{notice_type or '今回の動き'}の続報と実際の起用を見ていきたいところです。",
            _short_source_comment_prompt(body_subtype),
        ]
        if source_url:
            sections.append(f"出典: {source_url}")
        return "\n".join(sections)

    if body_subtype == "player_recovery":
        recovery_subject = _compact_subject_label(title, summary, category) or "対象選手"
        if not facts:
            return None
        headings = _recovery_required_headings()
        sections = [
            headings[0],
            f"{prefix}{facts[0]}。".strip(),
            headings[1],
            f"{facts[1]}。" if len(facts) > 1 else f"{recovery_subject}の状態変化として確認できる要点です。",
            headings[2],
            f"{quote_phrases[0]}。"
            if quote_phrases
            else f"{facts[2]}。" if len(facts) > 2 else f"{source_label}が伝えた範囲で復帰見通しを整理します。",
            headings[3],
            f"{recovery_subject}が次の実戦でどこまで状態を戻せるかが注目点です。",
            _short_source_comment_prompt(body_subtype),
        ]
        if source_url:
            sections.append(f"出典: {source_url}")
        return "\n".join(sections)

    if body_subtype == "social_news":
        social_headings = _social_required_headings()
        if not facts:
            facts = [_strip_title_prefix(title) or "X投稿で伝えられた内容"]
        sections = [
            social_headings[0],
            f"{prefix}{facts[0]}。".strip(),
            social_headings[1],
            f"{quote_phrases[0]}。"
            if quote_phrases
            else f"{facts[1]}。" if len(facts) > 1 else f"{source_label}の投稿要点を短く整理します。",
            social_headings[2],
            f"{facts[2]}。" if len(facts) > 2 else f"{source_label}が発信した範囲に限って整理します。",
            social_headings[3],
            _short_source_comment_prompt(body_subtype),
        ]
        if source_url:
            sections.append(f"出典: {source_url}")
        return "\n".join(sections)

    if body_subtype == "farm":
        headings = _farm_required_headings("farm")
        if not headings:
            return None
        if not facts:
            facts = [_strip_title_prefix(title) or "ファーム情報"]
        sections = [
            headings[0],
            f"{prefix}{facts[0]}。".strip(),
            headings[1],
            f"{facts[1]}。" if len(facts) > 1 else "ファームで確認できたプレーを短く整理します。",
            headings[2],
            f"{facts[2]}。" if len(facts) > 2 else f"{source_label}が伝えた範囲で個別の動きを確認します。",
            headings[3],
            _short_source_comment_prompt(body_subtype),
        ]
        if source_url:
            sections.append(f"出典: {source_url}")
        return "\n".join(sections)

    if body_subtype == "roster":
        headings = _article_section_headings("補強・移籍", False)
        facts = facts or [_strip_title_prefix(title) or "補強・移籍情報"]
        sections = [
            headings[0],
            f"{prefix}{facts[0]}。".strip(),
            headings[1],
            f"{quote_phrases[0]}。"
            if quote_phrases
            else f"{facts[1]}。" if len(facts) > 1 else f"{source_label}が伝えた要点を整理します。",
            headings[2],
            _short_source_comment_prompt(body_subtype),
        ]
        if source_url:
            sections.append(f"出典: {source_url}")
        return "\n".join(sections)

    return None


def _short_source_narrow_template_contract_ok(body_text: str, body_subtype: str) -> tuple[bool, list[str]]:
    if body_subtype == "player_notice":
        return _notice_body_has_required_structure(body_text), ["notice_required_headings"]
    if body_subtype == "player_recovery":
        return _recovery_body_has_required_structure(body_text), ["recovery_required_headings"]
    if body_subtype == "social_news":
        return _social_body_has_required_structure(body_text), ["social_required_headings"]
    if body_subtype == "farm":
        return _farm_body_has_required_structure(body_text, "farm"), ["farm_required_headings"]
    if body_subtype == "roster":
        sections = _split_text_sections(body_text)
        return len(sections) >= 3, ["roster_short_sections"]
    return False, ["unsupported_body_subtype"]


def _maybe_build_short_source_narrow_body(
    *,
    title: str,
    summary: str,
    category: str,
    body_subtype: str,
    source_url: str,
    source_name: str,
    source_day_label: str,
    logger: logging.Logger,
) -> str | None:
    source_text = f"{title} {summary}"
    source_length = len(_collapse_ws(_strip_html(source_text)))

    if _is_farm_short_post_template_candidate(source_text, body_subtype):
        body_text = _build_farm_short_post_body(
            title=title,
            summary=summary,
            source_url=source_url,
            source_name=source_name,
        )
        if body_text and _farm_body_has_required_structure(body_text, "farm"):
            logger.info(
                json.dumps(
                    {
                        "event": "farm_short_post_template_used",
                        "severity": "INFO",
                        "source_url": source_url,
                        "source_length": source_length,
                        "subtype": body_subtype,
                        "body_length": len(body_text),
                    },
                    ensure_ascii=False,
                )
            )
            return body_text

    if _is_short_source_narrow_template_candidate(source_text, body_subtype):
        body_text = _build_short_source_narrow_body(
            title=title,
            summary=summary,
            category=category,
            body_subtype=body_subtype,
            source_url=source_url,
            source_name=source_name,
            source_day_label=source_day_label,
        )
        if body_text:
            contract_ok, fail_axes = _short_source_narrow_template_contract_ok(body_text, body_subtype)
            if contract_ok and not (
                _is_source_link_only_template_candidate(source_text, body_subtype)
                and _should_prefer_source_link_only_template(title=title, body_text=body_text)
            ):
                logger.info(
                    json.dumps(
                        {
                            "event": "short_source_narrow_template_used",
                            "severity": "INFO",
                            "subtype": body_subtype,
                            "source_length": source_length,
                            "body_length": len(body_text),
                        },
                        ensure_ascii=False,
                    )
                )
                return body_text
            if not _is_source_link_only_template_candidate(source_text, body_subtype):
                logger.warning(
                    json.dumps(
                        {
                            "event": "short_template_blocked_by_contract",
                            "severity": "WARNING",
                            "subtype": body_subtype,
                            "source_length": source_length,
                            "body_length": len(body_text),
                            "fail_axes": fail_axes,
                        },
                        ensure_ascii=False,
                    )
                )
                return None

    if not _is_source_link_only_template_candidate(source_text, body_subtype):
        return None

    source_link_only_body = _build_source_link_only_body(
        title=title,
        summary=summary,
        body_subtype=body_subtype,
        source_url=source_url,
        source_name=source_name,
        source_day_label=source_day_label,
    )
    if not source_link_only_body:
        return None
    contract_ok, fail_axes = _source_link_only_template_contract_ok(source_link_only_body, body_subtype)
    if not contract_ok:
        logger.warning(
            json.dumps(
                {
                    "event": "short_template_blocked_by_contract",
                    "severity": "WARNING",
                    "subtype": body_subtype,
                    "source_length": source_length,
                    "body_length": len(source_link_only_body),
                    "fail_axes": fail_axes,
                },
                ensure_ascii=False,
            )
        )
        return None
    logger.info(
        json.dumps(
            {
                "event": "source_link_only_template_used",
                "severity": "INFO",
                "source_url": source_url,
                "source_length": source_length,
                "subtype": body_subtype,
                "body_length": len(source_link_only_body),
            },
            ensure_ascii=False,
        )
    )
    return source_link_only_body


def _build_rule_based_subtype_body(
    *,
    title: str,
    summary: str,
    generation_category: str,
    article_subtype: str,
    special_story_kind: str = "",
    source_url: str = "",
    source_name: str = "",
    source_day_label: str = "",
    source_type: str = "news",
    lineup_rows: list[dict] | None = None,
) -> tuple[str, str] | None:
    target_subtype = _resolve_rule_based_target_subtype(
        title=title,
        summary=summary,
        generation_category=generation_category,
        article_subtype=article_subtype,
        special_story_kind=special_story_kind,
        source_type=source_type,
    )
    if not _should_use_rule_based(target_subtype):
        return None

    body = None
    if target_subtype == "lineup":
        body = _render_lineup_rule_based(
            title=title,
            summary=summary,
            source_url=source_url,
            source_day_label=source_day_label,
            lineup_rows=lineup_rows,
        )
    elif target_subtype == "program":
        body = _render_program_rule_based(
            title=title,
            summary=summary,
            source_url=source_url,
        )
    elif target_subtype == "notice":
        body = _render_notice_rule_based(
            title=title,
            summary=summary,
            source_url=source_url,
            source_name=source_name,
            source_day_label=source_day_label,
        )
    if not body:
        return None
    return target_subtype, body


def _log_rule_based_subtype_skip_gemini(
    logger: logging.Logger,
    *,
    subtype: str,
    source_url: str,
    input_chars: int,
    output_chars: int,
    saved_gemini_calls: int = 3,
    template_version: str = RULE_BASED_SUBTYPE_TEMPLATE_VERSION,
) -> None:
    payload = {
        "event": "rule_based_subtype_skip_gemini",
        "subtype": str(subtype or "").strip().lower(),
        "source_url_hash": _hash_duplicate_guard_value(source_url),
        "input_chars": int(input_chars or 0),
        "output_chars": int(output_chars or 0),
        "saved_gemini_calls": int(saved_gemini_calls or 0),
        "rule_based_template_version": template_version,
        "timestamp": datetime.now(timezone.utc).isoformat(),
    }
    logger.info(json.dumps(payload, ensure_ascii=False))


def _article_reads_too_generic(text: str, category: str) -> bool:
    if category != "選手情報":
        return False
    clean = _strip_html(text or "")
    hit_count = sum(1 for marker in GENERIC_PLAYER_ARTICLE_MARKERS if marker in clean)
    return hit_count >= 1


def infer_article_has_game(title: str, summary: str, category: str, daily_has_game: bool) -> bool:
    text = f"{_strip_html(title)} {_strip_html(summary)}"
    if category == "試合速報":
        return True
    if SCORE_TOKEN_RE.search(text):
        return True
    if any(keyword in text for keyword in GAME_ARTICLE_KEYWORDS):
        return True
    return daily_has_game and any(marker in text for marker in ("vs", "VS", "対"))


def _find_unverified_number_tokens(text: str, allowed_tokens: set[str]) -> list[str]:
    found = []
    for token in _extract_number_tokens(text):
        normalized = _normalize_number_token(token)
        token_variants = _expand_number_token_variants(normalized)
        if token_variants.isdisjoint(allowed_tokens):
            found.append(normalized)

    deduped = []
    seen = set()
    for token in found:
        if token not in seen:
            seen.add(token)
            deduped.append(token)
    return deduped


def _text_has_fake_citation(text: str) -> bool:
    return any(marker in text for marker in FAKE_CITATION_MARKERS)


def _source_has_confirmed_result(title: str, summary: str) -> bool:
    source_text = _strip_html(f"{title} {summary}")
    if _has_explicit_confirmed_result(source_text):
        return True
    return bool(SCORE_TOKEN_RE.search(source_text))


def _is_pregame_article(title: str, summary: str, category: str, has_game: bool) -> bool:
    return bool(category == "試合速報" and has_game and not _source_has_confirmed_result(title, summary))


def _text_guardrail_flags(title: str, summary: str, text: str, has_game: bool) -> dict:
    allowed_tokens = _collect_allowed_number_tokens(title, summary)
    clean_text = text.strip()
    source_has_result = _source_has_confirmed_result(title, summary)
    source_mentions_outcome = _source_mentions_outcome_terms(title, summary)
    return {
        "unverified_numbers": _find_unverified_number_tokens(clean_text, allowed_tokens),
        "bad_score": bool(
            (not has_game)
            and (not source_mentions_outcome)
            and (SCORE_TOKEN_RE.search(clean_text) or any(word in clean_text for word in NON_GAME_RESULT_WORDS))
        ),
        "fake_citation": bool(_text_has_fake_citation(clean_text)),
        "fabricated_result": bool((not source_has_result) and any(marker in clean_text for marker in DEFINITE_RESULT_MARKERS)),
    }


def _text_is_safe(title: str, summary: str, text: str, has_game: bool) -> bool:
    flags = _text_guardrail_flags(title, summary, text, has_game)
    return not (flags["unverified_numbers"] or flags["bad_score"] or flags["fake_citation"] or flags["fabricated_result"])


def _apply_article_guardrails(title: str, summary: str, category: str, article_text: str, has_game: bool, logger: logging.Logger) -> str:
    if not article_text:
        return ""

    clean_text = article_text.strip()
    flags = _text_guardrail_flags(title, summary, clean_text, has_game)

    if flags["unverified_numbers"] or flags["bad_score"] or flags["fake_citation"] or flags["fabricated_result"]:
        logger.warning(
            "記事ガードレール発動: %s",
            {
                "category": category,
                "unverified_numbers": flags["unverified_numbers"][:8],
                "bad_score": flags["bad_score"],
                "fake_citation": flags["fake_citation"],
                "fabricated_result": flags["fabricated_result"],
            },
        )
        return _build_safe_article_fallback(title, summary, category, has_game)
    return clean_text


def _split_text_sections(text: str) -> list[tuple[str, str]]:
    clean_lines = [line.strip() for line in (text or "").splitlines() if line.strip()]
    if not clean_lines:
        return []

    sections: list[tuple[str, str]] = []
    current_heading = ""
    current_lines: list[str] = []
    for line in clean_lines:
        if line.startswith("【") and "】" in line:
            if current_heading or current_lines:
                sections.append((current_heading, "\n".join(current_lines).strip()))
            current_heading = line
            current_lines = []
            continue
        current_lines.append(line)
    if current_heading or current_lines:
        sections.append((current_heading, "\n".join(current_lines).strip()))
    return sections


def _body_dup_reduction_sentence_units(text: str) -> list[str]:
    parts = _re.split(r"(?<=[。！？!?])\s*", _collapse_ws(text or ""))
    return [part.strip() for part in parts if part.strip()]


def _body_dup_reduction_ngram_overlap(left: str, right: str, size: int = 3) -> float:
    left_norm = _normalize_title_for_dedupe(left)
    right_norm = _normalize_title_for_dedupe(right)
    if len(left_norm) < size or len(right_norm) < size:
        return 0.0
    left_ngrams = {left_norm[index:index + size] for index in range(len(left_norm) - size + 1)}
    right_ngrams = {right_norm[index:index + size] for index in range(len(right_norm) - size + 1)}
    if not left_ngrams or not right_ngrams:
        return 0.0
    return len(left_ngrams & right_ngrams) / max(len(left_ngrams), 1)


def _body_lead_title_ngrams(text: str, size: int = 3) -> list[str]:
    normalized = _normalize_title_for_dedupe(text).replace(" ", "")
    if len(normalized) < size:
        return []
    return _dedupe_preserve_order(
        [
            normalized[index:index + size]
            for index in range(len(normalized) - size + 1)
            if normalized[index:index + size].strip()
        ]
    )


def _body_lead_overlap_ngrams(title: str, sentence: str, size: int = 3) -> list[str]:
    sentence_norm = _normalize_title_for_dedupe(sentence).replace(" ", "")
    if not sentence_norm:
        return []
    return [ngram for ngram in _body_lead_title_ngrams(title, size=size) if ngram in sentence_norm]


def _body_lead_has_source_quote(sentence: str, quote_phrases: list[str]) -> bool:
    clean = _collapse_ws(sentence or "")
    if not clean or not quote_phrases:
        return False
    return any(phrase in clean for phrase in quote_phrases)


def _body_lead_paraphrase_generic_sentence(
    *,
    source_title: str,
    summary: str,
    category: str,
    article_subtype: str,
    source_name: str = "",
) -> str:
    source_label = _display_source_name(source_name) if source_name else "元記事"
    subject = _compact_subject_label(source_title, summary, category) or _extract_subject_label(source_title, summary, category)
    normalized_subtype = str(article_subtype or "").strip().lower()

    if normalized_subtype == "manager":
        speaker = subject if subject and subject not in {"巨人", "首脳陣"} else "首脳陣"
        return f"{speaker}の発言が伝えられました。"
    if normalized_subtype == "player_notice":
        player = subject if subject and subject not in {"巨人", "対象選手"} else "対象選手"
        return f"{player}に関する公示の要点が伝えられました。"
    if normalized_subtype == "player_recovery":
        player = subject if subject and subject not in {"巨人", "対象選手"} else "対象選手"
        return f"{player}の状態変化が伝えられました。"
    if normalized_subtype == "farm":
        if subject and subject not in {"巨人", "対象選手"}:
            return f"{subject}に関するファーム情報が伝えられました。"
        return "ファームの動きが伝えられました。"
    if normalized_subtype == "roster":
        return f"{source_label}が補強・移籍の要点を伝えました。"
    if category == "試合速報":
        return "巨人戦のポイントが伝えられました。"
    if subject and subject not in {"巨人", "対象選手", "首脳陣"}:
        return f"{source_label}が{subject}に関する話題を伝えました。"
    return f"{source_label}が話題の要点を伝えました。"


def _body_lead_paraphrase_candidates(
    *,
    article_title: str,
    source_title: str,
    summary: str,
    category: str,
    article_subtype: str,
    source_name: str,
    first_sentence: str,
) -> tuple[list[str], bool]:
    fact_lines = _rule_based_fact_lines(source_title, summary, max_sentences=4, limit=72)
    quote_phrases = _extract_quote_phrases(f"{source_title}\n{summary}", max_phrases=1)
    fact_candidates: list[str] = []
    for fact in fact_lines[1:] + fact_lines[:1]:
        sentence = f"{fact.rstrip('。')}。".strip()
        if not sentence or sentence == first_sentence:
            continue
        if _body_dup_reduction_ngram_overlap(article_title, sentence) >= 0.55:
            continue
        fact_candidates.append(sentence)

    if quote_phrases and not fact_candidates and _body_lead_has_source_quote(first_sentence, quote_phrases):
        return [], True

    candidates = list(fact_candidates)
    if quote_phrases:
        quote_sentence = f"引用: 「{quote_phrases[0]}」。"
        if quote_sentence != first_sentence and _body_dup_reduction_ngram_overlap(article_title, quote_sentence) < 0.55:
            candidates.append(quote_sentence)

    generic_sentence = _body_lead_paraphrase_generic_sentence(
        source_title=source_title,
        summary=summary,
        category=category,
        article_subtype=article_subtype,
        source_name=source_name,
    )
    if generic_sentence != first_sentence and _body_dup_reduction_ngram_overlap(article_title, generic_sentence) < 0.55:
        candidates.append(generic_sentence)

    return _dedupe_preserve_order(candidates), False


def _player_manager_subjective_lead(sentence: str, category: str) -> bool:
    if category not in {"選手情報", "首脳陣"}:
        return False
    clean = _collapse_ws(_strip_html(sentence or ""))
    if not clean:
        return False
    subjective_markers = (
        "笑みはない",
        "闘志",
        "宿っていた",
        "見どころ",
        "追っていきたい",
        "見たいところ",
        "本気度",
        "腹をくくって",
    )
    return any(marker in clean for marker in subjective_markers)


def _maybe_apply_body_lead_paraphrase_guard(
    *,
    body_text: str,
    article_title: str,
    source_title: str,
    summary: str,
    category: str,
    article_subtype: str,
    source_name: str,
    source_url: str,
    logger: logging.Logger,
) -> str:
    if not _body_lead_paraphrase_guard_enabled():
        return body_text
    sections = _split_text_sections(body_text)
    if not sections:
        return body_text
    first_heading, first_body = sections[0]
    sentences = _body_dup_reduction_sentence_units(first_body)
    if not sentences:
        return body_text
    first_sentence = sentences[0]
    subjective_lead = _player_manager_subjective_lead(first_sentence, category)
    if _body_dup_reduction_ngram_overlap(article_title, first_sentence) < 0.55 and not subjective_lead:
        return body_text
    overlap_ngrams = _body_lead_overlap_ngrams(article_title, first_sentence)[:12]
    if not overlap_ngrams and not subjective_lead:
        return body_text

    candidates, quote_only = _body_lead_paraphrase_candidates(
        article_title=article_title,
        source_title=source_title,
        summary=summary,
        category=category,
        article_subtype=article_subtype,
        source_name=source_name,
        first_sentence=first_sentence,
    )
    if quote_only or not candidates:
        return body_text

    replacement = candidates[0]
    if replacement == first_sentence:
        return body_text

    if subjective_lead:
        filtered_sentences = [replacement]
        for sentence in sentences[1:]:
            if _player_manager_subjective_lead(sentence, category):
                continue
            filtered_sentences.append(sentence)
        sentences = filtered_sentences
    else:
        sentences[0] = replacement
    sections[0] = (first_heading, " ".join(sentences).strip())
    rebuilt_lines: list[str] = []
    for heading, section_body in sections:
        if heading:
            rebuilt_lines.append(heading)
        if section_body:
            rebuilt_lines.extend(line.strip() for line in section_body.splitlines() if line.strip())
    guarded_body = "\n".join(rebuilt_lines)
    logger.info(
        json.dumps(
            {
                "event": "body_lead_paraphrase_avoided",
                "source_url": source_url,
                "subtype": article_subtype,
                "title_ngrams_excluded": overlap_ngrams,
                "body_lead_length": len(replacement),
            },
            ensure_ascii=False,
        )
    )
    return guarded_body


def _sentence_duplicates_title_or_heading(sentence: str, title: str, headings: list[str]) -> bool:
    sentence_norm = _normalize_title_for_dedupe(sentence)
    if not sentence_norm:
        return False
    title_norm = _normalize_title_for_dedupe(title)
    if title_norm and (sentence_norm in title_norm or title_norm in sentence_norm):
        return True
    if title_norm and _body_dup_reduction_ngram_overlap(sentence, title) >= 0.55:
        return True
    for heading in headings:
        heading_norm = _normalize_title_for_dedupe(_collapse_ws(heading).strip("【】"))
        if not heading_norm:
            continue
        if heading_norm in sentence_norm:
            return True
        if _body_dup_reduction_ngram_overlap(sentence, heading_norm) >= 0.6:
            return True
    return False


def _maybe_reduce_body_intro_dup(
    *,
    body_text: str,
    article_title: str,
    article_subtype: str,
    logger: logging.Logger,
) -> str:
    if not _body_dup_reduction_enabled():
        return body_text
    sections = _split_text_sections(body_text)
    if not sections:
        return body_text
    removed_sentences: list[str] = []
    updated_sections = list(sections)
    for index, (heading, section_body) in enumerate(sections):
        sentences = _body_dup_reduction_sentence_units(section_body)
        if len(sentences) < 2:
            continue
        heading_candidates = [heading] if heading else []
        while len(sentences) > 1 and _sentence_duplicates_title_or_heading(sentences[0], article_title, heading_candidates):
            removed_sentences.append(sentences.pop(0))
        updated_sections[index] = (heading, " ".join(sentences).strip())
    if not removed_sentences:
        return body_text
    rebuilt_lines: list[str] = []
    for heading, section_body in updated_sections:
        if heading:
            rebuilt_lines.append(heading)
        if section_body:
            rebuilt_lines.extend(line.strip() for line in section_body.splitlines() if line.strip())
    reduced_body = "\n".join(rebuilt_lines)
    removed_chars = len(" ".join(removed_sentences))
    if removed_chars > 0:
        logger.info(
            json.dumps(
                {
                    "event": "body_dup_reduction_applied",
                    "severity": "INFO",
                    "subtype": article_subtype,
                    "removed_chars": removed_chars,
                },
                ensure_ascii=False,
            )
        )
    return reduced_body


def _render_preview_body_html(text: str) -> str:
    lines = [line.strip() for line in str(text or "").splitlines() if line.strip()]
    if not lines:
        return ""
    blocks: list[str] = []
    heading_index = 0
    rendered_h3_count = 0
    for line in lines:
        escaped = (
            line.replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
        )
        if line.startswith("【") and "】" in line:
            level, rendered_h3_count = _resolved_rendered_heading_level(line, heading_index, rendered_h3_count)
            blocks.append(f"<h{level}>{escaped}</h{level}>")
            heading_index += 1
            continue
        blocks.append(f"<p>{escaped}</p>")
    return "\n".join(blocks)


def _log_entity_mismatch_repair_applied(
    logger: logging.Logger,
    *,
    source_url: str,
    source_title: str,
    original_title: str,
    repaired_title: str,
    repair_flags: tuple[str, ...],
    removed_strings: tuple[str, ...],
) -> None:
    payload = {
        "event": "entity_mismatch_repair_applied",
        "source_url": source_url,
        "source_title": source_title,
        "original_title": original_title,
        "repaired_title": repaired_title,
        "repair_flags": list(repair_flags),
        "removed_strings": list(removed_strings),
    }
    logger.info(json.dumps(payload, ensure_ascii=False))


def _maybe_apply_entity_mismatch_repair(
    *,
    title: str,
    body_text: str,
    body_html: str,
    source_title: str,
    source_summary: str,
    article_subtype: str,
    source_refs: dict[str, object] | None = None,
    logger: logging.Logger | None = None,
    source_url: str = "",
) -> dict[str, object] | None:
    if not _env_flag(ENTITY_MISMATCH_REPAIR_ENV_FLAG, False):
        return None
    repair = repair_entity_mismatch(
        current_title=title,
        body_text=body_text,
        body_html=body_html,
        source_title=source_title,
        source_summary=source_summary,
    )
    if not repair.applied:
        return {
            "applied": False,
            "repairable": repair.repairable,
            "stop_reason": repair.stop_reason,
            "title": title,
            "body_text": body_text,
            "body_html": body_html,
            "validation": {
                "ok": False,
                "fail_axes": [f"entity_mismatch_repair:{repair.stop_reason or repair.reason}"],
                "stop_reason": repair.stop_reason or repair.reason,
            },
            "repair_flags": repair.repair_flags,
            "removed_strings": repair.removed_strings,
        }
    repaired_preview_html = _render_preview_body_html(repair.body_text)
    validation = _evaluate_post_gen_validate(
        repair.body_text,
        article_subtype=article_subtype,
        title=repair.title,
        source_refs=source_refs,
        rendered_html=repaired_preview_html,
    )
    repaired_entity_axis = f"entity_mismatch:{repair.reason}"
    if repaired_entity_axis in validation["fail_axes"]:
        filtered_fail_axes = [axis for axis in validation["fail_axes"] if axis != repaired_entity_axis]
        validation = dict(validation)
        validation["fail_axes"] = filtered_fail_axes
        validation["ok"] = not filtered_fail_axes
        if not filtered_fail_axes:
            validation["stop_reason"] = ""
        elif validation.get("stop_reason") == repaired_entity_axis:
            validation["stop_reason"] = filtered_fail_axes[0]
    if validation["ok"] and logger is not None:
        _log_entity_mismatch_repair_applied(
            logger,
            source_url=source_url,
            source_title=source_title,
            original_title=title,
            repaired_title=repair.title,
            repair_flags=repair.repair_flags,
            removed_strings=repair.removed_strings,
        )
    return {
        "applied": validation["ok"],
        "repairable": repair.repairable,
        "stop_reason": repair.stop_reason,
        "title": repair.title,
        "body_text": repair.body_text,
        "body_html": repair.body_html,
        "validation": validation,
        "repair_flags": repair.repair_flags,
        "removed_strings": repair.removed_strings,
    }


def _evaluate_post_gen_validate(
    text: str,
    article_subtype: str = "",
    title: str = "",
    source_refs: dict[str, object] | None = None,
    rendered_html: str = "",
) -> dict[str, object]:
    raw_text = text or ""
    clean_text = _collapse_ws(_strip_html(raw_text))
    title_text = _collapse_ws(_strip_html(title or ""))
    fail_axes: list[str] = []
    source_refs = source_refs or {}

    def _append_fail_axis(axis: str) -> None:
        if axis not in fail_axes:
            fail_axes.append(axis)

    if any(clean_text.startswith(prefix) for prefix in POST_GEN_INTRO_ECHO_PREFIXES):
        _append_fail_axis("intro_echo")

    sections = _split_text_sections(text)
    final_section_text = sections[-1][1] if sections else clean_text
    # RSS-257: lineup と x_short_player (短文 X 選手記事 subtype) は close_marker
    # 必須を免除。長文 template の締め句 contract に従えない短文構造のため。
    close_marker_exempt_subtypes = {"lineup"} | X_SHORT_TEMPLATE_SUBTYPES
    if article_subtype not in close_marker_exempt_subtypes and not any(
        marker in final_section_text for marker in POST_GEN_CLOSE_MARKERS
    ):
        _append_fail_axis("close_marker")

    normalized_headings: list[str] = []
    if article_subtype in NON_LINEUP_STARMEN_GUARD_SUBTYPES or article_subtype == "live_update":
        heading_candidates = [heading for heading, _body in sections if heading]
        heading_candidates.extend(
            match
            for match in _re.findall(r"<h[23][^>]*>(.*?)</h[23]>", raw_text, flags=_re.IGNORECASE | _re.DOTALL)
            if match
        )
        normalized_headings = [
            _collapse_ws(_strip_html(heading)).strip("【】")
            for heading in heading_candidates
            if heading and _collapse_ws(_strip_html(heading))
        ]

    if article_subtype in NON_LINEUP_STARMEN_GUARD_SUBTYPES:
        if _starts_with_starmen_prefix(title_text):
            _append_fail_axis("starmen_title_prefix")
        if any(_starts_with_starmen_prefix(heading) for heading in normalized_headings):
            _append_fail_axis("starmen_heading_prefix")

    if article_subtype == "live_update":
        if any(any(keyword in heading for keyword in LIVE_UPDATE_LINEUP_HEADING_KEYWORDS) for heading in normalized_headings):
            _append_fail_axis("live_update_lineup_heading")
        batting_order_markers = {match.group(0) for match in _re.finditer(r"[1-9１-９]番", clean_text)}
        has_lineup_table = "<table" in raw_text.lower() and any(keyword in clean_text for keyword in LIVE_UPDATE_LINEUP_HEADING_KEYWORDS)
        if has_lineup_table or len(batting_order_markers) >= 4:
            _append_fail_axis("live_update_lineup_structure")

    if article_subtype == "lineup":
        lineup_tokens: list[str] = []
        for key in ("opponent", "scoreline"):
            value = _collapse_ws(_strip_html(str(source_refs.get(key) or "")))
            if value:
                lineup_tokens.append(value)

        source_title_text = _collapse_ws(_strip_html(str(source_refs.get("source_title") or "")))
        source_summary_text = _collapse_ws(_strip_html(str(source_refs.get("source_summary") or source_refs.get("summary") or "")))
        context_text = "\n".join(part for part in (title_text, source_title_text, source_summary_text) if part)
        score_match = _re.search(r"\d{1,2}\s*[－\-–]\s*\d{1,2}", context_text)
        if score_match:
            lineup_tokens.append(score_match.group(0))
        opponent_match = _re.search(r"(阪神|中日|ヤクルト|広島|DeNA|ＤｅＮＡ|横浜|日本ハム|ソフトバンク|楽天|ロッテ|西武|オリックス)", context_text)
        if opponent_match:
            lineup_tokens.append(opponent_match.group(1))

        fact_conflict_payload = {
            "title": title_text,
            "body_text": clean_text,
            "game_id": str(source_refs.get("game_id") or "").strip(),
            "scoreline": str(source_refs.get("scoreline") or "").strip(),
            "team_result": str(source_refs.get("team_result") or "").strip(),
            "opponent": str(source_refs.get("opponent") or "").strip(),
            "required_tokens": tuple(dict.fromkeys(token for token in lineup_tokens if token)),
        }
        if _detect_no_game_but_result(fact_conflict_payload, source_refs):
            _append_fail_axis("NO_GAME_BUT_RESULT")
        if _detect_game_result_conflict(fact_conflict_payload, source_refs):
            _append_fail_axis("GAME_RESULT_CONFLICT")
        if _detect_title_body_entity_mismatch(title_text, fact_conflict_payload):
            _append_fail_axis("TITLE_BODY_ENTITY_MISMATCH")

    # RSS-257: lineup_table_heavy + x_short_template の両方を template-formatted
    # validator の skip 対象とする (長文 template gate を 短文 X subtype で発動させない)。
    short_template_skip = (
        article_subtype in LINEUP_TABLE_HEAVY_SUBTYPES
        or article_subtype in X_SHORT_TEMPLATE_SUBTYPES
    )
    lineup_table_heavy = short_template_skip  # 既存名 keep (h3_count_guard 側でも使用)
    if _env_flag(ENABLE_FORBIDDEN_PHRASE_FILTER_ENV_FLAG, False):
        forbidden_hit = find_forbidden_phrase(raw_text)
        if forbidden_hit:
            _append_fail_axis(f"forbidden_phrase:{forbidden_hit['label']}")
        if not lineup_table_heavy:
            placeholder_markers = (
                "元記事の内容を確認中です",
                "確認できる範囲を押さえておきたい",
                "この話題で押さえるべき論点を整理します",
            )
            for heading, body_text in sections:
                normalized_body = _collapse_ws(_strip_html(body_text))
                if heading and not normalized_body:
                    _append_fail_axis("placeholder_body:empty_section")
                    break
                if heading and any(marker in normalized_body for marker in placeholder_markers):
                    _append_fail_axis("placeholder_body:boilerplate")
                    break

    if _env_flag(ENABLE_QUOTE_INTEGRITY_GUARD_ENV_FLAG, False):
        quote_issue = find_quote_integrity_issue(raw_text)
        if quote_issue:
            _append_fail_axis(f"quote_integrity:{quote_issue['reason']}")

    if _env_flag(ENABLE_DUPLICATE_SENTENCE_GUARD_ENV_FLAG, False):
        duplicate_issue = find_duplicate_sentence(raw_text)
        if duplicate_issue:
            _append_fail_axis(f"duplicate_sentence:{duplicate_issue['reason']}")

    if _env_flag(ENABLE_H3_COUNT_GUARD_ENV_FLAG, False) and not lineup_table_heavy:
        excessive_h3 = find_excessive_h3(rendered_html or _render_preview_body_html(raw_text))
        if excessive_h3:
            _append_fail_axis(f"h3_count:{excessive_h3['reason']}")

    if _env_flag(ENABLE_ACTIVE_TEAM_MISMATCH_GUARD_ENV_FLAG, False):
        entity_conflict = detect_source_entity_conflict(
            str(source_refs.get("source_title") or source_refs.get("title") or ""),
            str(source_refs.get("source_summary") or source_refs.get("summary") or ""),
        )
        if entity_conflict:
            _append_fail_axis(f"entity_mismatch:{entity_conflict['reason']}")

    if _source_grounding_drift_repair_enabled():
        source_title = str(source_refs.get("source_title") or source_refs.get("title") or "")
        source_summary = str(source_refs.get("source_summary") or source_refs.get("summary") or "")
        if source_title or source_summary:
            grounding_issues = _find_source_grounding_drift_issues(
                raw_text,
                source_title=source_title,
                source_summary=source_summary,
                category_hint=_source_grounding_category_hint(article_subtype, source_refs),
            )
            for reason in dict.fromkeys(str(issue.get("reason") or "") for issue in grounding_issues):
                if reason:
                    _append_fail_axis(f"source_grounding_drift:{reason}")

    stop_reason = ""
    if any(axis.startswith("starmen_") for axis in fail_axes):
        stop_reason = "starmen_prefix_guard"
    elif any(axis.startswith("live_update_") for axis in fail_axes):
        stop_reason = "live_update_lineup_guard"
    elif fail_axes:
        stop_reason = fail_axes[0]

    return {
        "ok": not fail_axes,
        "fail_axes": fail_axes,
        "final_section_heading": sections[-1][0] if sections else "",
        "final_section_text": final_section_text,
        "stop_reason": stop_reason,
    }


def _log_article_skipped_post_gen_validate(
    logger: logging.Logger,
    *,
    title: str,
    source_title: str = "",
    post_url: str,
    category: str,
    article_subtype: str,
    fail_axes: list[str],
    stop_reason: str = "",
):
    normalized_fail_axes = [str(axis).strip() for axis in fail_axes if str(axis).strip()]
    skip_reason = ""
    if normalized_fail_axes and normalized_fail_axes[0].startswith(("weak_subject_title:", "weak_generated_title:")):
        skip_reason = normalized_fail_axes[0]
    elif stop_reason:
        skip_reason = str(stop_reason).strip()
    elif normalized_fail_axes:
        skip_reason = normalized_fail_axes[0]
    payload = {
        "event": "article_skipped_post_gen_validate",
        "post_id": None,
        "title": title,
        "post_url": post_url,
        "category": category,
        "article_subtype": article_subtype,
        "fail_axis": normalized_fail_axes,
        "skip_layer": POST_GEN_VALIDATE_SKIP_LAYER,
        "source_url_hash": _hash_duplicate_guard_value(post_url),
    }
    if stop_reason:
        payload["stop_reason"] = stop_reason
    if source_title:
        payload["source_title"] = source_title
    if skip_reason:
        payload["skip_reason"] = skip_reason
    if _fetcher_log_sampling_v1_enabled():
        first_axis = (
            normalized_fail_axes[0]
            if normalized_fail_axes
            else (skip_reason or stop_reason or "unknown")
        )
        first_axis_key = str(first_axis).split(":", 1)[0] or "unknown"
        bucket_key = f"{article_subtype or 'unknown'}|{first_axis_key}"
        _record_article_skipped_sample(bucket_key, title or source_title or post_url)
    else:
        logger.info(json.dumps(payload, ensure_ascii=False))
    _record_post_gen_validate_skip_history(
        logger,
        source_url=post_url,
        source_title=source_title,
        generated_title=title,
        category=category,
        article_subtype=article_subtype,
        fail_axes=normalized_fail_axes,
        skip_reason=skip_reason,
    )


def _preflight_skip_notification_enabled() -> bool:
    return _env_flag(PREFLIGHT_SKIP_NOTIFICATION_ENV_FLAG, False)


def _resolve_preflight_skip_history_path() -> Path:
    raw = str(os.environ.get(PREFLIGHT_SKIP_LEDGER_PATH_ENV, "")).strip()
    if raw:
        return Path(raw)
    return PREFLIGHT_SKIP_HISTORY_DEFAULT_PATH


def _append_preflight_skip_gcs_record(record_line: str, logger: logging.Logger) -> None:
    client = _gcs_client()
    if client is None:
        return
    try:
        from google.api_core.exceptions import PreconditionFailed
    except Exception:
        PreconditionFailed = None

    bucket = client.bucket(PREFLIGHT_SKIP_STATE_BUCKET)
    blob = bucket.blob(PREFLIGHT_SKIP_STATE_KEY)
    for _ in range(4):
        try:
            if blob.exists():
                blob.reload()
                generation = int(blob.generation or 0)
                existing_payload = blob.download_as_text(encoding="utf-8")
            else:
                generation = 0
                existing_payload = ""
            next_payload = existing_payload
            if next_payload and not next_payload.endswith("\n"):
                next_payload += "\n"
            next_payload += f"{record_line}\n"
            blob.upload_from_string(
                next_payload,
                content_type="application/x-ndjson",
                if_generation_match=generation if generation else 0,
            )
            return
        except Exception as exc:
            if PreconditionFailed is not None and isinstance(exc, PreconditionFailed):
                continue
            logger.warning(
                json.dumps(
                    {
                        "event": "preflight_skip_history_gcs_append_failed",
                        "record_type": PREFLIGHT_SKIP_RECORD_TYPE,
                        "skip_layer": PREFLIGHT_SKIP_LAYER,
                        "reason": type(exc).__name__,
                    },
                    ensure_ascii=False,
                )
            )
            return


def _record_preflight_skip_history(
    logger: logging.Logger,
    *,
    candidate: dict[str, Any],
    skip_reason: str,
) -> None:
    if not _preflight_skip_notification_enabled():
        return
    source_url = str(candidate.get("source_url") or candidate.get("post_url") or "").strip()
    source_title = str(candidate.get("source_title") or candidate.get("title") or "").strip()
    source_url_hash = str(candidate.get("source_url_hash") or "").strip() or _hash_duplicate_guard_value(source_url)
    record = {
        "ts": datetime.now(JST).isoformat(),
        "record_type": PREFLIGHT_SKIP_RECORD_TYPE,
        "skip_layer": PREFLIGHT_SKIP_LAYER,
        "source_url": source_url,
        "source_url_hash": source_url_hash,
        "content_hash": str(candidate.get("content_hash") or "").strip(),
        "source_title": source_title,
        "category": str(candidate.get("category") or "").strip(),
        "article_subtype": str(candidate.get("article_subtype") or "").strip(),
        "source_name": str(candidate.get("source_name") or "").strip(),
        "source_type": str(candidate.get("source_type") or "").strip(),
        "published_at": (
            candidate.get("published_at").isoformat()
            if isinstance(candidate.get("published_at"), datetime)
            else str(candidate.get("published_at") or "").strip()
        ),
        "has_game": bool(candidate.get("has_game")),
        "skip_reason": str(skip_reason or "").strip(),
    }
    if candidate.get("existing_publish_same_source_url") is not None:
        record["existing_publish_same_source_url"] = bool(candidate.get("existing_publish_same_source_url"))
    history_path = _resolve_preflight_skip_history_path()
    try:
        history_path.parent.mkdir(parents=True, exist_ok=True)
        record_line = json.dumps(record, ensure_ascii=False)
        with history_path.open("a", encoding="utf-8") as handle:
            handle.write(record_line)
            handle.write("\n")
    except OSError as exc:
        logger.warning(
            json.dumps(
                {
                    "event": "preflight_skip_history_local_append_failed",
                    "record_type": PREFLIGHT_SKIP_RECORD_TYPE,
                    "skip_layer": PREFLIGHT_SKIP_LAYER,
                    "reason": type(exc).__name__,
                },
                ensure_ascii=False,
            )
        )
        return
    _append_preflight_skip_gcs_record(record_line, logger)


