def _normalize_roster_signal_text(text: str) -> str:
    clean = _strip_html(text or "")
    clean = _html.unescape(clean)
    return _re.sub(r"[\s　【】「」『』〔〕（）()・･．\.,，/／\-ーｰ:：]", "", clean)


@lru_cache(maxsize=1)
def _load_giants_roster() -> tuple[dict, ...]:
    try:
        with open(GIANTS_ROSTER_FILE, encoding="utf-8") as f:
            data = json.load(f)
    except FileNotFoundError:
        return ()
    return tuple(entry for entry in data if isinstance(entry, dict))


@lru_cache(maxsize=1)
def _giants_roster_alias_index() -> tuple[dict, ...]:
    alias_map: dict[str, set[str]] = {}
    for entry in _load_giants_roster():
        name = (entry.get("name") or "").strip()
        if not name:
            continue
        alias_bucket = alias_map.setdefault(name, set())
        aliases = [name] + list(entry.get("aliases") or [])
        for alias in aliases:
            normalized = _normalize_roster_signal_text(alias)
            if len(normalized) < 2:
                continue
            alias_bucket.add(normalized)

    for name, aliases in GIANTS_ROSTER_EXTRA_ALIASES.items():
        alias_bucket = alias_map.setdefault(name, set())
        for alias in aliases:
            normalized = _normalize_roster_signal_text(alias)
            if len(normalized) >= 2:
                alias_bucket.add(normalized)

    index: list[dict] = []
    for name, alias_bucket in alias_map.items():
        normalized_aliases = sorted(alias_bucket, key=len, reverse=True)
        if normalized_aliases:
            index.append(
                {
                    "name": name,
                    "aliases": tuple(sorted(normalized_aliases, key=len, reverse=True)),
                }
            )
    return tuple(index)


def _is_non_giants_mlb_primary_subject(title: str, summary: str) -> str:
    """非元巨人 MLB 選手 (大谷翔平 等) が主役で、巨人 relevance が薄い記事を
    検出して該当選手名を返す。skip 候補なら non-empty。

    skip 回避条件 (いずれか):
      1. 巨人 roster 現役選手が言及されている
      2. EX_GIANTS_OB_MLB (菅野/岡本) が言及されている
      3. NON_GIANTS_MLB_PRIMARY_SUBJECTS の hit 自体が無い

    user lock 2026-05-14 (memory: project_mlb_player_inclusion_policy)
    """
    text = f"{title or ''} {summary or ''}"
    matched = next(
        (name for name in NON_GIANTS_MLB_PRIMARY_SUBJECTS if name in text), ""
    )
    if not matched:
        return ""
    if _matching_giants_roster_names(text):
        return ""
    if any(ob in text for ob in EX_GIANTS_OB_MLB):
        return ""
    return matched


def _matching_giants_roster_names(text: str) -> list[str]:
    normalized_text = _normalize_roster_signal_text(text)
    if not normalized_text:
        return []
    hits: list[str] = []
    for entry in _giants_roster_alias_index():
        if any(alias in normalized_text for alias in entry["aliases"]):
            hits.append(entry["name"])
    return hits


def _match_giants_roster_hashtag_alias(text: str) -> str:
    normalized = _normalize_roster_signal_text(text)
    if len(normalized) < 2:
        return ""
    for entry in _giants_roster_alias_index():
        if normalized in entry["aliases"]:
            return str(entry["name"] or "")
    return ""


def _is_other_team_transfer_story(text: str, roster_hits: list[str]) -> bool:
    if not roster_hits:
        return False
    source_text = text or ""
    if any(marker in source_text for marker in GIANTS_KEYWORDS):
        return False
    if "読売" in source_text:
        return False
    if not any(marker in source_text for marker in NON_GIANTS_TEAM_MARKERS):
        return False
    return any(marker in source_text for marker in GIANTS_TRANSFER_CONTEXT_MARKERS)


def _trusted_social_signal_match(text: str, category: str, article_subtype: str) -> str:
    markers = list(TRUSTED_SOCIAL_REPORTABLE_MARKERS.get(category, ()))
    if article_subtype == "pregame":
        markers.extend(("先発", "予告先発", "スタメン", "打順", "オーダー"))
    for marker in markers:
        if marker in text:
            return marker
    return ""


def _social_too_weak_narrow_rescue_source_key(source_url: str, source_handle: str, source_name: str) -> str:
    source_handle_key = str(source_handle or "").strip().lstrip("@").lower()
    if source_handle_key:
        return source_handle_key
    source_family = _extract_source_family(source_url)
    if source_family and source_family != "unknown":
        return source_family
    raw_url = _html.unescape(str(source_url or "")).strip()
    if raw_url:
        try:
            from urllib.parse import urlparse

            return urlparse(raw_url).netloc.lower()
        except Exception:
            return raw_url.lower()
    normalized_name = _collapse_ws(str(source_name or "")).replace(" ", "").lower()
    return normalized_name


def _social_too_weak_narrow_rescue_keyword_hits(title: str, summary: str, category: str) -> list[str]:
    text = _strip_html(f"{title} {summary}")
    hits: list[str] = []
    subject = _compact_subject_label(title, summary, category)
    if subject and title_has_person_name_candidate(subject):
        hits.append(subject)
    if category == "首脳陣":
        manager_label = _extract_subject_label(title, summary, category)
        if manager_label and manager_label not in {"巨人", "首脳陣"}:
            hits.append(manager_label)
    for keyword in SOCIAL_TOO_WEAK_NARROW_RESCUE_KEYWORDS:
        if keyword in text:
            hits.append(keyword)
    return _dedupe_preserve_order(hits)


def _social_too_weak_narrow_rescue_meta(
    title: str,
    summary: str,
    category: str,
    article_subtype: str,
    *,
    source_url: str = "",
    source_name: str = "",
    source_handle: str = "",
) -> dict | None:
    if not _social_too_weak_narrow_rescue_enabled():
        return None
    source_domain = _social_too_weak_narrow_rescue_source_key(source_url, source_handle, source_name)
    if source_domain not in SOCIAL_TOO_WEAK_NARROW_RESCUE_SOURCE_KEYS:
        return None
    keyword_hits = _social_too_weak_narrow_rescue_keyword_hits(title, summary, category)
    if not keyword_hits:
        return None
    logging.getLogger("rss_fetcher").info(
        json.dumps(
            {
                "event": "social_too_weak_narrow_rescued",
                "severity": "INFO",
                "source_domain": source_domain,
                "keyword_hits": keyword_hits,
                "subtype": article_subtype,
            },
            ensure_ascii=False,
        )
    )
    return {
        "rescue_reason": "social_too_weak_narrow_rescue",
        "matched_word": keyword_hits[0],
        "keyword_hits": keyword_hits,
        "source_domain": source_domain,
    }


def is_giants_related(text: str, source_name: str = "", post_url: str = "") -> bool:
    source_text = text or ""
    if any(kw in source_text for kw in GIANTS_KEYWORDS):
        return True
    if _is_giants_exclusive_social_source(_extract_handle_from_tweet_url(post_url), source_name):
        return True
    roster_hits = _matching_giants_roster_names(source_text)
    if not roster_hits:
        return False
    return not _is_other_team_transfer_story(source_text, roster_hits)


def _is_youtube_post_url(post_url: str) -> bool:
    """344-INGEST: post_url が YouTube 由来かを判定。"""
    if not post_url:
        return False
    url_l = post_url.lower()
    return "youtube.com" in url_l or "youtu.be" in url_l


_YOUTUBE_DRAFT_TITLE_PREFIX = "【YouTube】"


def _maybe_apply_youtube_title_prefix(title: str, source_url: str) -> str:
    """344-INGEST: YouTube source の draft title 先頭に「【YouTube】」prefix を付ける。

    auto-publish 後 mail 件名 / WP admin で即識別可能にし、user の手動編集判断を
    補助する。idempotent (既に prefix あれば 二重付与しない)。
    """
    if not _is_youtube_post_url(source_url):
        return title
    if not title:
        return title
    if title.startswith(_YOUTUBE_DRAFT_TITLE_PREFIX):
        return title
    return _YOUTUBE_DRAFT_TITLE_PREFIX + title


def _extract_youtube_video_id(url: str) -> str:
    """344-INGEST: YouTube URL から video_id を抽出 (youtu.be / watch / shorts / embed)。
    抽出不可なら空文字。"""
    if not url:
        return ""
    try:
        from urllib.parse import urlparse, parse_qs
        parsed = urlparse(url)
        host = (parsed.hostname or "").lower()
        if host in {"youtu.be", "www.youtu.be"}:
            parts = [p for p in parsed.path.split("/") if p]
            return parts[0] if parts else ""
        if host in {"youtube.com", "www.youtube.com", "m.youtube.com", "mobile.youtube.com"}:
            if parsed.path == "/watch":
                return parse_qs(parsed.query).get("v", [""])[0]
            parts = [p for p in parsed.path.split("/") if p]
            if len(parts) >= 2 and parts[0] in {"shorts", "live", "embed", "v"}:
                return parts[1]
    except Exception:  # noqa: BLE001
        return ""
    return ""


def _maybe_append_youtube_caption_section(
    rendered_html: str,
    *,
    source_url: str,
    source_name: str,
    logger: logging.Logger,
) -> str:
    """344-INGEST: YouTube source なら caption literal + 出典 + embed section を末尾に追加。

    additive (本文に追加するのみ、既存 body 削除なし)、idempotent
    (既に nomotoke-youtube-caption marker あれば skip)。
    LLM 不使用、字幕 API call は無料。
    例外時は元 HTML を返して main flow を絶対に壊さない。
    """
    if not _is_youtube_post_url(source_url):
        return rendered_html
    if "nomotoke-youtube-caption" in (rendered_html or ""):
        return rendered_html
    video_id = _extract_youtube_video_id(source_url)
    if not video_id:
        logger.info(
            "youtube_caption_section_skip reason=no_video_id url=%s", source_url
        )
        return rendered_html
    try:
        from src.youtube_caption_fetcher import fetch_youtube_caption
        caption = fetch_youtube_caption(video_id, max_chars=600, logger=logger)
    except Exception as exc:  # noqa: BLE001
        logger.warning(
            "youtube_caption_section_fetch_failed err=%s url=%s",
            exc,
            source_url,
        )
        return rendered_html
    if not caption:
        logger.info(
            "youtube_caption_section_skip reason=no_caption url=%s", source_url
        )
        return rendered_html
    embed_url = f"https://www.youtube.com/embed/{video_id}"
    section = (
        '<aside class="nomotoke-youtube-caption">'
        '<h3>📺 字幕抜粋</h3>'
        '<blockquote class="nomotoke-youtube-caption__body">'
        f'<p>{_html.escape(caption)}</p>'
        '</blockquote>'
        f'<p class="nomotoke-youtube-caption__attr">— '
        f'{_html.escape(source_name or "YouTube")} (字幕より、引用法 32 条範囲内)</p>'
        '<div class="nomotoke-youtube-caption__embed">'
        f'<iframe width="560" height="315" src="{embed_url}" '
        f'frameborder="0" allowfullscreen></iframe>'
        '</div>'
        '</aside>'
    )
    logger.info(
        "youtube_caption_section_appended url=%s video_id=%s caption_len=%d",
        source_url,
        video_id,
        len(caption),
    )
    return rendered_html + section


def _check_youtube_giants_filter(title: str) -> tuple[bool, str]:
    """344-INGEST: YouTube 動画 title が巨人 relevance を持つか判定。

    OB roster 検出を追加した filter (`youtube_title_passes_giants_filter`) を呼ぶ。
    本 helper は import 失敗 / 例外時に空 fallback で main flow を絶対に壊さない。
    """
    try:
        from src.youtube_title_filter import youtube_title_passes_giants_filter
    except Exception:  # noqa: BLE001
        return (False, "import_failed")
    try:
        return youtube_title_passes_giants_filter(
            title,
            giants_roster_matcher=_matching_giants_roster_names,
        )
    except Exception:  # noqa: BLE001
        return (False, "filter_error")

# ──────────────────────────────────────────────────────────
# カテゴリ自動分類
# ──────────────────────────────────────────────────────────
def classify_category(
    text: str,
    keywords: dict,
    *,
    source_url: str = "",
    logger: logging.Logger | None = None,
) -> str:
    source_text = text or ""
    if _is_giants_player_dismissal_story(text):
        return "選手情報"
    if _is_farm_lineup_text(text):
        return "ドラフト・育成"
    if any(marker in text for marker in _farm_category_markers()):
        return "ドラフト・育成"
    for category, kws in keywords.items():
        if any(kw in text for kw in kws):
            if category == "試合速報" and _rss_type_flag_enabled(ENABLE_FARM_CATEGORY_NARROW_FIX_ENV_FLAG):
                farm_keyword_hits = _farm_category_narrow_fix_keyword_hits(source_text)
                if farm_keyword_hits and not _farm_split_first_team_priority_hits(source_text):
                    _emit_rss_story_type_event(
                        logger,
                        "rss_farm_category_rerouted",
                        source_url,
                        pre_category=category,
                        post_category="ドラフト・育成",
                        farm_keyword_hits=farm_keyword_hits,
                    )
                    return "ドラフト・育成"
            return category
    return "コラム"


def _resolve_draft_category_ids(
    wp: WPClient,
    category: str,
    logger: logging.Logger | None = None,
) -> list[int]:
    requested_category = (category or "").strip() or DRAFT_CATEGORY_FALLBACK_NAME
    category_names = [requested_category]
    if requested_category != DRAFT_CATEGORY_FALLBACK_NAME:
        category_names.append(DRAFT_CATEGORY_FALLBACK_NAME)

    for index, category_name in enumerate(category_names):
        category_id = int(wp.resolve_category_id(category_name) or 0)
        if not category_id:
            continue
        if index > 0 and logger is not None:
            logger.warning(
                "draft category fallback applied requested=%s fallback=%s",
                requested_category,
                category_name,
            )
        return [category_id]

    raise ValueError(
        f"draft category resolution failed requested={requested_category} fallback={DRAFT_CATEGORY_FALLBACK_NAME}"
    )


def _evaluate_authoritative_social_entry(
    title: str,
    summary: str,
    category: str,
    article_subtype: str,
    source_name: str = "",
    source_handle: str = "",
    source_url: str = "",
) -> tuple[bool, dict | None]:
    text = _strip_html(f"{title} {summary}")
    trusted_source = _is_trusted_social_source(source_handle, source_name)
    if _is_promotional_video_entry(title, summary) or any(marker in text for marker in SOCIAL_VIDEO_SKIP_MARKERS):
        return False, None
    has_quote = "「" in text and "」" in text

    if article_subtype in {"lineup", "farm_lineup", "postgame"}:
        return True, None
    if article_subtype == "live_update":
        return ENABLE_LIVE_UPDATE_ARTICLES, None
    if category in {"首脳陣", "選手情報"} and has_quote:
        return True, None
    if category == "選手情報":
        matched_keyword = _first_matching_keyword(text, SOCIAL_PLAYER_NOTICE_RESCUE_KEYWORDS)
        if matched_keyword:
            return True, {
                "rescue_reason": "player_notice_keyword",
                "matched_word": matched_keyword,
            }
    if category == "ドラフト・育成" and "２軍" in text:
        return True, {
            "rescue_reason": "zenkaku_2gun",
            "matched_word": "２軍",
        }
    if category == "試合速報":
        matched_keyword = _first_matching_keyword(text, SOCIAL_GAME_NOTICE_RESCUE_KEYWORDS)
        if matched_keyword:
            return True, {
                "rescue_reason": "game_notice_keyword",
                "matched_word": matched_keyword,
            }
    if category == "試合速報" and any(keyword in text for keyword in ("先発", "登録", "昇格", "抹消", "公示", "打順", "オーダー", "ベンチ入り")):
        return True, None
    if category == "コラム":
        rescue_reason, matched_word = _match_social_column_rescue(text)
        if rescue_reason and matched_word:
            return True, {
                "rescue_reason": rescue_reason,
                "matched_word": matched_word,
            }
    if category == "補強・移籍" and any(keyword in text for keyword in ("獲得", "移籍", "トレード", "加入", "退団")):
        return True, None
    narrow_rescue_meta = _social_too_weak_narrow_rescue_meta(
        title,
        summary,
        category,
        article_subtype,
        source_url=source_url,
        source_name=source_name,
        source_handle=source_handle,
    )
    if narrow_rescue_meta:
        return True, narrow_rescue_meta
    if trusted_source:
        matched_signal = _trusted_social_signal_match(text, category, article_subtype)
        if matched_signal:
            return True, {
                "rescue_reason": "trusted_social_source",
                "matched_word": matched_signal,
            }
    giants_rescue_meta = _evaluate_trusted_social_giants_rescue(
        title=title,
        summary=summary,
        category=category,
        article_subtype=article_subtype,
        source_url=source_url,
        source_name=source_name,
        source_handle=source_handle,
    )
    if giants_rescue_meta:
        return True, giants_rescue_meta
    return False, None


def _is_authoritative_social_entry_worthy(title: str, summary: str, category: str, article_subtype: str) -> bool:
    worthy, _rescue_meta = _evaluate_authoritative_social_entry(title, summary, category, article_subtype)
    return worthy


def _log_sns_weak_rescue(
    logger: logging.Logger,
    source_url: str,
    title: str,
    rescue_meta: dict | None,
) -> None:
    if not rescue_meta:
        return
    payload = {
        "event": "sns_weak_rescued",
        "rescue_reason": rescue_meta.get("rescue_reason", ""),
        "source_url": source_url,
        "title": title,
        "matched_word": rescue_meta.get("matched_word", ""),
    }
    logger.info(json.dumps(payload, ensure_ascii=False))

# ──────────────────────────────────────────────────────────
# タイトル生成（投稿内容の先頭40字）
# ──────────────────────────────────────────────────────────
def make_title(entry) -> str:
    text = entry.get("title", "") or entry.get("summary", "")
    # HTMLタグ除去
    import re
    text = re.sub(r"<[^>]+>", "", text).strip()
    text = text[:40].strip()
    return text if text else f"X投稿 {datetime.now().strftime('%Y-%m-%d')}"


def _prepare_source_title_context(entry_title_clean: str, entry: dict | None = None) -> tuple[str, str]:
    raw_title = entry_title_clean.strip() if entry_title_clean else make_title(entry or {})
    raw_title = _strip_html(raw_title).strip()
    preview_title = raw_title[:40].strip() if raw_title else ""
    return raw_title, preview_title or raw_title


def _clean_display_title_text(text: str) -> str:
    clean = _strip_html(text or "")
    clean = _re.sub(r"^【[^】]+】", "", clean).strip()
    clean = _re.sub(r"\s+", " ", clean)
    return clean.strip("。 ")


def _short_subject_name(title: str, summary: str, category: str) -> str:
    subject = _extract_subject_label(title, summary, category)
    return _re.sub(r"(投手|捕手|内野手|外野手|監督|コーチ)$", "", subject).strip()


def _trim_display_title(text: str, max_chars: int = 38) -> str:
    clean = _re.sub(r"\s+", " ", (text or "")).strip("。 ")
    if len(clean) <= max_chars:
        return clean
    return clean[:max_chars].rstrip(" ・、。") + "…"


def _manager_quote_short_title_repair_enabled() -> bool:
    return _env_flag(ENABLE_MANAGER_QUOTE_SHORT_TITLE_REPAIR_ENV_FLAG, False)


def _is_manager_quote_short_title_repair_target(title: str) -> bool:
    normalized = _collapse_ws(_strip_html(title or "")).strip()
    return any(marker in normalized for marker in MANAGER_QUOTE_SHORT_TITLE_REPAIR_TARGET_MARKERS)


def _extract_manager_quote_short_title_quote(source_title: str, source_body: str, summary: str) -> str:
    texts = _dedupe_preserve_order(
        [
            _collapse_ws(_strip_html(value or "")).strip()
            for value in (source_title, source_body, summary)
            if _collapse_ws(_strip_html(value or "")).strip()
        ]
    )
    for text in texts:
        for phrase in _re.findall(r"[「『]([^」』]{4,50})[」』]", text):
            clean = _collapse_ws(phrase).strip(" ・、。")
            if not clean or any(marker in clean for marker in QUOTE_SKIP_MARKERS):
                continue
            return clean
    return ""


def _clip_manager_quote_short_title_quote(quote: str, max_chars: int = 40) -> str:
    clean = _collapse_ws(quote or "").strip(" ・、。")
    if len(clean) <= max_chars:
        return clean
    return clean[:max_chars].rstrip(" ・、。") + "…"


def _normalize_manager_quote_short_title_name(candidate: str) -> str:
    cleaned = _collapse_ws(_strip_html(candidate or "")).strip(" ・、。")
    if not cleaned or cleaned in {"巨人", "選手", "出場選手", "首脳陣", "ベンチ"}:
        return ""
    bare = _re.sub(r"(監督|コーチ|投手|捕手|内野手|外野手|選手)$", "", cleaned).strip()
    if bare and is_non_name_speaker_label(bare):
        return ""
    if title_has_person_name_candidate(cleaned) or (bare and title_has_person_name_candidate(bare)):
        return cleaned
    return ""


def _manager_quote_short_title_name_candidates(
    source_title: str,
    source_body: str,
    summary: str,
    metadata: Mapping[str, object] | None = None,
) -> list[str]:
    metadata = metadata or {}
    candidates: list[str] = []
    for key in ("player_name", "notice_subject", "speaker", "manager_name"):
        candidate = _collapse_ws(str(metadata.get(key) or "")).strip()
        role = _collapse_ws(str(metadata.get("role") or "")).strip()
        if key == "speaker" and role in {"監督", "コーチ"} and candidate and not candidate.endswith(role):
            candidate = f"{candidate}{role}"
        normalized = _normalize_manager_quote_short_title_name(candidate)
        if normalized and normalized not in candidates:
            candidates.append(normalized)

    player_subject = _normalize_manager_quote_short_title_name(_compact_subject_label(source_title, source_body or summary, "選手情報"))
    if player_subject and player_subject not in candidates:
        candidates.append(player_subject)

    manager_subject = _normalize_manager_quote_short_title_name(_extract_subject_label(source_title, source_body or summary, "首脳陣"))
    if manager_subject and manager_subject not in candidates:
        candidates.append(manager_subject)
    return candidates


def _manager_quote_short_title_name_matches_quote(name: str, quote: str, texts: list[str]) -> bool:
    variants = _dedupe_preserve_order(
        [
            name,
            _re.sub(r"(監督|コーチ|投手|捕手|内野手|外野手|選手)$", "", name).strip(),
        ]
    )
    for text in texts:
        normalized = _collapse_ws(_strip_html(text or ""))
        for variant in variants:
            if not variant:
                continue
            before_pattern = _re.compile(rf"{_re.escape(variant)}[^「『」』]{{0,12}}[「『]{_re.escape(quote)}[」』]")
            after_pattern = _re.compile(rf"[「『]{_re.escape(quote)}[」』][^「『」』]{{0,16}}{_re.escape(variant)}")
            if before_pattern.search(normalized) or after_pattern.search(normalized):
                return True
    return False


def _extract_manager_quote_short_title_name(
    source_title: str,
    source_body: str,
    summary: str,
    *,
    quote: str,
    metadata: Mapping[str, object] | None = None,
) -> str:
    texts = _dedupe_preserve_order(
        [
            _collapse_ws(_strip_html(value or "")).strip()
            for value in (source_title, source_body, summary)
            if _collapse_ws(_strip_html(value or "")).strip()
        ]
    )
    candidates = _manager_quote_short_title_name_candidates(source_title, source_body, summary, metadata)
    if quote:
        for candidate in candidates:
            if _manager_quote_short_title_name_matches_quote(candidate, quote, texts):
                return candidate

    for candidate in candidates:
        if candidate.endswith(("監督", "コーチ")):
            return candidate
    return candidates[0] if candidates else ""


def _manager_quote_short_title_has_action(source_title: str, source_body: str, summary: str) -> bool:
    source_text = _strip_html(" ".join(value for value in (source_title, source_body, summary) if value)).strip()
    return any(marker in source_text for marker in MANAGER_QUOTE_SHORT_TITLE_REPAIR_ACTION_MARKERS)


def _build_title_player_name_backfill_metadata(
    source_title: str,
    summary: str,
    category: str,
    article_subtype: str,
    *,
    manager_subject: str = "",
    notice_subject: str = "",
) -> dict[str, str]:
    metadata: dict[str, str] = {}
    if manager_subject and manager_subject not in {"首脳陣", "巨人"}:
        speaker = _re.sub(r"(監督|コーチ)$", "", manager_subject).strip()
        if speaker:
            metadata["speaker"] = speaker
        if manager_subject.endswith("監督"):
            metadata["role"] = "監督"
        elif "コーチ" in manager_subject:
            metadata["role"] = "コーチ"
        return metadata

    player_name = ""
    if notice_subject and notice_subject not in {"巨人", "選手", "出場選手"}:
        player_name = notice_subject
    else:
        player_name = _compact_subject_label(source_title, summary, category)
    if player_name and player_name not in {"巨人", "選手", "首脳陣"}:
        metadata["player_name"] = player_name

    role_label = _extract_player_role_label(source_title, summary)
    if role_label and not role_label.startswith("この"):
        for suffix in PLAYER_ROLE_SUFFIXES:
            if role_label.endswith(suffix):
                metadata["role"] = "投手" if suffix == "投手" else "選手"
                break
    if "role" not in metadata and article_subtype in {"lineup", "postgame", "pregame", "player", "notice", "recovery", "farm"}:
        metadata["role"] = "選手"
    if metadata.get("player_name") and any(marker in f"{source_title} {summary}" for marker in ("コメント", "談話", "一問一答", "発言", "語った", "話した")):
        metadata["speaker"] = metadata["player_name"]
    return metadata


def _log_title_player_name_unresolved(
    logger: logging.Logger,
    *,
    source_url: str,
    source_name: str,
    category: str,
    article_subtype: str,
    source_title: str,
    rewritten_title: str,
) -> None:
    payload = {
        "event": "title_player_name_review",
        "reason": "title_player_name_unresolved",
        "source_url": source_url,
        "source_name": source_name,
        "category": category,
        "article_subtype": article_subtype,
        "source_title": source_title,
        "candidate_title": rewritten_title,
    }
    logger.warning(json.dumps(payload, ensure_ascii=False))


def _is_social_or_video_title_source(source_url: str, source_name: str) -> bool:
    source_url_l = str(source_url or "").lower()
    source_name_clean = str(source_name or "").strip()
    source_name_l = source_name_clean.lower()
    return bool(
        any(
            marker in source_url_l
            for marker in ("x.com/", "twitter.com/", "youtube.com/", "youtu.be/", "instagram.com/")
        )
        or any(marker in source_name_l for marker in ("youtube", "instagram"))
        or source_name_clean.endswith(("X", "Ｘ"))
        or any(marker in source_name_clean for marker in ("公式X", "公式Ｘ", "巨人班X", "巨人班Ｘ"))
    )


def _social_title_publish_suffix(source_url: str, source_name: str) -> str:
    source_url_l = str(source_url or "").lower()
    source_name_l = str(source_name or "").lower()
    if "youtube.com/" in source_url_l or "youtu.be/" in source_url_l or "youtube" in source_name_l:
        return "がYouTubeで公開"
    if "instagram.com/" in source_url_l or "instagram" in source_name_l:
        return "がInstagramで投稿"
    return "が投稿"


def _nameless_social_title_topic(source_title: str, summary: str, source_url: str, source_name: str) -> str:
    source_text = _strip_html(f"{source_title} {summary}")
    source_url_l = str(source_url or "").lower()
    source_name_l = str(source_name or "").lower()
    quote_match = _re.search(r"[「『]([^」』]{1,12})[」』]", source_text)
    quote_label = f"「{quote_match.group(1)}」" if quote_match else ""

    if ("youtube.com/" in source_url_l or "youtu.be/" in source_url_l or "youtube" in source_name_l) and any(
        marker in source_text for marker in ("OB", "ＯＢ", "元巨人", "発言", "語")
    ):
        return "巨人OBの発言が話題" if any(marker in source_text for marker in ("発言", "語", "コメント")) else "巨人OBの話題"
    if quote_label and "投打" in source_text:
        return f"巨人{quote_label}に投打で話題"
    if "投打" in source_text:
        return "巨人投打の話題"
    if any(marker in source_text for marker in ("二軍", "２軍", "2軍", "ファーム")):
        return "巨人二軍の話題"
    if any(marker in source_text for marker in ("練習動画", "守備練習", "打撃練習", "練習")):
        return "巨人練習動画の話題"
    if any(marker in source_text for marker in ("試合前", "先発", "スタメン")):
        return "巨人試合前の話題"
    if any(marker in source_text for marker in ("ヒーロー", "お立ち台")):
        return "巨人ヒーロー投稿の話題"
    if quote_label:
        return f"巨人{quote_label}の話題"
    return "巨人関連の話題"


def _build_nameless_social_safe_title(
    *,
    source_title: str,
    summary: str,
    source_name: str,
    source_url: str,
) -> str:
    topic = _nameless_social_title_topic(source_title, summary, source_url, source_name)
    source_label = _collapse_ws(source_name or "X")
    suffix = _social_title_publish_suffix(source_url, source_name)
    return _trim_display_title(f"{topic} {source_label}{suffix}", max_chars=48)


def _title_needs_nameless_social_safety(title: str) -> bool:
    weak_subject, _reason = is_weak_subject_title(title)
    return bool(weak_subject or title_has_orphan_subject_particle(title))


def _log_nameless_social_safe_title_applied(
    logger: logging.Logger,
    *,
    source_url: str,
    source_name: str,
    category: str,
    article_subtype: str,
    original_title: str,
    safe_title: str,
) -> None:
    payload = {
        "event": "nameless_social_safe_title_applied",
        "source_url_hash": _hash_duplicate_guard_value(source_url),
        "source_name": source_name,
        "category": category,
        "article_subtype": article_subtype,
        "original_title": original_title,
        "safe_title": safe_title,
    }
    logger.info(json.dumps(payload, ensure_ascii=False))


def _apply_title_player_name_backfill(
    *,
    rewritten_title: str,
    source_title: str,
    source_body: str,
    summary: str,
    category: str,
    article_subtype: str,
    manager_subject: str = "",
    notice_subject: str = "",
    logger: logging.Logger | None = None,
    source_name: str = "",
    source_url: str = "",
) -> tuple[str, str]:
    metadata = _build_title_player_name_backfill_metadata(
        source_title,
        summary,
        category,
        article_subtype,
        manager_subject=manager_subject,
        notice_subject=notice_subject,
    )
    result = backfill_title_player_name(
        existing_title=rewritten_title,
        source_title=source_title,
        body=source_body,
        summary=summary,
        metadata=metadata,
    )
    final_title = _trim_display_title(result.title or rewritten_title)
    comparison_title = source_title

    # 329-QA: aggressive backfill via giants_roster.json scan.
    # 316-A の通常 backfill が title_player_name_unresolved になる時、
    # source body / summary / source_title を roster で再 scan し、exactly 1
    # player match があれば player_name=<match> を強制 metadata に詰めて
    # backfill を retry。「title に固有名詞を必ず入れる」user 要望への
    # narrow extension。default ON、ENABLE_AGGRESSIVE_TITLE_NAME_BACKFILL=0
    # で無効化可能。
    if (
        result.review_reason == "title_player_name_unresolved"
        and _aggressive_title_name_backfill_enabled()
    ):
        try:
            combined_text = " ".join(
                s for s in (source_body or "", summary or "", source_title or "") if s
            )
            roster_matches = (
                _matching_giants_roster_names(combined_text) if combined_text else []
            )
        except Exception:
            roster_matches = []
        if len(roster_matches) == 1:
            forced_name = roster_matches[0]
            forced_metadata = dict(metadata)
            forced_metadata["player_name"] = forced_name
            if article_subtype == "manager" and not forced_metadata.get("role"):
                forced_metadata["role"] = "監督"
            elif article_subtype == "coach" and not forced_metadata.get("role"):
                forced_metadata["role"] = "コーチ"
            try:
                forced_result = backfill_title_player_name(
                    existing_title=rewritten_title,
                    source_title=source_title,
                    body=source_body,
                    summary=summary,
                    metadata=forced_metadata,
                )
            except Exception:
                forced_result = None
            if (
                forced_result is not None
                and forced_result.player_name
                and forced_result.review_reason != "title_player_name_unresolved"
                and forced_result.title
                and forced_result.title != final_title
            ):
                if logger is not None:
                    try:
                        logger.info(
                            json.dumps(
                                {
                                    "event": "aggressive_title_name_backfill_applied",
                                    "source_url_hash": _hash_duplicate_guard_value(source_url),
                                    "source_name": source_name,
                                    "category": category,
                                    "article_subtype": article_subtype,
                                    "forced_name": forced_name,
                                    "original_title": final_title,
                                    "new_title": forced_result.title,
                                },
                                ensure_ascii=False,
                            )
                        )
                    except Exception:
                        pass
                final_title = _trim_display_title(forced_result.title)
                comparison_title = source_title
                return final_title, comparison_title

    if result.review_reason == "title_player_name_unresolved":
        if logger is not None:
            _log_title_player_name_unresolved(
                logger,
                source_url=source_url,
                source_name=source_name,
                category=category,
                article_subtype=article_subtype,
                source_title=source_title,
                rewritten_title=final_title,
            )
        if (
            _is_social_or_video_title_source(source_url, source_name)
            and _title_needs_nameless_social_safety(final_title)
        ):
            safe_title = _build_nameless_social_safe_title(
                source_title=source_title,
                summary=summary,
                source_name=source_name,
                source_url=source_url,
            )
            if safe_title:
                if logger is not None:
                    _log_nameless_social_safe_title_applied(
                        logger,
                        source_url=source_url,
                        source_name=source_name,
                        category=category,
                        article_subtype=article_subtype,
                        original_title=final_title,
                        safe_title=safe_title,
                    )
                final_title = safe_title
                comparison_title = source_title
        else:
            comparison_title = final_title

    # 330-QA: のもとけ-style SEO title pattern shaping.
    # backfill / rescue 完了後の final_title を subtype に応じた pattern
    # (A 発言 / B 状況+結果 / E 日付速報) に reshape。facts 不足時は None を
    # 返して current title 維持。ENABLE_NOMOTOKE_TITLE_TEMPLATE=0 で無効化可能。
    try:
        from src.title_template_assembler import assemble_nomotoke_title

        shaped_title = assemble_nomotoke_title(
            article_subtype=article_subtype,
            existing_title=final_title,
            source_title=source_title,
            source_body=source_body,
            summary=summary,
            player_name=result.player_name or "",
            role=result.role or "",
            metadata=metadata,
        )
    except Exception:
        shaped_title = None
    if shaped_title and shaped_title != final_title:
        if logger is not None:
            try:
                logger.info(
                    json.dumps(
                        {
                            "event": "nomotoke_title_template_applied",
                            "source_url_hash": _hash_duplicate_guard_value(source_url),
                            "source_name": source_name,
                            "category": category,
                            "article_subtype": article_subtype,
                            "before": final_title,
                            "after": shaped_title,
                        },
                        ensure_ascii=False,
                    )
                )
            except Exception:
                pass
        final_title = _trim_display_title(shaped_title)
        comparison_title = source_title

    try:
        from src.title_template_assembler import compress_event_token_repetition

        compressed_title = compress_event_token_repetition(final_title)
    except Exception:
        compressed_title = final_title
    if compressed_title and compressed_title != final_title:
        if logger is not None:
            try:
                logger.info(
                    json.dumps(
                        {
                            "event": "event_token_repetition_compressed",
                            "source_url_hash": _hash_duplicate_guard_value(source_url),
                            "before": final_title,
                            "after": compressed_title,
                        },
                        ensure_ascii=False,
                    )
                )
            except Exception:
                pass
        final_title = compressed_title

    return final_title, comparison_title


def _log_weak_title_rescued(
    logger: logging.Logger,
    *,
    source_url: str,
    source_name: str,
    category: str,
    article_subtype: str,
    original_title: str,
    rescued_title: str,
    source_title: str,
    strategy: str,
    original_skip_reason: str,
) -> None:
    payload = {
        "event": "weak_title_rescued",
        "source_url_hash": _hash_duplicate_guard_value(source_url),
        "source_name": source_name,
        "category": category,
        "article_subtype": article_subtype,
        "original_title": original_title,
        "new_title": rescued_title,
        "source_title": source_title,
        "strategy": strategy,
        "original_skip_reason": original_skip_reason,
    }
    logger.info(json.dumps(payload, ensure_ascii=False))


def _maybe_apply_weak_title_rescue(
    *,
    rewritten_title: str,
    source_title: str,
    source_body: str,
    summary: str,
    category: str,
    article_subtype: str,
    manager_subject: str = "",
    notice_subject: str = "",
    logger: logging.Logger | None = None,
    source_name: str = "",
    source_url: str = "",
    metadata: Mapping[str, object] | None = None,
) -> tuple[str, str | None]:
    if not _env_flag(WEAK_TITLE_RESCUE_ENV_FLAG, False):
        return rewritten_title, None

    weak_generated, weak_generated_reason = is_weak_generated_title(rewritten_title)
    weak_subject, weak_subject_reason = is_weak_subject_title(rewritten_title)
    if not weak_generated and not weak_subject:
        return rewritten_title, None

    rescue_metadata = _build_title_player_name_backfill_metadata(
        source_title,
        summary,
        category,
        article_subtype,
        manager_subject=manager_subject,
        notice_subject=notice_subject,
    )
    rescue_metadata.update(_merge_weak_title_metadata(metadata))
    rescue_result = (
        rescue_subtype_aware(
            gen_title=rewritten_title,
            source_title=source_title,
            body=source_body,
            summary=summary,
            metadata=rescue_metadata,
        )
        if _env_flag(NARROW_UNLOCK_SUBTYPE_AWARE_ENV_FLAG, False)
        else None
    ) or (
        rescue_related_info_escape(
            gen_title=rewritten_title,
            source_title=source_title,
            body=source_body,
            summary=summary,
            metadata=rescue_metadata,
        )
        or rescue_blacklist_phrase(
            gen_title=rewritten_title,
            source_title=source_title,
            body=source_body,
            summary=summary,
            metadata=rescue_metadata,
        )
    )
    if rescue_result is None:
        return rewritten_title, None

    rescued_title = _trim_display_title(rescue_result.title or rewritten_title)
    if not rescued_title or rescued_title == rewritten_title:
        return rewritten_title, None

    rescued_weak_generated, _ = is_weak_generated_title(rescued_title)
    rescued_weak_subject, _ = is_weak_subject_title(rescued_title)
    subtype_floor_ok = False
    if (
        _env_flag(NARROW_UNLOCK_SUBTYPE_AWARE_ENV_FLAG, False)
        and rescue_result.strategy.startswith("subtype_aware_")
    ):
        rescue_context_subtype = str(rescue_metadata.get("special_story_kind") or article_subtype)
        subtype_floor_ok, _subtype_reason = title_has_minimum_article_context(rescued_title, rescue_context_subtype)
    if (rescued_weak_generated or rescued_weak_subject) and not subtype_floor_ok:
        return rewritten_title, None

    original_skip_reason = ""
    if weak_subject:
        original_skip_reason = f"weak_subject_title:{weak_subject_reason}"
    elif weak_generated:
        original_skip_reason = f"weak_generated_title:{weak_generated_reason}"
    if logger is not None:
        _log_weak_title_rescued(
            logger,
            source_url=source_url,
            source_name=source_name,
            category=category,
            article_subtype=article_subtype,
            original_title=rewritten_title,
            rescued_title=rescued_title,
            source_title=source_title,
            strategy=rescue_result.strategy,
            original_skip_reason=original_skip_reason,
        )
    return rescued_title, original_skip_reason or None


RAINOUT_SLIDE_TITLE_RE = _re.compile(r"(?:雨天中止|雨で中止).*(?:スライド登板|先発予定)|(?:スライド登板).*(?:雨天中止|先発予定)")
FARM_LINEUP_TITLE_RE = _re.compile(r"(?:二軍|２軍|2軍|ファーム).*(?:スタメン|オーダー|打順|1⃣|2⃣|3⃣|4⃣|1番|2番|3番|4番)|(?:スタメン|オーダー|打順|1⃣|2⃣|3⃣|4⃣|1番|2番|3番|4番).*(?:二軍|２軍|2軍|ファーム)")
FARM_RESULT_TITLE_RE = _re.compile(r"(?:二軍|２軍|2軍|ファーム).*(?:\d+\s*[-－]\s*\d+|勝利|白星|敗戦|本塁打|無失点|猛打賞|マルチ)")
PLAYER_DEREGISTER_TITLE_RE = _re.compile(r"(?:出場選手)?登録を?抹消|登録抹消")
PLAYER_REGISTER_TITLE_RE = _re.compile(r"(?:出場選手)?登録|一軍登録|再登録")
PLAYER_RETURN_TITLE_RE = _re.compile(r"実戦復帰|復帰(?:へ前進|見込み|予定|間近)?")
PLAYER_JOIN_TITLE_RE = _re.compile(r"(?:一軍|チーム)?合流|昇格")
TITLE_VENUE_MARKERS = (
    "甲子園",
    "東京ドーム",
    "ジャイアンツ球場",
    "神宮",
    "横浜",
    "ナゴヤ",
    "バンテリン",
    "マツダ",
    "ZOZOマリン",
    "PayPay",
    "楽天モバイル",
    "京セラ",
    "エスコン",
    "しずてつスタジアム草薙",
)


def _extract_title_opponent(source_text: str) -> str:
    for marker in NPB_TEAM_MARKERS:
        if marker in {"巨人", "読売ジャイアンツ"}:
            continue
        if marker in source_text:
            return marker
    return ""


def _extract_title_venue(source_text: str) -> str:
    for marker in TITLE_VENUE_MARKERS:
        if marker in source_text:
            return marker
    return ""


def _has_pregame_numeric_hint(source_text: str) -> bool:
    return bool(RECORD_TOKEN_RE.search(source_text) or LABELED_DECIMAL_TOKEN_RE.search(source_text))


def _has_streaming_hint(source_text: str) -> bool:
    return any(marker in source_text for marker in ("配信中", "アーカイブ", "GIANTS TV", "Giants TV", "GIANTS_TV"))


def _extract_game_subject_fallback(source_text: str) -> str:
    patterns = (
        r"([一-龥々ァ-ヴー]{2,6})(?:投手|捕手|選手)?(?:\d+日)?スライド登板",
        r"([一-龥々ァ-ヴー]{2,6})(?:投手|捕手|選手)?先発",
    )
    for pattern in patterns:
        for match in _re.finditer(pattern, source_text):
            candidate = match.group(1).strip()
            if (
                not candidate
                or candidate in {"巨人", "読売ジャイアンツ"}
                or candidate in {"予告先発", "先発"}
                or candidate in NPB_TEAM_MARKERS
                or candidate in TITLE_VENUE_MARKERS
                or candidate.endswith("球場")
            ):
                continue
            return candidate
    return ""


def _normalize_game_story_subject(subject: str) -> str:
    normalized = (subject or "").strip()
    for marker in NPB_TEAM_MARKERS:
        normalized = _re.sub(rf"^{_re.escape(marker)}[・･]?", "", normalized)
    normalized = _re.sub(r"(投手|捕手|内野手|外野手|選手)$", "", normalized).strip()
    if (
        not normalized
        or normalized in {"巨人", "選手", "先発", "予告", "登板"}
        or any(marker in normalized for marker in ("ブルペン", "打線", "ベンチ"))
    ):
        return ""
    return normalized


ARTICLEIZATION_SOURCE_TITLE_PASSTHROUGH_MARKERS = (
    "顔面直撃",
    "緊急",
    "救急搬送",
    "搬送",
    "負傷",
    "故障",
    "けが",
    "ケガ",
    "実戦復帰",
    "復帰初球",
    "初球安打",
    "故障明け",
    "リハビリ",
)


def _source_title_has_articleization_detail(clean_title: str, source_text: str, category: str, subtype: str) -> bool:
    title_text = _collapse_ws(_strip_html(clean_title or ""))
    if len(title_text) < 8:
        return False
    if any(marker in title_text for marker in ("関連情報", "関連発言", "発言整理", "ベンチ関連発言")):
        return False
    if category == "ドラフト・育成" and SCORE_TOKEN_RE.search(title_text) and any(marker in source_text for marker in ("巨人", "二軍", "三軍", "ファーム")):
        return True
    if title_has_person_name_candidate(title_text) and any(marker in source_text for marker in ARTICLEIZATION_SOURCE_TITLE_PASSTHROUGH_MARKERS):
        return True
    if category == "ドラフト・育成" and any(marker in source_text for marker in ("二軍", "２軍", "2軍", "三軍", "３軍", "3軍", "ファーム")):
        return True
    return False


def _source_title_result_if_specific(
    clean_title: str,
    source_text: str,
    category: str,
    subtype: str,
    template_key: str,
    *,
    max_chars: int = 42,
) -> tuple[str, str] | None:
    if not _source_title_has_articleization_detail(clean_title, source_text, category, subtype):
        return None
    return _trim_display_title(clean_title, max_chars=max_chars), template_key


def _is_generic_title_only_pattern(title: str) -> bool:
    clean_title = _collapse_ws(_strip_html(title or "")).strip(" ・、。")
    if not clean_title:
        return True
    if title_has_person_name_candidate(clean_title):
        return False
    if any(marker in clean_title for marker in ("監督", "コーチ")):
        return False
    normalized = _normalize_title_for_dedupe(clean_title)
    for marker in GENERIC_TITLE_ONLY_MARKERS:
        if normalized == _normalize_title_for_dedupe(marker):
            return True
    if len(clean_title) > 18:
        return False
    stripped = clean_title
    for marker in GENERIC_TITLE_ONLY_MARKERS:
        stripped = stripped.replace(marker, "")
    stripped = _re.sub(r"[ 　・、。のはがをにでと確認整理関連ポイント]+", "", stripped)
    return not stripped


def _generic_title_repair_subject(
    source_title: str,
    summary: str,
    category: str,
    metadata: Mapping[str, object] | None = None,
) -> str:
    metadata = metadata or {}
    manager_name = _collapse_ws(str(metadata.get("manager_name") or "")).strip()
    if manager_name and manager_name not in {"巨人", "首脳陣"}:
        return manager_name
    for key in ("player_name", "notice_subject", "speaker"):
        candidate = _collapse_ws(str(metadata.get(key) or "")).strip()
        if candidate and candidate not in {"巨人", "選手", "出場選手", "首脳陣"}:
            return candidate
    candidate = _compact_subject_label(source_title, summary, category)
    if candidate and candidate not in {"巨人", "選手", "首脳陣"}:
        return candidate
    if category == "首脳陣":
        manager_label = _extract_subject_label(source_title, summary, category)
        if manager_label and manager_label not in {"巨人", "首脳陣"}:
            return manager_label
    return ""


def _generic_title_repair_action(source_title: str, summary: str) -> str:
    source_text = _strip_html(f"{source_title} {summary}")
    for action_label, markers in GENERIC_TITLE_REPAIR_ACTION_LABELS:
        if action_label == "失点":
            if _GENERIC_TITLE_REPAIR_QUANTIFIED_LOSS_RE.search(source_text):
                return action_label
            continue
        if any(marker in source_text for marker in markers):
            return action_label
    return ""


def _maybe_apply_manager_quote_short_title_repair(
    *,
    rewritten_title: str,
    source_title: str,
    source_body: str,
    summary: str,
    category: str,
    article_subtype: str,
    logger: logging.Logger,
    source_url: str,
    metadata: Mapping[str, object] | None = None,
) -> str:
    if not _manager_quote_short_title_repair_enabled():
        return rewritten_title
    if category != "首脳陣" or article_subtype not in {"manager", "manager_comment", "manager_quote"}:
        return rewritten_title
    if not _is_manager_quote_short_title_repair_target(rewritten_title):
        return rewritten_title

    quote = _extract_manager_quote_short_title_quote(source_title, source_body, summary)
    name = _extract_manager_quote_short_title_name(
        source_title,
        source_body,
        summary,
        quote=quote,
        metadata=metadata,
    )
    action_present = _manager_quote_short_title_has_action(source_title, source_body, summary)
    repaired_title = "review_kept"
    if name and action_present:
        if quote:
            repaired_title = _trim_display_title(
                f"{name}「{_clip_manager_quote_short_title_quote(quote)}」",
                max_chars=50,
            )
        else:
            repaired_title = _trim_display_title(f"{name}のコメント", max_chars=42)

    payload = {
        "event": "manager_quote_short_title_repaired",
        "source_url": source_url,
        "original_fallback_title": rewritten_title,
        "repaired_title": repaired_title,
        "name_extracted": name,
        "quote_extracted": quote,
    }
    if repaired_title == "review_kept":
        logger.warning(json.dumps(payload, ensure_ascii=False))
        return rewritten_title

    logger.info(json.dumps(payload, ensure_ascii=False))
    return repaired_title


def _maybe_apply_generic_title_repair(
    *,
    rewritten_title: str,
    source_title: str,
    summary: str,
    category: str,
    article_subtype: str,
    logger: logging.Logger,
    metadata: Mapping[str, object] | None = None,
) -> tuple[str, _WeakTitleReviewFallback | None]:
    if not _generic_title_repair_enabled():
        return rewritten_title, None
    if not _is_generic_title_only_pattern(rewritten_title):
        return rewritten_title, None

    source_text = _strip_html(f"{source_title} {summary}")
    source_title_result = _source_title_result_if_specific(
        _clean_display_title_text(source_title),
        source_text,
        category,
        article_subtype,
        "generic_title_repair_source_title",
        max_chars=42,
    )
    if source_title_result is not None:
        repaired_title, _template_key = source_title_result
        logger.info(
            json.dumps(
                {
                    "event": "generic_title_repair_applied",
                    "severity": "INFO",
                    "subtype": article_subtype,
                    "original_title": rewritten_title,
                    "repaired_title": repaired_title,
                },
                ensure_ascii=False,
            )
        )
        return repaired_title, None

    subject = _generic_title_repair_subject(source_title, summary, category, metadata)
    action = _generic_title_repair_action(source_title, summary)
    if subject and action:
        repaired_title = _trim_display_title(f"{subject}、{action} 関連情報", max_chars=42)
        logger.info(
            json.dumps(
                {
                    "event": "generic_title_repair_applied",
                    "severity": "INFO",
                    "subtype": article_subtype,
                    "original_title": rewritten_title,
                    "repaired_title": repaired_title,
                },
                ensure_ascii=False,
            )
        )
        return repaired_title, None

    logger.warning(
        json.dumps(
            {
                "event": "generic_title_repair_applied",
                "severity": "WARNING",
                "subtype": article_subtype,
                "original_title": rewritten_title,
                "repaired_title": "review_routed",
            },
            ensure_ascii=False,
        )
    )
    return rewritten_title, _WeakTitleReviewFallback("generic_title_repair_review")


def _rewrite_display_title_with_template_v2(
    *,
    title: str,
    summary: str,
    category: str,
    routing_template_key: str,
    source_analysis: Mapping[str, object] | None = None,
) -> tuple[str, str] | None:
    if not routing_template_key:
        return None

    def _result(text: str, template_key: str, max_chars: int = 42) -> tuple[str, str]:
        return _trim_display_title(text, max_chars=max_chars), template_key

    analysis = source_analysis or {}
    source_text = _strip_html(f"{title} {summary}")
    actor_name = str(analysis.get("actor_name") or "").strip()
    quote_phrases = _extract_quote_phrases(f"{title}\n{summary}", max_phrases=1)
    quote_text = quote_phrases[0] if quote_phrases else ""
    score = _extract_game_score_token(source_text)

    if routing_template_key == "score_lite" and score:
        return _result(f"巨人{score} 試合結果の要点", routing_template_key, max_chars=34)

    if routing_template_key in {"short_comment", "player_quote_short", "manager_quote_short"} and actor_name:
        if quote_text:
            return _result(f"{actor_name}「{quote_text}」 関連発言", routing_template_key, max_chars=50)
        action = _generic_title_repair_action(title, summary)
        if action:
            return _result(f"{actor_name}、{action} 関連発言", routing_template_key, max_chars=42)
        return _result(f"{actor_name} コメント整理", routing_template_key, max_chars=38)

    return None


def _rewrite_display_title_with_template(
    title: str,
    summary: str,
    category: str,
    has_game: bool,
    *,
    article_subtype_override: str = "",
    routing_template_key: str = "",
    source_analysis: Mapping[str, object] | None = None,
) -> tuple[str, str]:
    clean_title = _clean_display_title_text(title)
    clean_summary = _strip_html(summary or "").strip()
    source_text = _strip_html(f"{title} {summary}")
    subject = _short_subject_name(title, summary, category) or "巨人"
    status_subject = subject
    generic_player_status_subject = ""
    if category == "選手情報":
        role_label = _extract_player_role_label(title, summary)
        if (
            role_label
            and role_label.endswith("選手")
            and not role_label.startswith("この")
            and role_label.startswith(subject)
            and f"{subject}選手" in source_text
        ):
            generic_player_status_subject = role_label
    notice_subject = ""
    notice_type = ""
    if category == "選手情報" and _is_notice_template_story(title, summary, category):
        notice_subject, notice_type = _extract_notice_subject_and_type(title, summary)
        if notice_subject:
            subject = notice_subject
            status_subject = notice_subject
        if generic_player_status_subject and notice_subject and generic_player_status_subject.startswith(notice_subject):
            status_subject = generic_player_status_subject
    if subject in TITLE_VENUE_MARKERS or subject.endswith("球場") or subject in {"予告先発", "先発"}:
        subject = "巨人"
        status_subject = subject
    if category == "試合速報" and subject == "巨人":
        player_subject = _compact_subject_label(title, summary, "選手情報")
        if player_subject and player_subject not in TITLE_VENUE_MARKERS and not player_subject.endswith("球場"):
            subject = player_subject
            status_subject = player_subject
        if subject == "巨人":
            fallback_subject = _extract_game_subject_fallback(source_text)
            if fallback_subject:
                subject = fallback_subject
                status_subject = fallback_subject
    manager_display_subject = subject
    if category == "首脳陣":
        manager_label = _extract_subject_label(title, summary, category)
        if manager_label not in {"", "首脳陣", "巨人"}:
            subject = _re.sub(r"(監督|コーチ)$", "", manager_label).strip()
            manager_display_subject = manager_label
    quote = _extract_quote_phrases(f"{title}\n{summary}", max_phrases=1)
    quote_text = quote[0] if quote else ""
    subtype = _detect_article_subtype(title, summary, category, has_game)
    if _rss_template_routing_v2_enabled() and article_subtype_override:
        subtype = article_subtype_override
    opponent = _extract_title_opponent(source_text)
    venue = _extract_title_venue(source_text)
    game_subject = _normalize_game_story_subject(subject) if category == "試合速報" else ""
    source_entity_conflict = _quality_source_entity_conflict(title, summary)
    generic_player_subject_blocked = False
    if category == "選手情報" and _env_flag(ENABLE_TITLE_GENERIC_COMPOUND_GUARD_ENV_FLAG, False):
        generic_player_subject_blocked = any(
            is_generic_compound_subject(candidate) or is_non_name_speaker_label(candidate)
            for candidate in (generic_player_status_subject, status_subject, subject)
            if candidate
        )

    def _result(text: str, template_key: str, max_chars: int = 38) -> tuple[str, str]:
        return _trim_display_title(text, max_chars=max_chars), template_key

    if _rss_template_routing_v2_enabled():
        v2_result = _rewrite_display_title_with_template_v2(
            title=title,
            summary=summary,
            category=category,
            routing_template_key=routing_template_key,
            source_analysis=source_analysis,
        )
        if v2_result is not None:
            return v2_result

    if category == "選手情報":
        player_status_story = bool(
            PLAYER_DEREGISTER_TITLE_RE.search(source_text)
            or PLAYER_JOIN_TITLE_RE.search(source_text)
            or PLAYER_REGISTER_TITLE_RE.search(source_text)
            or PLAYER_RETURN_TITLE_RE.search(source_text)
            or "昇格" in source_text
            or "一軍" in source_text
            or "復帰" in source_text
        )
        if player_status_story and (source_entity_conflict or generic_player_subject_blocked):
            template_key = "player_status_entity_conflict_passthrough" if source_entity_conflict else "player_status_generic_subject_passthrough"
            return _result(clean_title or title or "巨人ニュース", template_key, max_chars=42)
        if "フォーム" in source_text or "助言" in source_text or "修正" in source_text:
            return _result(f"{subject}、フォーム変更 関連情報", "player_mechanics_generic")
        if PLAYER_DEREGISTER_TITLE_RE.search(source_text):
            return _result(f"{status_subject}、登録抹消 関連情報", "player_status_deregister")
        if PLAYER_JOIN_TITLE_RE.search(source_text):
            return _result(f"{status_subject}、一軍合流 関連情報", "player_status_join")
        if PLAYER_REGISTER_TITLE_RE.search(source_text):
            if notice_type in {"一軍登録", "再登録"}:
                return _result(f"{status_subject}、{notice_type} 関連情報", "player_status_register")
            return _result(f"{status_subject}、登録に関する関連情報", "player_status_register")
        if PLAYER_RETURN_TITLE_RE.search(source_text) or "昇格" in source_text or "一軍" in source_text or "復帰" in source_text:
            if generic_player_status_subject and not generic_player_subject_blocked:
                status_subject = generic_player_status_subject
            return _result(f"{status_subject}、昇格・復帰 関連情報", "player_status_return")
        if quote_text:
            return _result(f"{subject}「{quote_text}」 関連発言", "player_quote")
        return _result(f"{subject}の現状整理 関連情報", "player_generic")

    if category == "首脳陣":
        if quote_text and ("若手" in source_text or "競争" in source_text):
            return _result(
                f"{manager_display_subject}「{quote_text}」 若手起用で序列はどう動くか",
                "manager_quote_youth",
                max_chars=40,
            )
        if quote_text and ("スタメン" in source_text or "打順" in source_text or "起用" in source_text):
            return _result(f"{manager_display_subject}「{quote_text}」 スタメン関連発言", "manager_quote_lineup")
        if quote_text:
            return _result(f"{manager_display_subject}「{quote_text}」 ベンチ関連発言", "manager_quote_generic")
        return _result(f"{subject}コメント整理 ベンチ関連の発言ポイント", "manager_generic")

    if category == "試合速報":
        if "スライド登板" in source_text or RAINOUT_SLIDE_TITLE_RE.search(source_text):
            if "雨天中止" in source_text or "雨で中止" in source_text:
                return _result(f"{subject}、雨天中止スライド登板 関連情報", "game_rainout_slide_rainout")
            if venue:
                return _result(f"{subject}、{venue}スライド登板 関連情報", "game_rainout_slide_venue")
            if opponent:
                return _result(f"{subject}、{opponent}戦スライド登板 関連情報", "game_rainout_slide_opponent")
            return _result(f"{subject}、スライド登板 関連情報", "game_rainout_slide_generic")
        if subtype == "lineup":
            body = clean_title.replace("今日の", "").replace("スタメン発表", "").replace("発表", "").strip()
            capped = body[:25].rstrip()
            if capped:
                return _result(f"巨人スタメン {capped}", "game_lineup")
            return _result("巨人スタメン", "game_lineup")
        if subtype == "live_update":
            state_match = _re.search(r"(\d+回[表裏]?)", source_text)
            score = SCORE_TOKEN_RE.search(source_text)
            state_label = state_match.group(1) if state_match else "途中経過"
            if any(marker in source_text for marker in ("勝ち越し", "逆転")) and score:
                return _result(f"巨人{state_label} {score.group(0)} どこで流れが変わったか", "game_live_swing")
            if "同点" in source_text and score:
                return _result(f"巨人{state_label} {score.group(0)} 同点の試合状況", "game_live_tie")
            if score:
                return _result(f"巨人{state_label} {score.group(0)} 途中経過のポイント", "game_live_score")
            return _result(f"巨人{state_label} 途中経過のポイント", "game_live_generic")
        if subtype == "postgame":
            score = SCORE_TOKEN_RE.search(source_text)
            if any(marker in source_text for marker in ("完封負け", "0封負け", "打線が沈黙", "攻略できず")):
                base = f"巨人{opponent}戦 打線沈黙 試合内容の整理" if opponent else "巨人戦 打線沈黙 試合内容の整理"
                return _result(base, "game_postgame_shutout")
            if any(marker in source_text for marker in ("決勝打", "サヨナラ", "逆転")):
                base = f"巨人{opponent}戦 終盤の一打で動いた試合" if opponent else "巨人戦 終盤の一打で動いた試合"
                return _result(base, "game_postgame_clutch")
            if score and any(marker in source_text for marker in ("本日のヒーロー", "HERO IS HERE", "ヒーロー")):
                return _result(f"巨人{score.group(0)} 試合を決めたヒーロー", "game_postgame_hero")
            if game_subject:
                if "一問一答" in source_text or quote_text:
                    base = f"巨人{opponent}戦 {game_subject}の試合後発言整理" if opponent else f"巨人戦 {game_subject}の試合後発言整理"
                    return _result(base, "game_postgame_subject_comment")
                if any(marker in source_text for marker in ("強み", "投球術", "分析")):
                    base = f"巨人{opponent}戦 {game_subject}の強み 試合後の整理" if opponent else f"巨人戦 {game_subject}の強み 試合後の整理"
                    return _result(base, "game_postgame_subject_analysis")
                if any(marker in source_text for marker in ("勝目", "勝利", "白星", "好投", "快投", "本塁打", "打点", "猛打賞", "連勝")):
                    base = f"巨人{opponent}戦 {game_subject}、試合での見せ場" if opponent else f"巨人戦 {game_subject}、試合での見せ場"
                    return _result(base, "game_postgame_subject")
            if any(marker in source_text for marker in ("とっておきメモ", "証言")):
                base = f"巨人{opponent}戦 勝利を支えた材料の整理" if opponent else "巨人戦 勝利を支えた材料の整理"
                return _result(base, "game_postgame_supporting_point")
            if score:
                if any(marker in source_text for marker in ("敗れ", "敗戦", "黒星")):
                    return _result(f"巨人{score.group(0)} 敗戦の分岐点 試合の流れ", "game_postgame_loss")
                if any(marker in source_text for marker in ("勝利", "白星", "連勝")):
                    return _result(f"巨人{score.group(0)} 勝利の分岐点 試合の流れ", "game_postgame_win")
                return _result(f"巨人{score.group(0)} 試合の流れを分けたポイント", "game_postgame_score")
            if opponent:
                return _result(f"巨人{opponent}戦 試合の流れを分けたポイント", "game_postgame_opponent")
            return _result("巨人戦 試合の流れを分けたポイント", "game_postgame_generic")
        if subject not in {"", "巨人", "選手", "予告", "先発", "登板"} and any(marker in source_text for marker in ("予告先発", "先発", "登板")):
            if opponent:
                return _result(f"巨人{opponent}戦 {subject}先発 試合前情報", "game_pregame_subject_starter")
            return _result(f"巨人戦 {subject}先発 試合前情報", "game_pregame_subject_starter")
        if "予告先発" in source_text and _has_pregame_numeric_hint(source_text):
            if opponent:
                return _result(f"巨人{opponent}戦 予告先発 関連数字情報", "game_pregame_numeric")
            return _result("巨人戦 予告先発 関連数字情報", "game_pregame_numeric")
        if any(marker in source_text for marker in ("初打席", "プロ初")):
            if opponent:
                return _result(f"巨人{opponent}戦 初打席の注目選手", "game_pregame_first_at_bat")
            return _result("巨人戦 初打席の注目選手情報", "game_pregame_first_at_bat")
        if game_subject:
            if opponent:
                return _result(f"巨人{opponent}戦 {game_subject}に関する試合前情報", "game_pregame_subject")
            return _result(f"巨人戦 {game_subject}に関する試合前情報", "game_pregame_subject")
        if venue:
            if opponent:
                return _result(f"巨人{opponent}戦 {venue}に関する試合前情報", "game_pregame_venue")
            return _result(f"巨人戦 {venue}に関する試合前情報", "game_pregame_venue")
        if opponent:
            return _result(f"巨人{opponent}戦 当日カードの試合前情報", "game_pregame_opponent")
        return _result("巨人戦 当日カードの試合前情報", "game_pregame_generic")

    if category == "補強・移籍":
        if "外国人" in source_text:
            return _result("巨人の新外国人補強 関連情報", "reinforcement_foreign")
        if "トレード" in source_text or "移籍" in source_text:
            return _result("巨人の補強・移籍 最新関連情報", "reinforcement_trade")
        return _result("巨人補強の整理 関連トピック", "reinforcement_generic")

    if category == "ドラフト・育成":
        if subtype == "farm_lineup" or FARM_LINEUP_TITLE_RE.search(source_text):
            return _result("巨人二軍スタメン 当日カード試合前情報", "farm_lineup")
        score = SCORE_TOKEN_RE.search(source_text)
        if FARM_RESULT_TITLE_RE.search(source_text) and score:
            if _has_streaming_hint(source_text):
                return _result(f"巨人二軍 {score.group(0)} 配信試合のポイント", "farm_result_stream")
            if "降雨コールド" in source_text:
                return _result(f"巨人二軍 {score.group(0)} 降雨コールドのポイント", "farm_result_rainout")
            return _result(f"巨人二軍 {score.group(0)} 結果のポイント", "farm_result_score")

    return _result(clean_title or "巨人ニュース", "fallback_clean_title")


def rewrite_display_title(title: str, summary: str, category: str, has_game: bool) -> str:
    rewritten_title, _template_key = _rewrite_display_title_with_guard(
        title,
        summary,
        category,
        has_game,
    )
    return rewritten_title


def _log_title_template_selected(
    logger: logging.Logger,
    source_url: str,
    original_title: str,
    rewritten_title: str,
    template_key: str,
    category: str,
    article_subtype: str,
) -> None:
    payload = {
        "event": "title_template_selected",
        "source_url": source_url,
        "category": category,
        "article_subtype": article_subtype,
        "template": template_key,
        "original_title": original_title,
        "rewritten_title": rewritten_title,
    }
    logger.info(json.dumps(payload, ensure_ascii=False))


def _log_title_validator_reroll(
    logger: logging.Logger,
    *,
    source_url: str,
    category: str,
    article_subtype: str,
    fail_axes: list[str],
    inferred_subtype: str,
    expected_first_block: str,
    candidate_title: str,
    rerolled_title: str,
) -> None:
    payload = {
        "event": "title_validator_reroll",
        "source_url": source_url,
        "category": category,
        "article_subtype": article_subtype,
        "fail_axis": fail_axes,
        "inferred_subtype": inferred_subtype,
        "expected_first_block": expected_first_block,
        "candidate_title": candidate_title,
        "rerolled_title": rerolled_title,
    }
    logger.warning(json.dumps(payload, ensure_ascii=False))


def _rewrite_display_title_with_guard(
    title: str,
    summary: str,
    category: str,
    has_game: bool,
    *,
    article_subtype: str = "",
    logger: logging.Logger | None = None,
    source_url: str = "",
    routing_context: Mapping[str, object] | None = None,
) -> tuple[str, str]:
    resolved_subtype = article_subtype or _detect_article_subtype(title, summary, category, has_game)
    routing_payload = dict(routing_context or {})
    rewritten_title, template_key = _rewrite_display_title_with_template(
        title,
        summary,
        category,
        has_game,
        article_subtype_override=resolved_subtype,
        routing_template_key=str(routing_payload.get("template_selector_v2_key") or ""),
        source_analysis=routing_payload.get("source_analysis_v2") if isinstance(routing_payload.get("source_analysis_v2"), Mapping) else None,
    )
    if not _title_validator_supports_subtype(resolved_subtype):
        return rewritten_title, template_key

    validation = _validate_title_candidate(rewritten_title, resolved_subtype)
    if validation["ok"]:
        return rewritten_title, template_key

    rerolled_title = _trim_display_title(_build_title_reroll_title(rewritten_title, resolved_subtype))
    rerolled_validation = _validate_title_candidate(rerolled_title, resolved_subtype)
    if not rerolled_validation["ok"]:
        rerolled_title = _trim_display_title(_build_title_reroll_title("", resolved_subtype))

    if logger is not None:
        _log_title_validator_reroll(
            logger,
            source_url=source_url,
            category=category,
            article_subtype=resolved_subtype,
            fail_axes=list(validation["fail_axes"]),
            inferred_subtype=str(validation.get("inferred_subtype") or ""),
            expected_first_block=str(validation.get("expected_first_block") or ""),
            candidate_title=rewritten_title,
            rerolled_title=rerolled_title,
        )

    return rerolled_title, f"{template_key}_title_reroll"


def _generic_title_blocklist_v2_phrase(title: str) -> str:
    normalized = _collapse_ws(_strip_html(title or "")).strip(" ・、。")
    for phrase in GENERIC_TITLE_BLOCKLIST_V2:
        if normalized.endswith(phrase):
            return phrase
    return ""


def _extract_v2_title_action(
    *,
    source_title: str,
    summary: str,
    analysis: Mapping[str, object] | None = None,
) -> str:
    source_text = _strip_html(f"{source_title} {summary}")
    notice_type = _extract_notice_type_label(source_text)
    if notice_type:
        return notice_type

    if analysis and analysis.get("has_recovery_or_injury"):
        for marker in ("実戦復帰", "復帰登板", "一軍合流", "術後", "故障明け", "リハビリ", "復帰"):
            if marker in source_text:
                return marker

    action = _generic_title_repair_action(source_title, summary)
    if action:
        return action

    decisive_event = str((analysis or {}).get("decisive_event_text") or "").strip()
    if decisive_event:
        return decisive_event.rstrip("。")
    return ""


def _extract_giants_hashtag_name_recovery_candidates(source_text: str) -> list[tuple[str, str]]:
    clean_source_text = _collapse_ws(_strip_html(source_text or ""))
    if not clean_source_text or "#" not in clean_source_text:
        return []
    candidates: list[tuple[str, str]] = []
    for match in TITLE_HASHTAG_NAME_RECOVERY_HASHTAG_RE.finditer(clean_source_text):
        roster_name = _match_giants_roster_hashtag_alias(match.group("tag"))
        if not roster_name:
            continue
        candidates.append((roster_name, clean_source_text[match.end():].lstrip()))
    return candidates


def _recover_title_from_hashtag_name(
    raw_title: str,
    *,
    source_title: str = "",
    summary: str = "",
) -> str:
    if not _title_hashtag_name_recovery_enabled():
        return raw_title

    clean_title = _collapse_ws(_strip_html(raw_title or "")).strip()
    if not clean_title:
        return raw_title

    leading_punct_match = TITLE_HASHTAG_NAME_RECOVERY_LEADING_PUNCT_RE.match(clean_title)
    role_match = TITLE_HASHTAG_NAME_RECOVERY_ROLE_RE.search(clean_title)
    if not leading_punct_match and not role_match:
        return raw_title
    if role_match and title_has_person_name_candidate(clean_title[:role_match.start()].rstrip(" ・、，,")):
        return raw_title

    candidates = _extract_giants_hashtag_name_recovery_candidates(f"{source_title} {summary}")
    if not candidates:
        return raw_title

    if leading_punct_match:
        for roster_name, tail in candidates:
            if tail.startswith(clean_title):
                return _trim_display_title(f"{roster_name}{clean_title}", max_chars=42)

    if role_match:
        role_remainder = clean_title[role_match.start():].lstrip()
        prefix = clean_title[:role_match.start()].rstrip()
        for roster_name, tail in candidates:
            if tail.startswith(role_remainder):
                return _trim_display_title(f"{prefix}{roster_name}{clean_title[role_match.start():]}", max_chars=42)

    return raw_title


def _finalize_title(
    raw_title: str,
    *,
    source_title: str = "",
    summary: str = "",
    analysis: Mapping[str, object] | None = None,
) -> tuple[str, _WeakTitleReviewFallback | None]:
    raw_title = _recover_title_from_hashtag_name(
        raw_title,
        source_title=source_title,
        summary=summary,
    )
    blocklisted_phrase = _generic_title_blocklist_v2_phrase(raw_title)
    if not blocklisted_phrase:
        return raw_title, None

    source_analysis = analysis or {}
    actor_name = str(source_analysis.get("actor_name") or "").strip()
    quote_phrases = _extract_quote_phrases(f"{source_title}\n{summary}", max_phrases=1)
    if actor_name and quote_phrases:
        return _trim_display_title(f"{actor_name}「{_clip_manager_quote_short_title_quote(quote_phrases[0])}」", max_chars=50), None

    action = _extract_v2_title_action(
        source_title=source_title,
        summary=summary,
        analysis=source_analysis,
    )
    if actor_name and action:
        if action.startswith("「"):
            rewritten = f"{actor_name}{action}"
        else:
            rewritten = f"{actor_name}、{action}"
        return _trim_display_title(rewritten, max_chars=42), None

    return raw_title, _WeakTitleReviewFallback(f"blacklist_phrase:{blocklisted_phrase}")


def _log_body_validator_reroll(
    logger: logging.Logger,
    *,
    source_url: str,
    category: str,
    article_subtype: str,
    fail_axes: list[str],
    expected_first_block: str,
    actual_first_block: str,
    missing_required_blocks: list[str],
    actual_block_order: list[str],
) -> None:
    payload = {
        "event": "body_validator_reroll",
        "source_url": source_url,
        "category": category,
        "article_subtype": article_subtype,
        "fail_axis": fail_axes,
        "expected_first_block": expected_first_block,
        "actual_first_block": actual_first_block,
        "missing_required_blocks": missing_required_blocks,
        "actual_block_order": actual_block_order,
    }
    logger.warning(json.dumps(payload, ensure_ascii=False))


def _log_body_validator_fail(
    logger: logging.Logger,
    *,
    source_url: str,
    category: str,
    article_subtype: str,
    fail_axes: list[str],
    expected_first_block: str,
    actual_first_block: str,
    has_source_block: bool,
    stop_reason: str = "",
) -> None:
    payload = {
        "event": "body_validator_fail",
        "source_url": source_url,
        "category": category,
        "article_subtype": article_subtype,
        "fail_axis": fail_axes,
        "expected_first_block": expected_first_block,
        "actual_first_block": actual_first_block,
        "has_source_block": has_source_block,
    }
    if stop_reason:
        payload["stop_reason"] = stop_reason
    logger.warning(json.dumps(payload, ensure_ascii=False))


def _log_manager_body_template_applied(
    logger: logging.Logger,
    post_id: int,
    title: str,
    quote_count: int,
    section_count: int,
    template_version: str | None = None,
) -> None:
    payload = {
        "event": "manager_body_template_applied",
        "post_id": post_id,
        "title": title,
        "quote_count": quote_count,
        "section_count": section_count,
        "template_version": template_version or _manager_body_template_version(),
    }
    logger.info(json.dumps(payload, ensure_ascii=False))


# 2026-05-13: ヨシラバー voice 構造化 prefix。postgame article の冒頭に
# fact table + 見どころ + 短い fan-voice narrative を追加して「大手新聞
# imitation」から脱却する。LLM 不要 (deterministic、source 由来 fact のみ)、
# 著作権 risk 小 (短い fact 列挙、creative work copy ではない)。
_YOSHILOVER_INNINGS_RE = _re.compile(r"(?<![0-9０-９])(?P<innings>[1-9]|1[0-2])回(?![表裏])")
_YOSHILOVER_PITCH_COUNT_RE = _re.compile(r"(?P<pitches>\d{2,3})球")
_YOSHILOVER_RUN_GIVEN_RE = _re.compile(r"(?P<runs>無失点|[1-9]\d?失点)")
_YOSHILOVER_HIT_COUNT_RE = _re.compile(r"被安打(?P<hits>\d+)")
_YOSHILOVER_K_COUNT_RE = _re.compile(r"奪三振(?P<k>\d+)")
_YOSHILOVER_KEY_PLAY_MARKERS: tuple[str, ...] = (
    "本塁打", "ソロ", "ホームラン", "打点", "盗塁",
    "好投", "完投", "勝利投手", "敗戦投手", "セーブ",
    "サヨナラ", "逆転", "同点", "決勝", "先制",
)


def _yoshilover_postgame_narrative(text: str, has_no_runs: bool, title: str = "") -> str:
    """Short fan-voice narrative for postgame articles. Deterministic
    template, no LLM. Picks the most-specific branch that matches.

    主役 player は ``title`` から優先検出。summary 内の secondary 言及 (例:
    同点被弾の救援投手) が narrative を逆転しないように。
    """
    try:
        from src.player_eyecatch_resolver import detect_person
        player = detect_person(title) if title else ""
        if not player:
            player = detect_person(text) or ""
    except Exception:
        player = ""
    is_noresult = ("ノーゲーム" in text) or ("中止" in text)
    is_win = any(m in text for m in ("勝利", "白星", "サヨナラ勝", "勝ち", "勝った", "勝つ"))
    is_loss = any(m in text for m in ("敗戦", "黒星", "敗れ", "サヨナラ負", "負け"))
    is_tied = ("同点" in text) or ("引き分け" in text)
    is_hr = any(m in text for m in ("本塁打", "ソロ", "ホームラン"))

    if is_noresult:
        return "今日はノーゲーム / 中止。次戦に切り替えたいところ。"
    if player and has_no_runs:
        return f"{player} の好投が光った試合。次回登板への期待も大きい。"
    if player and is_hr:
        return f"{player} の一発が試合を動かした。流れを変える一打になった印象。"
    if player and is_win:
        return f"{player} の活躍で巨人に勝利。次戦への弾みになる試合だった。"
    if player and is_loss:
        return f"{player} の奮闘はあったが今日は黒星。次戦の巻き返しに期待。"
    if is_win:
        return "巨人らしく粘った試合だった。次戦への期待値も上がる結果。"
    if is_loss:
        return "悔しい敗戦。ファンとしては次戦の巻き返しに期待したい。"
    if is_tied:
        return "白黒つかず、終盤の競り合いが見どころに。"
    return "ファンとしては今日の試合の流れを噛みしめたい結果。"


def _build_yoshilover_structured_prefix(
    title: str,
    summary: str,
    article_subtype: str,
) -> str:
    """Return an HTML prefix (fact table + 見どころ + 短い fan-voice
    narrative) to be prepended to postgame article body. Returns ``""``
    when subtype is not postgame or no facts are extractable.
    """
    if article_subtype != "postgame":
        return ""
    text = _strip_html(f"{title} {summary}")

    rows: list[tuple[str, str]] = []
    score = _extract_game_score_token(text)
    if score:
        rows.append(("スコア", score))
    m_inn = _YOSHILOVER_INNINGS_RE.search(text)
    if m_inn:
        rows.append(("投球回", f"{m_inn.group('innings')}回"))
    m_pitch = _YOSHILOVER_PITCH_COUNT_RE.search(text)
    if m_pitch:
        rows.append(("球数", f"{m_pitch.group('pitches')}球"))
    m_runs = _YOSHILOVER_RUN_GIVEN_RE.search(text)
    has_no_runs = bool(m_runs and "無失点" in m_runs.group("runs"))
    if m_runs:
        rows.append(("失点", m_runs.group("runs")))
    m_hits = _YOSHILOVER_HIT_COUNT_RE.search(text)
    if m_hits:
        rows.append(("被安打", f"{m_hits.group('hits')}本"))
    m_k = _YOSHILOVER_K_COUNT_RE.search(text)
    if m_k:
        rows.append(("奪三振", f"{m_k.group('k')}個"))

    bullets: list[str] = []
    sentences = [s.strip(" 　・") for s in _re.split(r"[。！？\n]+", text) if s.strip()]
    seen_b: set[str] = set()
    for s in sentences:
        if not (8 <= len(s) <= 80):
            continue
        if not any(m in s for m in _YOSHILOVER_KEY_PLAY_MARKERS):
            continue
        key = s.replace(" ", "").replace("　", "")
        if key in seen_b:
            continue
        seen_b.add(key)
        bullets.append(s)
        if len(bullets) >= 3:
            break

    if not rows and not bullets:
        return ""

    narrative = _yoshilover_postgame_narrative(text, has_no_runs, title=title)

    parts: list[str] = []
    parts.append(
        '<aside class="nomotoke-card-yoshilover-fact" '
        'style="background:#f8fcff;border-left:4px solid #f57f17;'
        'padding:14px 16px;margin:14px 0;border-radius:6px;">'
    )
    if rows:
        parts.append(
            '<p style="margin:0 0 8px;color:#1976d2;font-weight:700;font-size:1.05em;">'
            '📊 試合まとめ</p>'
        )
        parts.append(
            '<table style="width:100%;border-collapse:collapse;margin-bottom:12px;font-size:0.95em;">'
        )
        for label, value in rows:
            parts.append(
                f'<tr><th style="text-align:left;padding:4px 8px;'
                f'background:#e3f2fd;width:32%;font-weight:600;">{_html.escape(label)}</th>'
                f'<td style="padding:4px 8px;">{_html.escape(value)}</td></tr>'
            )
        parts.append('</table>')
    if bullets:
        parts.append(
            '<p style="margin:0 0 8px;color:#1976d2;font-weight:700;font-size:1.05em;">'
            '🔑 見どころ</p>'
        )
        parts.append('<ul style="margin:0 0 12px 0;padding-left:1.4em;">')
        for b in bullets:
            parts.append(f'<li style="margin-bottom:4px;">{_html.escape(b)}</li>')
        parts.append('</ul>')
    if narrative:
        parts.append(
            '<p style="margin:0 0 8px;color:#1976d2;font-weight:700;font-size:1.05em;">'
            '📝 ヨシラバー的に</p>'
        )
        parts.append(f'<p style="margin:0;">{_html.escape(narrative)}</p>')
    parts.append('</aside>')
    return "".join(parts)


