def _lock_timestamp_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")


def _lock_payload(run_id: str) -> dict[str, object]:
    now = _lock_timestamp_now()
    return {
        "run_id": run_id,
        "started_at": now,
        "updated_at": now,
        "pid": os.getpid(),
        "hostname": socket.gethostname(),
        "revision": os.getenv("K_REVISION", "unknown"),
        "timeout_seconds": RSS_FETCHER_LOCK_TIMEOUT_SECONDS,
        "lock_version": RSS_FETCHER_LOCK_VERSION,
    }


def _safe_lock_int(value: object) -> int | None:
    if isinstance(value, bool):
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _parse_lock_timestamp(value: object) -> datetime | None:
    if not isinstance(value, str) or not value:
        return None
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None


def _load_lock_data(lock_file: Path) -> dict[str, object] | None:
    try:
        payload = json.loads(lock_file.read_text(encoding="utf-8"))
    except (FileNotFoundError, json.JSONDecodeError, OSError, UnicodeDecodeError):
        return None
    if not isinstance(payload, dict):
        return None
    return payload


def _lock_age_seconds(lock_file: Path, payload: Mapping[str, object] | None) -> int:
    updated_at = _parse_lock_timestamp(payload.get("updated_at")) if payload else None
    if updated_at is not None:
        age = time.time() - updated_at.timestamp()
    else:
        try:
            age = time.time() - lock_file.stat().st_mtime
        except FileNotFoundError:
            return 0
    return max(0, int(age))


def _lock_ttl_seconds(payload: Mapping[str, object] | None) -> int:
    timeout_seconds = _safe_lock_int(payload.get("timeout_seconds")) if payload else None
    if timeout_seconds and timeout_seconds > 0:
        return max(timeout_seconds * 2, 900)
    return RSS_FETCHER_LOCK_TTL_SECONDS


def _is_lock_pid_alive(pid: int) -> bool:
    if pid <= 0:
        return False
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return True


def _emit_lock_event(logger: logging.Logger, level: str, payload: dict[str, object]):
    payload["severity"] = level
    log_fn = getattr(logger, level.lower())
    log_fn(json.dumps(payload, ensure_ascii=False))


def _build_lock_cleanup(lock_file: Path, run_id: str, logger: logging.Logger):
    state = {"released": False}

    def cleanup():
        if state["released"]:
            return False
        payload = _load_lock_data(lock_file)
        if not payload or payload.get("run_id") != run_id:
            return False
        try:
            lock_file.unlink(missing_ok=True)
        except OSError:
            return False
        state["released"] = True
        _emit_lock_event(
            logger,
            "INFO",
            {
                "event": "rss_fetcher_lock_released",
                "current_run_id": run_id,
                "lock_pid": payload.get("pid", "unknown"),
            },
        )
        return True

    return cleanup


def _try_acquire_lock(lock_file: Path, run_id: str, logger: logging.Logger) -> bool:
    while lock_file.exists():
        payload = _load_lock_data(lock_file)
        age_seconds = _lock_age_seconds(lock_file, payload)
        ttl_seconds = _lock_ttl_seconds(payload)
        pid = _safe_lock_int(payload.get("pid")) if payload else None

        if pid is not None:
            pid_alive = _is_lock_pid_alive(pid)
            if pid_alive and age_seconds < ttl_seconds:
                _emit_lock_event(
                    logger,
                    "WARNING",
                    {
                        "event": "rss_fetcher_lock_skip",
                        "reason": "fresh_lock",
                        "lock_age_seconds": age_seconds,
                        "lock_run_id": payload.get("run_id", "unknown") if payload else "unknown",
                        "current_run_id": run_id,
                        "lock_pid": pid,
                        "lock_pid_alive": True,
                        "ttl_seconds": ttl_seconds,
                    },
                )
                return False
            stale_reason = "pid_dead" if not pid_alive else "ttl_expired"
        else:
            if age_seconds < ttl_seconds:
                _emit_lock_event(
                    logger,
                    "WARNING",
                    {
                        "event": "rss_fetcher_lock_skip",
                        "reason": "corrupt_recent",
                        "lock_age_seconds": age_seconds,
                        "lock_run_id": payload.get("run_id", "unknown") if payload else "unknown",
                        "current_run_id": run_id,
                        "lock_pid": "unknown",
                        "lock_pid_alive": False,
                        "ttl_seconds": ttl_seconds,
                    },
                )
                return False
            stale_reason = "corrupt_old"

        _emit_lock_event(
            logger,
            "ERROR",
            {
                "event": "rss_fetcher_stale_lock_removed",
                "reason": stale_reason,
                "lock_age_seconds": age_seconds,
                "stale_run_id": payload.get("run_id", "unknown") if payload else "unknown",
                "current_run_id": run_id,
                "lock_started_at": payload.get("started_at", "unknown") if payload else "unknown",
                "lock_updated_at": payload.get("updated_at", "unknown") if payload else "unknown",
                "lock_pid": pid if pid is not None else "unknown",
                "ttl_seconds": ttl_seconds,
            },
        )
        lock_file.unlink(missing_ok=True)

    lock_file.parent.mkdir(parents=True, exist_ok=True)
    payload = _lock_payload(run_id)
    lock_file.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    _emit_lock_event(
        logger,
        "INFO",
        {
            "event": "rss_fetcher_lock_acquired",
            "current_run_id": run_id,
            "lock_pid": payload["pid"],
            "lock_started_at": payload["started_at"],
            "lock_updated_at": payload["updated_at"],
            "ttl_seconds": _lock_ttl_seconds(payload),
        },
    )
    return True

# ──────────────────────────────────────────────────────────
# X投稿URLを取得（twitter.com形式に統一）
# ──────────────────────────────────────────────────────────
def get_post_url(entry) -> str:
    url = entry.get("link", "")
    return url.replace("https://x.com/", "https://twitter.com/")

# ──────────────────────────────────────────────────────────
# メイン処理
# ──────────────────────────────────────────────────────────
def main():
    parser = argparse.ArgumentParser(description="RSSHub経由でX投稿を取得してWP下書き生成")
    parser.add_argument("--dry-run", action="store_true", help="WP投稿せず結果を表示のみ")
    parser.add_argument("--draft-only", action="store_true", help="WordPressに下書きだけ作成し、公開とX投稿を行わない")
    parser.add_argument("--limit", type=int, default=10, help="1回の実行で公開する最大記事数（デフォルト10）")
    parser.add_argument("--article-ai-mode", choices=["auto", "grok", "gemini", "none"], help="この実行に限り記事AIのモードを上書きする")
    args = parser.parse_args()

    logger = setup_logger()

    # 多重起動防止ロック
    lock_file = ROOT / "logs" / "rss_fetcher.lock"
    run_id = uuid.uuid4().hex
    if not _try_acquire_lock(lock_file, run_id, logger):
        return
    cleanup = _build_lock_cleanup(lock_file, run_id, logger)
    atexit.register(cleanup)
    previous_sigterm = signal.getsignal(signal.SIGTERM)

    def _handle_sigterm(signum, frame):
        cleanup()
        raise SystemExit(128 + signum)

    signal.signal(signal.SIGTERM, _handle_sigterm)
    try:
        _main(args, logger)
    finally:
        signal.signal(signal.SIGTERM, previous_sigterm)
        cleanup()


def _check_giants_game_today_yahoo() -> tuple:
    game_id, opponent, venue = _find_today_giants_game_info_yahoo()
    return bool(game_id), opponent, venue


def check_giants_game_today() -> tuple:
    """巨人の今日の試合があるか確認。(has_game: bool, opponent: str, venue: str) を返す。
    取得失敗時は (False, "", "") を返してフェイルクローズに倒す。"""
    import urllib.request as _ur
    from datetime import date
    import re as _re
    logger = logging.getLogger("rss_fetcher")

    yahoo_has_game, yahoo_opponent, yahoo_venue = _check_giants_game_today_yahoo()
    if yahoo_has_game:
        return yahoo_has_game, yahoo_opponent, yahoo_venue

    today = date.today()
    today_str = today.strftime("%Y-%m-%d")
    # NPB公式 月別日程ページ (4月なら schedule_04_detail.html)
    month_str = today.strftime("%m")
    url = f"https://npb.jp/games/{today.year}/schedule_{month_str}_detail.html"

    try:
        req = _ur.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with _ur.urlopen(req, timeout=10) as res:
            html = res.read().decode("utf-8", errors="ignore")

        # 今日の日付セクションを探す（NPBページは "M/D" 形式で日付が入る）
        # 巨人＝「読売」「Giants」「G」のいずれかが同じ行/セクションにあるか確認
        # 日付は例: "4/13" or "4月13日"
        day_pattern = f"{today.month}/{today.day}"
        day_pattern2 = f"{today.month}月{today.day}日"

        # ページ全体を日付ブロックに分割
        # 簡易：今日の日付文字列の前後500文字に巨人関連語があるか
        for pat in [day_pattern, day_pattern2]:
            idx = html.find(pat)
            while idx != -1:
                block = html[max(0, idx-50):idx+600]
                block_text = _re.sub(r'<[^>]+>', '', block)
                if any(kw in block_text for kw in ["読売", "Giants", "ジャイアンツ", "巨人"]):
                    # 中止・オフを除外
                    if any(ng in block_text for ng in ["中止", "オフ", "休み", "ノーゲーム"]):
                        return False, "", ""
                    # 対戦相手と球場を抽出（あれば）
                    opp_m = _re.search(r'(?:vs\.|対)\s*([^\s<&]{2,6})', block_text)
                    venue_m = _re.search(r'(東京ドーム|神宮|横浜|ナゴヤ|甲子園|マツダ|PayPay|バンテリン|ほっと|ZOZOマリン)', block_text)
                    opponent = opp_m.group(1) if opp_m else ""
                    venue    = venue_m.group(1) if venue_m else ""
                    return True, opponent, venue
                idx = html.find(pat, idx + 1)

        # 巨人戦が見つからなければ試合なし
        return False, "", ""

    except Exception as e:
        logger.warning("試合日チェック失敗（フェイルクローズ）: %s", e)
        return False, "", ""


def _main(args, logger):
    logger.info(f"=== rss_fetcher 開始 {'[DRY RUN]' if args.dry_run else ''} ===")

    if _fetcher_log_sampling_v1_enabled() or _pre_post_gen_validate_skip_enabled():
        _reset_log_sampling_state()

    # 今日の巨人戦有無を確認（試合なしの日は試合記事プロンプトを使わない）
    has_game, opponent, venue = check_giants_game_today()
    if has_game:
        logger.info(f"本日の巨人戦あり{(' vs ' + opponent) if opponent else ''}{(' @' + venue) if venue else ''}")
    else:
        logger.info("本日の巨人戦なし → 選手・コラム記事モードで実行")

    # 設定読み込み
    with open(RSS_SOURCES_FILE, encoding="utf-8") as f:
        sources = json.load(f)
    with open(KEYWORDS_FILE, encoding="utf-8") as f:
        keywords = json.load(f)

    history = load_history()

    if not args.dry_run:
        wp = WPClient()

    total = skip_dup = skip_filter = success = error = 0
    skip_reason_counts: Counter[str] = Counter()
    prepared_category_counts: Counter[str] = Counter()
    prepared_subtype_counts: Counter[str] = Counter()
    created_category_counts: Counter[str] = Counter()
    created_subtype_counts: Counter[str] = Counter()
    publish_skip_reason_counts: Counter[str] = Counter()
    publish_observation_counts: Counter[str] = Counter()
    x_skip_reason_counts: Counter[str] = Counter()
    # RELIABILITY-2026-05-08-T1: 1 fire の summary log 1 行で全観察項目を判定可能に
    # するための telemetry counters。5/9 朝検証で個別 grep を不要にする。
    review_drafts_created_count: int = 0
    review_drafts_axes_breakdown: Counter[str] = Counter()
    bypass_full_invocation_count: int = 0
    tag_scraper_per_source: Counter[str] = Counter()
    scraper_fetch_failures: int = 0
    skip_reason_sample_titles: dict[str, list[str]] = {}
    x_post_daily_limit = get_x_post_daily_limit()
    today_str = datetime.now().strftime("%Y-%m-%d")
    x_post_count = history.get(f"x_post_count_{today_str}", 0)
    x_ai_generation_count = history.get(f"x_ai_generation_count_{today_str}", 0)
    prepared_entries = []
    media_quote_pool = []
    entry_index = 0
    not_giants_related_info_count = 0
    not_giants_related_sample_titles: list[str] = []
    fetch_started_at = datetime.now(timezone.utc)
    # 324-QA: drop stale fan_voice_pool entries from any prior in-process run.
    _reset_fan_voice_pool_cache()
    game_live_source_policy_active = bool(
        has_game and _is_game_live_source_policy_window(fetch_started_at)
    )
    game_live_source_policy_skipped_sources = 0
    # RSS-255: 同一 run 内で同じ x_status_id の 2 件目以降を skip。
    same_fire_status_ids: set[str] = set()

    for source_rank, source in enumerate(sources):
        name        = source["name"]
        url         = source["url"]
        source_type = source.get("type", "news")
        source_roles = _source_roles_from_config(source.get("role"))
        prepared_source_roles = sorted(source_roles)
        should_add_to_media_quote_pool = bool(source_roles & {"media_quote_pool", "media_quote_only"})
        should_articleize = "media_quote_only" not in source_roles
        if game_live_source_policy_active and not _source_allowed_by_game_live_policy(
            source_roles,
            now=fetch_started_at,
        ):
            game_live_source_policy_skipped_sources += 1
            logger.info(
                json.dumps(
                    {
                        "event": "game_live_source_policy_skip",
                        "source_name": name,
                        "source_url": url,
                        "source_roles": prepared_source_roles,
                        "reason": "not_game_live_source",
                        "allowed_roles": sorted(GAME_LIVE_SOURCE_POLICY_ROLES),
                        "window": GAME_LIVE_SOURCE_POLICY_WINDOW_LABEL,
                    },
                    ensure_ascii=False,
                )
            )
            continue
        # 324-QA: fan_voice_pool sources are RSSHub feeds of curated fan
        # accounts. Fetch via feedparser, cache for the picker (325-QA), and
        # skip the per-entry articleize / media_quote_pool / publish loop.
        # With no fan_voice_pool entries in config today, this branch is dead.
        if source_type == "fan_voice_pool":
            logger.info(f"取得中: {name} ({url}) [fan_voice_pool]")
            try:
                feed = feedparser.parse(url)
                pool_entries = feed.entries
            except Exception as e:
                logger.error(f"fan_voice_pool fetch failed {name}: {e}")
                error += 1
                continue
            cached = _record_fan_voice_pool_entries(name, pool_entries)
            total += len(pool_entries)
            logger.info(
                f"  fan_voice_pool: {len(pool_entries)} fetched, {cached} cached from {name}"
            )
            continue
        logger.info(f"取得中: {name} ({url})")

        try:
            if source_type == "yahoo_realtime":
                keyword = url.replace("yahoo_realtime://", "")
                entries = fetch_yahoo_realtime_entries(keyword)
            elif source_type == "tag_scrape":
                # RELIABILITY-2026-05-08-A+B: hochi 等 RSS が 404 / 未配備の trusted media
                # 用 tag/index page scraper。env flag default OFF。config の `scraper` キーで
                # 実装名を指定 (hochi_giants_tag 等)。
                if not _env_flag("ENABLE_TAG_PAGE_SCRAPER", False):
                    logger.info(f"  tag_scrape disabled for {name} (ENABLE_TAG_PAGE_SCRAPER=0)")
                    entries = []
                else:
                    from src import tag_page_scraper as _tag_page_scraper
                    scraper_kind = str(source.get("scraper") or "").strip()
                    if not scraper_kind:
                        logger.error(f"tag_scrape source missing 'scraper' key: {name}")
                        error += 1
                        continue
                    try:
                        max_age_days_value = int(source.get("max_age_days") or 7)
                    except (TypeError, ValueError):
                        max_age_days_value = 7
                    try:
                        article_limit_value = int(source.get("article_limit") or 30)
                    except (TypeError, ValueError):
                        article_limit_value = 30
                    entries = _tag_page_scraper.fetch_tag_page_entries(
                        scraper=scraper_kind,
                        url=url,
                        max_age_days=max_age_days_value,
                        article_limit=article_limit_value,
                        logger=logger,
                    )
                    # RELIABILITY-2026-05-08-T1: scraper 別取得件数を telemetry 化。
                    # 0 件 = 取得失敗 / age filter 全 skip の signal、要観察。
                    tag_scraper_per_source[scraper_kind] += len(entries)
                    if not entries:
                        scraper_fetch_failures += 1
            else:
                feed    = feedparser.parse(url)
                entries = feed.entries
        except Exception as e:
            logger.error(f"フィード取得失敗 {name}: {e}")
            error += 1
            continue

        logger.info(f"  {len(entries)}件取得")
        total += len(entries)

        for entry in entries:
            post_url = get_post_url(entry)
            source_handle = _extract_handle_from_tweet_url(post_url)
            entry_title_raw = (entry.get("title", "") or "").strip()
            entry_summary_raw = entry.get("summary", "") or entry.get("description", "")
            if source_type == "social_news":
                entry_title_clean = _clean_social_entry_text(entry_title_raw)
                entry_summary_clean = _clean_social_entry_text(entry_summary_raw)
                if _is_polluted_social_entry(
                    entry_title_raw,
                    entry_summary_raw,
                    source_name=name,
                    post_url=post_url,
                ):
                    logger.debug(f"  [SKIP:SNS汚染] {entry_title_raw[:40]}")
                    skip_filter += 1
                    skip_reason_counts["sns_polluted"] += 1
                    continue
            else:
                entry_title_clean = entry_title_raw
                entry_summary_clean = entry_summary_raw
            title_text = f"{entry_title_clean} {entry_summary_clean}".strip()
            source_trust = (
                _source_trust_classify_handle(source_handle)
                if source_handle
                else _source_trust_classify_url(post_url)
            )
            logger.info(
                "  [SOURCE] url=%s source_trust=%s source_id=%s",
                post_url,
                source_trust,
                _source_id_key(post_url),
            )

            import re as _re2
            entry_title_norm = _re2.sub(r"[\s　【】「」『』〔〕（）()・\-_]", "", entry_title_clean).lower()
            if _is_history_duplicate(post_url, entry_title_norm, history):
                logger.debug(f"  [SKIP:履歴重複] {entry_title_clean[:50]}")
                skip_dup += 1
                skip_reason_counts["history_duplicate"] += 1
                _append_skip_reason_sample(skip_reason_sample_titles, "history_duplicate", entry_title_clean or post_url)
                continue

            # RSS-255: post_gen_validate fail history dedup (TTL 24h、Gemini cost 削減)
            x_status_id_for_dedup = _extract_x_status_id(post_url or "")
            if x_status_id_for_dedup and x_status_id_for_dedup in same_fire_status_ids:
                logger.debug(f"  [SKIP:同run内重複status_id] {entry_title_clean[:50]}")
                skip_filter += 1
                skip_reason_counts["post_gen_validate_failed_status_id_recent"] += 1
                _append_skip_reason_sample(
                    skip_reason_sample_titles,
                    "post_gen_validate_failed_status_id_recent",
                    entry_title_clean or post_url,
                )
                continue
            pgv_recent, pgv_match_kind = _is_post_gen_validate_failure_recent(
                history,
                post_url=post_url,
                x_status_id=x_status_id_for_dedup,
                entry_title_norm=entry_title_norm,
            )
            if pgv_recent and _post_gen_validate_trusted_bypass(post_url):
                logger.info(json.dumps({
                    "event": "post_gen_validate_trusted_source_bypass",
                    "fail_axes": [f"pgv_failure_dedup:{pgv_match_kind}"],
                    "stop_reason": "post_gen_validate_failure_dedup",
                    "post_url": post_url,
                }, ensure_ascii=False))
                pgv_recent = False
            if pgv_recent:
                skip_kind = (
                    "post_gen_validate_failed_status_id_recent"
                    if pgv_match_kind == "status"
                    else "post_gen_validate_failed_source_url_recent"
                )
                if _fetcher_log_sampling_v1_enabled():
                    _log_sampling_state["post_gen_validate_failure_dedup_skip_count"] += 1
                else:
                    logger.info(
                        json.dumps(
                            {
                                "event": "post_gen_validate_failure_dedup_skip",
                                "matched_key_kind": pgv_match_kind,
                                "post_url": post_url,
                                "x_status_id": x_status_id_for_dedup,
                                "title_preview": (entry_title_clean or "")[:60],
                                "ttl_hours": POST_GEN_VALIDATE_FAILURE_TTL_HOURS,
                            },
                            ensure_ascii=False,
                        )
                    )
                skip_filter += 1
                skip_reason_counts[skip_kind] += 1
                _append_skip_reason_sample(
                    skip_reason_sample_titles,
                    skip_kind,
                    entry_title_clean or post_url,
                )
                if x_status_id_for_dedup:
                    same_fire_status_ids.add(x_status_id_for_dedup)
                continue
            if x_status_id_for_dedup:
                same_fire_status_ids.add(x_status_id_for_dedup)

            published_at = _entry_published_datetime(entry)
            if not published_at:
                logger.debug(f"  [SKIP:日付なし] {post_url}")
                skip_filter += 1
                skip_reason_counts["missing_published_at"] += 1
                continue

            if should_add_to_media_quote_pool:
                media_quote_pool.append({
                    "source_name": name,
                    "source_type": source_type,
                    "source_roles": prepared_source_roles,
                    "source_url": post_url,
                    "title": entry_title_clean,
                    "summary": entry_summary_clean,
                    "created_at": published_at,
                })
            if not should_articleize:
                continue

            giants_signal_text = title_text
            if source_type == "social_news":
                giants_signal_text = " ".join(
                    part
                    for part in (entry_title_raw, entry_summary_raw, entry_title_clean, entry_summary_clean)
                    if part
                )

            # 344-INGEST: YouTube source は OB roster 検出を加えた YouTube 専用 filter で
            # 巨人 relevance を再評価 (is_giants_related と並行 OR、より広く拾う)。
            _entry_is_youtube = _is_youtube_post_url(post_url)
            _youtube_filter_pass = False
            _youtube_filter_reason = ""
            if _entry_is_youtube:
                _youtube_filter_pass, _youtube_filter_reason = _check_youtube_giants_filter(
                    entry_title_clean
                )

            if (
                not is_giants_related(giants_signal_text, source_name=name, post_url=post_url)
                and not _youtube_filter_pass
            ):
                logger.debug(f"  [SKIP:フィルタ] {post_url}")
                if len(not_giants_related_sample_titles) < 3:
                    not_giants_related_sample_titles.append(entry_title_clean[:80] or post_url)
                if not_giants_related_info_count < 5:
                    _log_not_giants_related_skip(
                        logger,
                        title=entry_title_clean[:160],
                        post_url=post_url,
                        source_name=name,
                        detected_keywords=_matching_giants_keywords(giants_signal_text),
                    )
                    not_giants_related_info_count += 1
                if _entry_is_youtube:
                    logger.info(
                        json.dumps(
                            {
                                "event": "youtube_title_filter_skip",
                                "reason": _youtube_filter_reason or "no_match",
                                "title": entry_title_clean[:160],
                                "post_url": post_url,
                                "source_name": name,
                            },
                            ensure_ascii=False,
                        )
                    )
                skip_filter += 1
                skip_reason_counts["not_giants_related"] += 1
                continue

            no_entity_reason = _should_skip_no_entity_non_game(
                entry_title_clean, entry_summary_clean
            )
            if no_entity_reason:
                logger.info(
                    json.dumps(
                        {
                            "event": "no_entity_non_game_skip",
                            "reason": no_entity_reason,
                            "title": entry_title_clean[:160],
                            "post_url": post_url,
                            "source_name": name,
                        },
                        ensure_ascii=False,
                    )
                )
                _append_skip_reason_sample(
                    skip_reason_sample_titles,
                    no_entity_reason,
                    entry_title_clean or post_url,
                )
                skip_filter += 1
                skip_reason_counts[no_entity_reason] += 1
                continue

            non_giants_mlb_subject = _is_non_giants_mlb_primary_subject(
                entry_title_clean, entry_summary_clean
            )
            if non_giants_mlb_subject:
                logger.info(
                    json.dumps(
                        {
                            "event": "non_giants_mlb_primary_subject_skip",
                            "subject": non_giants_mlb_subject,
                            "title": entry_title_clean[:160],
                            "post_url": post_url,
                            "source_name": name,
                        },
                        ensure_ascii=False,
                    )
                )
                _append_skip_reason_sample(
                    skip_reason_sample_titles,
                    "non_giants_mlb_primary_subject",
                    entry_title_clean or post_url,
                )
                skip_filter += 1
                skip_reason_counts["non_giants_mlb_primary_subject"] += 1
                continue

            if _should_skip_too_short_title(entry_title_clean):
                logger.info(
                    json.dumps(
                        {
                            "event": "title_too_short_skip",
                            "title": entry_title_clean[:80],
                            "post_url": post_url,
                            "source_name": name,
                        },
                        ensure_ascii=False,
                    )
                )
                _append_skip_reason_sample(
                    skip_reason_sample_titles,
                    "title_too_short",
                    entry_title_clean or post_url,
                )
                skip_filter += 1
                skip_reason_counts["title_too_short"] += 1
                continue

            if _should_skip_quote_only_no_subject_title(entry_title_clean):
                logger.info(
                    json.dumps(
                        {
                            "event": "quote_only_no_subject_skip",
                            "title": entry_title_clean[:80],
                            "post_url": post_url,
                            "source_name": name,
                        },
                        ensure_ascii=False,
                    )
                )
                _append_skip_reason_sample(
                    skip_reason_sample_titles,
                    "quote_only_no_subject",
                    entry_title_clean or post_url,
                )
                skip_filter += 1
                skip_reason_counts["quote_only_no_subject"] += 1
                continue

            # 同 Giants player name が title 内に 2 回以上出てきたら 1 回に dedup。
            # 例: source 元 (報知) が「{name}『{name}選手は…』」 format を使う
            # ケースに対応。dedup は entry_title_clean のみ更新、summary は維持。
            _deduped = _dedupe_entity_in_title(entry_title_clean)
            if _deduped != entry_title_clean:
                logger.info(
                    json.dumps(
                        {
                            "event": "title_entity_duplicate_deduped",
                            "before": entry_title_clean[:80],
                            "after": _deduped[:80],
                            "post_url": post_url,
                            "source_name": name,
                        },
                        ensure_ascii=False,
                    )
                )
                entry_title_clean = _deduped

            raw_title, title_preview = _prepare_source_title_context(entry_title_clean, entry)
            title = raw_title
            summary  = entry_summary_clean
            category = classify_category(
                title_text,
                keywords,
                source_url=post_url,
                logger=logger,
            )
            # Observation only; later consumers decide whether to use normalized outputs.
            _, category_guard_warnings = _tc_validate_category(category)
            _, tag_guard_warnings = _tc_validate_tags(prepared_source_roles)
            tag_category_warnings = category_guard_warnings + tag_guard_warnings
            if tag_category_warnings:
                logger.info(
                    "  [CLASSIFY_OBSERVE] %s → %s tag_category_warnings=%s",
                    title_preview[:40],
                    category,
                    json.dumps(tag_category_warnings, ensure_ascii=False),
                )
            routing_context = _resolve_rss_story_type_context(
                title=title,
                summary=summary,
                category=category,
                daily_has_game=has_game,
                source_type=source_type,
                source_url=post_url,
                source_name=name,
                logger=logger,
            )
            category = str(routing_context.get("category") or category)
            entry_has_game = bool(
                routing_context.get("entry_has_game", infer_article_has_game(title, summary, category, has_game))
            )
            article_subtype = str(
                routing_context.get("title_subtype")
                or _detect_article_subtype(title, summary, category, entry_has_game)
            )
            stale_source_guard = _evaluate_fetcher_stale_source_guard(
                entry,
                post_url=post_url,
                article_subtype=article_subtype,
            )
            if not stale_source_guard["allow"]:
                stale_reason = str(stale_source_guard["reason"] or "stale_source_age")
                _log_stale_source_guard_skip(
                    logger,
                    reason=stale_reason,
                    title=title,
                    post_url=post_url,
                    article_subtype=article_subtype,
                    decision=stale_source_guard,
                )
                skip_filter += 1
                skip_reason_counts[stale_reason] += 1
                _append_skip_reason_sample(skip_reason_sample_titles, stale_reason, title)
                continue
            if _should_skip_stale_postgame_entry(category, title, summary, published_at, max_age_hours=36):
                logger.debug(f"  [SKIP:postgame古い] {title_preview[:40]}")
                skip_filter += 1
                skip_reason_counts["stale_postgame"] += 1
                _append_skip_reason_sample(skip_reason_sample_titles, "stale_postgame", title)
                continue
            if _should_skip_postgame_after_morning_window(category, title, summary, published_at):
                logger.debug(f"  [SKIP:postgame朝刊window外] {title_preview[:40]}")
                skip_filter += 1
                skip_reason_counts["stale_postgame_morning_window"] += 1
                _append_skip_reason_sample(skip_reason_sample_titles, "stale_postgame_morning_window", title)
                continue
            if _should_skip_stale_player_status_entry(category, title, summary, published_at):
                logger.debug(f"  [SKIP:player_status古い] {title_preview[:40]}")
                skip_filter += 1
                skip_reason_counts["stale_player_status"] += 1
                _append_skip_reason_sample(skip_reason_sample_titles, "stale_player_status", title)
                continue

            if source_type in {"news", "social_news"}:
                if _is_promotional_video_entry(entry_title_clean, summary):
                    logger.debug(f"  [SKIP:動画プロモ] {title_preview[:40]}")
                    skip_filter += 1
                    skip_reason_counts["video_promo"] += 1
                    _append_skip_reason_sample(skip_reason_sample_titles, "video_promo", title)
                    continue
                if article_subtype == "live_update" and not ENABLE_LIVE_UPDATE_ARTICLES:
                    fan_important_exempt = _fetcher_fan_important_narrow_exempt_context(
                        skip_kind="live_update_disabled",
                        post_meta={
                            "source_name": name,
                            "source_handle": source_handle,
                            "source_title": raw_title,
                            "summary": summary,
                            "category": category,
                            "article_subtype": article_subtype,
                        },
                        source_url=post_url,
                        title=title,
                    )
                    if fan_important_exempt:
                        _log_fetcher_fan_important_narrow_exempt(
                            logger,
                            skip_kind="live_update_disabled",
                            source_url=post_url,
                            title=title,
                            context=fan_important_exempt,
                        )
                    else:
                        logger.debug(f"  [SKIP:途中経過停止中] {title_preview[:40]}")
                        skip_filter += 1
                        skip_reason_counts["live_update_disabled"] += 1
                        _append_skip_reason_sample(skip_reason_sample_titles, "live_update_disabled", title)
                        continue
                has_comment = "「" in title_text
                if source_type == "news":
                    allow_commentless_news = article_subtype in {"lineup", "farm_lineup", "postgame"}
                    if not has_comment and not allow_commentless_news:
                        fan_important_exempt = _fetcher_fan_important_narrow_exempt_context(
                            skip_kind="comment_required",
                            post_meta={
                                "source_name": name,
                                "source_handle": source_handle,
                                "source_title": raw_title,
                                "summary": summary,
                                "category": category,
                                "article_subtype": article_subtype,
                            },
                            source_url=post_url,
                            title=title,
                        )
                        if fan_important_exempt:
                            _log_fetcher_fan_important_narrow_exempt(
                                logger,
                                skip_kind="comment_required",
                                source_url=post_url,
                                title=title,
                                context=fan_important_exempt,
                            )
                        elif _post_gen_validate_trusted_bypass(post_url):
                            logger.info(json.dumps({
                                "event": "post_gen_validate_trusted_source_bypass",
                                "fail_axes": ["comment_required"],
                                "stop_reason": "comment_required",
                                "post_url": post_url,
                            }, ensure_ascii=False))
                        else:
                            logger.debug(f"  [SKIP:コメントなし] {title_preview[:40]}")
                            skip_filter += 1
                            skip_reason_counts["comment_required"] += 1
                            _append_skip_reason_sample(skip_reason_sample_titles, "comment_required", title)
                            continue
                else:
                    worthy, rescue_meta = _evaluate_authoritative_social_entry(
                        title,
                        summary,
                        category,
                        article_subtype,
                        source_name=name,
                        source_handle=source_handle,
                        source_url=post_url,
                    )
                    if rescue_meta:
                        _log_sns_weak_rescue(logger, post_url, title, rescue_meta)
                    if not worthy:
                        fan_important_exempt = _fetcher_fan_important_narrow_exempt_context(
                            skip_kind="social_too_weak",
                            post_meta={
                                "source_name": name,
                                "source_handle": source_handle,
                                "source_title": raw_title,
                                "summary": summary,
                                "category": category,
                                "article_subtype": article_subtype,
                            },
                            source_url=post_url,
                            title=title,
                        )
                        if fan_important_exempt:
                            _log_fetcher_fan_important_narrow_exempt(
                                logger,
                                skip_kind="social_too_weak",
                                source_url=post_url,
                                title=title,
                                context=fan_important_exempt,
                            )
                        elif _post_gen_validate_trusted_bypass(post_url):
                            logger.info(json.dumps({
                                "event": "post_gen_validate_trusted_source_bypass",
                                "fail_axes": ["social_too_weak"],
                                "stop_reason": "social_too_weak",
                                "post_url": post_url,
                            }, ensure_ascii=False))
                        else:
                            logger.debug(f"  [SKIP:SNS弱い] {title_preview[:40]}")
                            skip_filter += 1
                            skip_reason_counts["social_too_weak"] += 1
                            _append_skip_reason_sample(skip_reason_sample_titles, "social_too_weak", title)
                            continue

            logger.info(f"  [HIT] {title_preview[:40]} → {category}")
            prepared_category_counts[category] += 1
            if source_type in {"news", "social_news"}:
                prepared_subtype_counts[article_subtype] += 1
            prepared_entries.append({
                "entry_index": entry_index,
                "source_rank": source_rank,
                "source_name": name,
                "source_handle": source_handle,
                "source_type": source_type,
                "source_roles": prepared_source_roles,
                "entry": entry,
                "post_url": post_url,
                "title_text": title_text,
                "raw_title": raw_title,
                "category": category,
                "title": title,
                "summary": summary,
                "entry_title_norm": entry_title_norm,
                "entry_has_game": entry_has_game,
                "published_at": published_at,
                "published_day": _entry_day_key(entry),
                "history_urls": [post_url],
                "history_title_norms": [entry_title_norm] if entry_title_norm else [],
                "routing_context": routing_context,
            })
            entry_index += 1

    prepared_entries = _aggregate_lineup_candidates(prepared_entries)
    # #18 / 339-INGEST: 同 family X 速報 + Web 記事 dedup (digest aggregation の前)。
    # ENABLE_SAME_FAMILY_X_WEB_DEDUP=0 (default) で完全 no-op。
    prepared_entries = _aggregate_same_family_x_web_candidates(prepared_entries)
    # 334-QA Phase 2b: digest cluster detection + log のみ、candidate 不変。
    # ENABLE_PLAYER_VOICE_DIGEST_DETECTION=0 (default) で完全 no-op。
    prepared_entries = _aggregate_player_voice_digest_candidates(prepared_entries)

    yahoo_game_status = {}
    if has_game:
        try:
            yahoo_game_status = fetch_today_giants_game_status_from_yahoo()
        except Exception as e:
            logger.warning("Yahoo試合固定ページ取得失敗: %s", e)
            yahoo_game_status = {}

    if has_game and yahoo_game_status:
        filtered_prepared_entries = []
        for item in prepared_entries:
            if _should_skip_started_pregame_entry(
                item["category"],
                item["title"],
                item["summary"],
                item.get("entry_has_game", True),
                yahoo_game_status,
            ):
                fan_important_exempt = _fetcher_fan_important_narrow_exempt_context(
                    skip_kind="pregame_started",
                    post_meta={
                        "source_name": item.get("source_name", ""),
                        "source_handle": item.get("source_handle", ""),
                        "source_title": item.get("raw_title", item["title"]),
                        "summary": item.get("summary", ""),
                        "category": item.get("category", ""),
                        "article_subtype": _detect_article_subtype(
                            item.get("raw_title", item["title"]),
                            item.get("summary", ""),
                            item.get("category", ""),
                            item.get("entry_has_game", True),
                        ),
                    },
                    source_url=item.get("post_url", ""),
                    title=item["title"],
                )
                if fan_important_exempt:
                    _log_fetcher_fan_important_narrow_exempt(
                        logger,
                        skip_kind="pregame_started",
                        source_url=item.get("post_url", ""),
                        title=item["title"],
                        context=fan_important_exempt,
                    )
                else:
                    _log_pregame_started_skip(
                        item["title"],
                        item.get("summary", ""),
                        item.get("post_url", ""),
                        yahoo_game_status,
                    )
                    skip_filter += 1
                    skip_reason_counts["pregame_started"] += 1
                    _append_skip_reason_sample(skip_reason_sample_titles, "pregame_started", item["title"])
                    continue
            if _should_skip_unfinished_postgame_entry(
                item["category"],
                item["title"],
                item["summary"],
                item.get("entry_has_game", True),
                yahoo_game_status,
            ):
                _log_postgame_unfinished_skip(
                    item["title"],
                    item.get("summary", ""),
                    item.get("post_url", ""),
                    yahoo_game_status,
                )
                skip_filter += 1
                skip_reason_counts["postgame_unfinished"] += 1
                _append_skip_reason_sample(
                    skip_reason_sample_titles,
                    "postgame_unfinished",
                    item["title"],
                )
                continue
            if _should_skip_prior_event_postgame(
                item["category"],
                item["title"],
                item["summary"],
                item.get("entry_has_game", True),
            ):
                logger.info(
                    json.dumps(
                        {
                            "event": "prior_event_postgame_skip",
                            "title": item["title"][:120],
                            "post_url": item.get("post_url", ""),
                            "source_name": item.get("source_name", ""),
                        },
                        ensure_ascii=False,
                    )
                )
                skip_filter += 1
                skip_reason_counts["prior_event_postgame"] += 1
                _append_skip_reason_sample(
                    skip_reason_sample_titles,
                    "prior_event_postgame",
                    item["title"],
                )
                continue
            _mismatch_skip, _mismatch_reason = _should_skip_mismatched_today_game(
                category=item["category"],
                title=item["title"],
                summary=item["summary"],
                article_subtype=_detect_article_subtype(
                    item.get("raw_title", item["title"]),
                    item.get("summary", ""),
                    item.get("category", ""),
                    item.get("entry_has_game", True),
                ),
                yahoo_game_status=yahoo_game_status,
            )
            if _mismatch_skip:
                logger.info(
                    json.dumps(
                        {
                            "event": "mismatched_today_game_skip",
                            "reason": _mismatch_reason,
                            "title": item["title"][:120],
                            "post_url": item.get("post_url", ""),
                            "yahoo_opponent": str(yahoo_game_status.get("opponent") or ""),
                            "yahoo_state": str(yahoo_game_status.get("state") or ""),
                        },
                        ensure_ascii=False,
                    )
                )
                skip_filter += 1
                skip_reason_counts["mismatched_today_game"] += 1
                _append_skip_reason_sample(
                    skip_reason_sample_titles,
                    "mismatched_today_game",
                    item["title"],
                )
                continue
            filtered_prepared_entries.append(item)
        prepared_entries = filtered_prepared_entries

    live_update_reason = ""
    game_id_for_live = yahoo_game_status.get("game_id", "")
    if has_game and yahoo_game_status and not yahoo_game_status.get("ended") and game_id_for_live:
        previous_live_state = _load_live_game_state(history, game_id_for_live)
        live_update_reason = _detect_live_update_reason(yahoo_game_status, previous_live_state)

    if has_game and not yahoo_game_status.get("ended") and not _has_primary_lineup_candidate(prepared_entries):
        try:
            yahoo_lineup_rows = fetch_today_giants_lineup_stats_from_yahoo()
        except Exception as e:
            logger.warning("Yahooスタメン固定ページ取得失敗: %s", e)
            yahoo_lineup_rows = []
        synthetic_lineup = _build_yahoo_lineup_candidate(opponent, venue, yahoo_lineup_rows, entry_index)
        if synthetic_lineup and not any(history.get(url) for url in synthetic_lineup.get("history_urls", [])):
            logger.info("  [HIT] Yahoo固定ページからスタメン補完 → 試合速報")
            prepared_category_counts["試合速報"] += 1
            prepared_subtype_counts["lineup"] += 1
            prepared_entries.append(synthetic_lineup)
            prepared_entries = sorted(prepared_entries, key=lambda item: item.get("entry_index", 0))

    if ENABLE_LIVE_UPDATE_ARTICLES and has_game and live_update_reason and not _has_primary_live_candidate(prepared_entries):
        synthetic_live = _build_yahoo_live_update_candidate(opponent, venue, yahoo_game_status, entry_index, live_update_reason)
        if synthetic_live and not any(history.get(url) for url in synthetic_live.get("history_urls", [])):
            logger.info("  [HIT] Yahoo固定ページから途中経過補完 → 試合速報 (%s)", live_update_reason)
            prepared_category_counts["試合速報"] += 1
            prepared_subtype_counts["live_update"] += 1
            prepared_entries.append(synthetic_live)
            prepared_entries = sorted(prepared_entries, key=lambda item: item.get("entry_index", 0))

    if has_game and yahoo_game_status.get("ended") and not _has_primary_postgame_candidate(prepared_entries):
        synthetic_postgame = _build_yahoo_postgame_candidate(opponent, venue, yahoo_game_status, entry_index)
        if synthetic_postgame and not any(history.get(url) for url in synthetic_postgame.get("history_urls", [])):
            logger.info("  [HIT] Yahoo固定ページから試合後補完 → 試合速報")
            prepared_category_counts["試合速報"] += 1
            prepared_subtype_counts["postgame"] += 1
            prepared_entries.append(synthetic_postgame)
            prepared_entries = sorted(prepared_entries, key=lambda item: item.get("entry_index", 0))

    if has_game and game_id_for_live:
        _save_live_game_state(history, game_id_for_live, yahoo_game_status)
        persist_history(history)

    prepared_entries = _prioritize_prepared_entries_for_creation(prepared_entries)
    prepared_entries = _annotate_duplicate_guard_contexts(prepared_entries)
    same_fire_source_urls: set[str] = set()
    same_fire_title_sources: dict[str, set[str]] = {}

    for item in prepared_entries:
        if success >= args.limit:
            logger.info(f"上限{args.limit}件に達したため終了")
            break

        # 2026-05-12 hotfix: defaults for variables that are only
        # populated inside the ``source_type in {"news", "social_news"}``
        # branch (line 23008+); when an article falls into the else
        # passthrough branch (tag_scrape / 非 X URL 等)これらを初期化
        # しないと publish 側の try block で UnboundLocalError になる。
        _article_images: list = []
        # 2026-05-14 C body fix: 前 iter からの stale value で
        # _create_draft_with_same_fire_guard(enrichment_raw_html=...) が呼ばれて
        # excerpt block が誤注入される事故防止 (各 iter 開始で空に reset)。
        _article_raw_html: str = ""
        title_template_key: str = ""

        source_type = item["source_type"]
        category = item["category"]
        title = item["title"]
        raw_title = item.get("raw_title") or title
        summary = item["summary"]
        post_url = item["post_url"]
        source_name = item["source_name"]
        source_handle = item.get("source_handle", "")
        entry_title_norm = item.get("entry_title_norm", "")
        entry_has_game = item["entry_has_game"]
        source_day_label = _format_source_day_label(item.get("published_at"))
        routing_context = dict(item.get("routing_context") or {})
        if not routing_context:
            routing_context = _resolve_rss_story_type_context(
                title=raw_title,
                summary=summary,
                category=category,
                daily_has_game=has_game,
                source_type=source_type,
                source_url=post_url,
                source_name=source_name,
            )
        category = str(routing_context.get("category") or category)
        entry_has_game = bool(routing_context.get("entry_has_game", entry_has_game))
        title_article_subtype = str(
            routing_context.get("title_subtype")
            or _detect_article_subtype(raw_title, summary, category, entry_has_game)
        )
        body_article_subtype = str(routing_context.get("body_subtype") or title_article_subtype)
        validator_article_subtype = str(routing_context.get("validator_subtype") or title_article_subtype)
        effective_story_category = str(
            routing_context.get("effective_generation_category")
            or _resolve_article_generation_category(category, raw_title, summary)
        )
        special_story_kind = str(
            routing_context.get("special_story_kind")
            or (
                _detect_player_special_template_kind(raw_title, summary)
                if effective_story_category == "選手情報"
                else ""
            )
        )

        if item.get("merged_source_count", 0) > 1:
            logger.info(f"  [統合] {title[:40]} ← {item['merged_source_count']}ソース")

        v2_skip_reason = str(routing_context.get("v2_skip_reason") or "").strip()
        if v2_skip_reason:
            skip_filter += 1
            skip_reason_counts[v2_skip_reason] += 1
            _append_skip_reason_sample(skip_reason_sample_titles, v2_skip_reason, raw_title)
            continue

        v2_review_reason = str(routing_context.get("v2_review_reason") or "").strip()
        if v2_review_reason and _post_gen_validate_trusted_bypass(post_url):
            logger.info(json.dumps({
                "event": "post_gen_validate_trusted_source_bypass",
                "fail_axes": ["routing_v2_review"],
                "stop_reason": f"rss_template_routing_v2:{v2_review_reason}",
                "post_url": post_url,
            }, ensure_ascii=False))
            v2_review_reason = ""
        if v2_review_reason:
            skip_filter += 1
            skip_reason_counts["post_gen_validate"] += 1
            _append_skip_reason_sample(skip_reason_sample_titles, "post_gen_validate", raw_title)
            _log_article_skipped_post_gen_validate(
                logger,
                title=raw_title,
                source_title=raw_title,
                post_url=post_url,
                category=category,
                article_subtype=title_article_subtype,
                fail_axes=["routing_v2_review"],
                stop_reason=f"rss_template_routing_v2:{v2_review_reason}",
            )
            if _pre_post_gen_validate_skip_enabled():
                _emit_pre_post_gen_validate_skip(
                    history,
                    post_url=post_url,
                    item=item,
                    fail_axes=["routing_v2_review"],
                    sample_title=raw_title,
                )
            continue

        if source_type in {"news", "social_news"}:
            source_fact_block, source_fact_block_length = _source_fact_block_metrics(
                raw_title,
                summary,
                source_type=source_type,
                entry=item.get("entry"),
            )
            thin_source_min_chars = _thin_source_fact_block_min_chars(source_type)
            if _is_thin_source_fact_block(source_type, source_fact_block_length):
                if _should_skip_thin_source_fact_block(
                    draft_only=bool(args.draft_only),
                    source_type=source_type,
                    source_fact_block_length=source_fact_block_length,
                ):
                    logger.info(
                        json.dumps(
                            {
                                "event": "article_skipped_thin_source",
                                "title": raw_title,
                                "post_url": post_url,
                                "category": category,
                                "article_subtype": title_article_subtype,
                                "source_type": source_type,
                                "source_fact_block_length": source_fact_block_length,
                                "min_chars": thin_source_min_chars,
                            },
                            ensure_ascii=False,
                        )
                    )
                    skip_filter += 1
                    skip_reason_counts["thin_source_fact_block"] += 1
                    _append_skip_reason_sample(skip_reason_sample_titles, "thin_source_fact_block", raw_title)
                    continue
                _log_draft_observed_thin_source(
                    logger,
                    title=raw_title,
                    post_url=post_url,
                    category=category,
                    article_subtype=title_article_subtype,
                    source_type=source_type,
                    source_fact_block_length=source_fact_block_length,
                    min_chars=thin_source_min_chars,
                )
            if args.dry_run:
                draft_title, title_template_key = _rewrite_display_title_with_guard(
                    raw_title,
                    summary,
                    category,
                    entry_has_game,
                    article_subtype=title_article_subtype,
                    logger=logger,
                    source_url=post_url,
                    routing_context=routing_context,
                )
                draft_title, _comparison_title = _apply_title_player_name_backfill(
                    rewritten_title=draft_title,
                    source_title=raw_title,
                    source_body=summary,
                    summary=summary,
                    category=category,
                    article_subtype=title_article_subtype,
                    manager_subject="",
                    notice_subject="",
                    logger=logger,
                    source_name=source_name,
                    source_url=post_url,
                )
                draft_title, _weak_title_rescue_reason = _maybe_apply_weak_title_rescue(
                    rewritten_title=draft_title,
                    source_title=raw_title,
                    source_body=summary,
                    summary=summary,
                    category=category,
                    article_subtype=title_article_subtype,
                    manager_subject="",
                    notice_subject="",
                    logger=logger,
                    source_name=source_name,
                    source_url=post_url,
                )
                if not _rss_template_routing_v2_enabled():
                    draft_title = _maybe_apply_manager_quote_short_title_repair(
                        rewritten_title=draft_title,
                        source_title=raw_title,
                        source_body=summary,
                        summary=summary,
                        category=category,
                        article_subtype=title_article_subtype,
                        logger=logger,
                        source_url=post_url,
                    )
                else:
                    draft_title, _finalize_review = _finalize_title(
                        draft_title,
                        source_title=raw_title,
                        summary=summary,
                        analysis=routing_context.get("source_analysis_v2") if isinstance(routing_context.get("source_analysis_v2"), Mapping) else None,
                    )
                _log_title_template_selected(logger, post_url, raw_title, draft_title, title_template_key, category, title_article_subtype)
                print(f"  DRY: [{category}] {draft_title[:50]}")
                print(f"       {post_url}")
                success += 1
                continue
            media_story_kind = special_story_kind
            manager_subject = ""
            manager_aliases: list[str] = []
            notice_subject = ""
            notice_type = ""
            player_aliases: list[str] = []
            if special_story_kind == "player_notice":
                notice_subject, notice_type = _extract_notice_subject_and_type(raw_title, summary)
                family_alias = _player_family_name_alias(raw_title, summary, "選手情報")
                player_aliases = _dedupe_preserve_order([alias for alias in [notice_subject, family_alias] if alias])
            elif category == "首脳陣" and title_article_subtype == "manager":
                media_story_kind = "manager_quote"
                manager_subject = _extract_subject_label(raw_title, summary, "首脳陣")
                compact_manager_subject = _re.sub(r"(監督|コーチ)$", "", manager_subject).strip()
                manager_aliases = _dedupe_preserve_order(
                    [
                        alias
                        for alias in [manager_subject, compact_manager_subject]
                        if alias and alias not in {"首脳陣", "巨人"}
                    ]
                )
            topic_aliases = _dedupe_preserve_order(player_aliases or manager_aliases)
            if not topic_aliases:
                compact_subject = _compact_subject_label(raw_title, summary, effective_story_category)
                if compact_subject and compact_subject not in {"巨人", "選手", "首脳陣"}:
                    topic_aliases.append(compact_subject)
                family_alias_for_topic = _player_family_name_alias(raw_title, summary, effective_story_category)
                if family_alias_for_topic:
                    topic_aliases.append(family_alias_for_topic)
                topic_aliases = _dedupe_preserve_order(topic_aliases)
            media_quote_max_count = 1
            if media_story_kind in {"player_notice", "manager_quote"}:
                media_quote_max_count = 2
            elif source_type == "social_news" and category in {"試合速報", "選手情報", "首脳陣"}:
                media_quote_max_count = 2

            media_quote_evaluation = evaluate_media_quote_selection(
                {
                    "source_type": source_type,
                    "source_url": post_url,
                    "source_name": source_name,
                    "title": raw_title,
                    "summary": summary,
                    "created_at": item.get("published_at").isoformat() if item.get("published_at") else "",
                    "story_kind": media_story_kind,
                    "player_name": notice_subject,
                    "player_aliases": player_aliases,
                    "notice_type": notice_type,
                    "manager_name": manager_subject,
                    "manager_aliases": manager_aliases,
                    "article_subtype": title_article_subtype,
                    "category": category,
                    "topic_aliases": topic_aliases,
                },
                max_count=media_quote_max_count,
                media_quote_pool=media_quote_pool,
            )
            media_quotes = media_quote_evaluation["quotes"]
            entry_obj = item.get("entry") if isinstance(item.get("entry"), dict) else {}
            _article_raw_html = ""
            if source_type in {"news", "tag_scrape"}:
                _article_raw_html = str(entry_obj.get("_html") or "")
                _raw_from_entry = bool(_article_raw_html)
                if not _article_raw_html:
                    _article_raw_html = _fetch_url_html(post_url, max_bytes=240000, timeout=12)
                # 2026-05-14: raw_html 0 字事象の root cause 切り分け用 observability。
                # 期待: source_type=news/tag_scrape では entry _html か _fetch_url_html
                # のどちらかで >0 字。0 字は excerpt block 永続 skip の原因。
                logger.info(
                    "article_raw_html_resolved post_url=%s source_type=%s "
                    "from_entry=%s raw_html_len=%d",
                    post_url,
                    source_type,
                    _raw_from_entry,
                    len(_article_raw_html or ""),
                )
            _article_images = _extract_source_article_image_urls(
                source_type,
                entry_obj,
                post_url,
                _article_raw_html,
                max_images=3,
            )
            _article_images = _filter_image_candidates(_article_images, post_url, logger)
            _article_images = _refetch_article_images_if_empty(_article_images, post_url, logger, max_images=3)
            _article_images = _ensure_story_featured_images(
                _article_images,
                raw_title,
                summary,
                category,
                title_article_subtype,
                source_url=post_url,
                logger=logger,
            )
            _og_url  = _article_images[0] if _article_images else ""
            draft_title, title_template_key = _rewrite_display_title_with_guard(
                raw_title,
                summary,
                category,
                entry_has_game,
                article_subtype=title_article_subtype,
                logger=logger,
                source_url=post_url,
                routing_context=routing_context,
            )
            draft_title, comparison_title = _apply_title_player_name_backfill(
                rewritten_title=draft_title,
                source_title=raw_title,
                source_body=summary,
                summary=summary,
                category=category,
                article_subtype=title_article_subtype,
                manager_subject=manager_subject,
                notice_subject=notice_subject,
                logger=logger,
                source_name=source_name,
                source_url=post_url,
            )
            weak_title_metadata = _build_title_player_name_backfill_metadata(
                raw_title,
                summary,
                category,
                title_article_subtype,
                manager_subject=manager_subject,
                notice_subject=notice_subject,
            )
            weak_title_metadata.update(
                {
                    "article_subtype": title_article_subtype,
                    "category": category,
                    "special_story_kind": special_story_kind,
                    "notice_type": notice_type,
                    "notice_subject": notice_subject,
                    "manager_name": manager_subject,
                    "published_at": item.get("published_at"),
                    "game_date": source_day_label,
                    "game_time": _extract_game_time_token(f"{raw_title} {summary}"),
                    "score": item.get("scoreline") or item.get("score") or "",
                    "opponent": item.get("opponent") or "",
                    "team_scope": (
                        item.get("team_scope")
                        if isinstance(item, dict)
                        else ""
                    )
                    or (
                        item.get("duplicate_guard_context", {}).get("team_scope")
                        if isinstance(item.get("duplicate_guard_context"), dict)
                        else ""
                    ),
                    "farm": category == "ドラフト・育成" or title_article_subtype in {"farm", "farm_lineup", "farm_result"},
                }
            )
            fan_important_post_meta = {
                **weak_title_metadata,
                "source_name": source_name,
                "source_handle": source_handle,
                "source_title": raw_title,
                "source_body": summary,
                "summary": summary,
                "category": category,
                "article_subtype": title_article_subtype,
            }
            title_player_name_unresolved = bool(
                comparison_title == draft_title
                and title_article_subtype in {"manager", "player", "notice", "recovery", "player_notice", "player_recovery"}
                and not title_has_person_name_candidate(draft_title)
            )
            draft_title, _weak_title_rescue_reason = _maybe_apply_weak_title_rescue(
                rewritten_title=draft_title,
                source_title=raw_title,
                source_body=summary,
                summary=summary,
                category=category,
                article_subtype=title_article_subtype,
                manager_subject=manager_subject,
                notice_subject=notice_subject,
                logger=logger,
                source_name=source_name,
                source_url=post_url,
                metadata=weak_title_metadata,
            )
            if not _rss_template_routing_v2_enabled():
                draft_title = _maybe_apply_manager_quote_short_title_repair(
                    rewritten_title=draft_title,
                    source_title=raw_title,
                    source_body=summary,
                    summary=summary,
                    category=category,
                    article_subtype=title_article_subtype,
                    logger=logger,
                    source_url=post_url,
                    metadata=weak_title_metadata,
                )
            else:
                draft_title, finalize_title_review = _finalize_title(
                    draft_title,
                    source_title=raw_title,
                    summary=summary,
                    analysis=routing_context.get("source_analysis_v2") if isinstance(routing_context.get("source_analysis_v2"), Mapping) else None,
                )
                if isinstance(finalize_title_review, _WeakTitleReviewFallback) and _post_gen_validate_trusted_bypass(post_url):
                    logger.info(json.dumps({
                        "event": "post_gen_validate_trusted_source_bypass",
                        "fail_axes": [f"weak_generated_title:{finalize_title_review.reason}"],
                        "stop_reason": "weak_generated_title_review",
                        "post_url": post_url,
                    }, ensure_ascii=False))
                    finalize_title_review = None
                if isinstance(finalize_title_review, _WeakTitleReviewFallback):
                    skip_filter += 1
                    skip_reason_counts["post_gen_validate"] += 1
                    _append_skip_reason_sample(skip_reason_sample_titles, "post_gen_validate", draft_title)
                    _log_article_skipped_post_gen_validate(
                        logger,
                        title=draft_title,
                        source_title=raw_title,
                        post_url=post_url,
                        category=category,
                        article_subtype=title_article_subtype,
                        fail_axes=[f"weak_generated_title:{finalize_title_review.reason}"],
                        stop_reason="weak_generated_title_review",
                    )
                    if _pre_post_gen_validate_skip_enabled():
                        _emit_pre_post_gen_validate_skip(
                            history,
                            post_url=post_url,
                            item=item,
                            fail_axes=[f"weak_generated_title:{finalize_title_review.reason}"],
                            sample_title=draft_title or raw_title,
                        )
                    continue
            draft_title, generic_title_review = _maybe_apply_generic_title_repair(
                rewritten_title=draft_title,
                source_title=raw_title,
                summary=summary,
                category=category,
                article_subtype=title_article_subtype,
                logger=logger,
                metadata=weak_title_metadata,
            )
            if isinstance(generic_title_review, _WeakTitleReviewFallback) and _post_gen_validate_trusted_bypass(post_url):
                logger.info(json.dumps({
                    "event": "post_gen_validate_trusted_source_bypass",
                    "fail_axes": [f"generic_title:{generic_title_review.reason}"],
                    "stop_reason": "generic_title_repair_review",
                    "post_url": post_url,
                }, ensure_ascii=False))
                generic_title_review = None
            if isinstance(generic_title_review, _WeakTitleReviewFallback):
                skip_filter += 1
                skip_reason_counts["post_gen_validate"] += 1
                _append_skip_reason_sample(skip_reason_sample_titles, "post_gen_validate", draft_title)
                _log_article_skipped_post_gen_validate(
                    logger,
                    title=draft_title,
                    source_title=raw_title,
                    post_url=post_url,
                    category=category,
                    article_subtype=title_article_subtype,
                    fail_axes=[f"generic_title:{generic_title_review.reason}"],
                    stop_reason="generic_title_repair_review",
                )
                if _pre_post_gen_validate_skip_enabled():
                    _emit_pre_post_gen_validate_skip(
                        history,
                        post_url=post_url,
                        item=item,
                        fail_axes=[f"generic_title:{generic_title_review.reason}"],
                        sample_title=draft_title or raw_title,
                    )
                continue
            weak_title_fallback = _maybe_route_weak_generated_title_review(
                article_subtype=title_article_subtype,
                rewritten_title=draft_title,
                original_title=comparison_title,
                source_name=source_name,
                logger=logger,
                source_url=post_url,
                source_title=raw_title,
                source_body=summary,
                summary=summary,
                metadata=weak_title_metadata,
                weak_title_rescue_reason=_weak_title_rescue_reason,
                duplicate_guard_context=item.get("duplicate_guard_context"),
                title_player_name_unresolved=title_player_name_unresolved,
            )
            if isinstance(weak_title_fallback, _WeakTitleReviewFallback) and _post_gen_validate_trusted_bypass(post_url):
                logger.info(json.dumps({
                    "event": "post_gen_validate_trusted_source_bypass",
                    "fail_axes": [f"weak_generated_title:{weak_title_fallback.reason}"],
                    "stop_reason": "weak_generated_title_review",
                    "post_url": post_url,
                }, ensure_ascii=False))
                weak_title_fallback = None
            if isinstance(weak_title_fallback, _WeakTitleReviewFallback):
                skip_filter += 1
                skip_reason_counts["post_gen_validate"] += 1
                _append_skip_reason_sample(skip_reason_sample_titles, "post_gen_validate", draft_title)
                _log_article_skipped_post_gen_validate(
                    logger,
                    title=draft_title,
                    source_title=raw_title,
                    post_url=post_url,
                    category=category,
                    article_subtype=title_article_subtype,
                    fail_axes=[f"weak_generated_title:{weak_title_fallback.reason}"],
                    stop_reason="weak_generated_title_review",
                )
                if _pre_post_gen_validate_skip_enabled():
                    _emit_pre_post_gen_validate_skip(
                        history,
                        post_url=post_url,
                        item=item,
                        fail_axes=[f"weak_generated_title:{weak_title_fallback.reason}"],
                        sample_title=draft_title or raw_title,
                    )
                continue
            weak_subject_fallback = _maybe_route_weak_subject_title_review(
                article_subtype=title_article_subtype,
                rewritten_title=draft_title,
                original_title=comparison_title,
                source_name=source_name,
                logger=logger,
                speaker_name=manager_subject or notice_subject,
                source_url=post_url,
                source_title=raw_title,
                source_body=summary,
                summary=summary,
                metadata=weak_title_metadata,
                weak_title_rescue_reason=_weak_title_rescue_reason,
                duplicate_guard_context=item.get("duplicate_guard_context"),
                title_player_name_unresolved=title_player_name_unresolved,
            )
            if isinstance(weak_subject_fallback, _WeakTitleReviewFallback):
                skip_filter += 1
                skip_reason_counts["post_gen_validate"] += 1
                _append_skip_reason_sample(skip_reason_sample_titles, "post_gen_validate", draft_title)
                _log_article_skipped_post_gen_validate(
                    logger,
                    title=draft_title,
                    source_title=raw_title,
                    post_url=post_url,
                    category=category,
                    article_subtype=title_article_subtype,
                    fail_axes=[f"weak_subject_title:{weak_subject_fallback.reason}"],
                    stop_reason="weak_subject_title_review",
                )
                if _pre_post_gen_validate_skip_enabled():
                    _emit_pre_post_gen_validate_skip(
                        history,
                        post_url=post_url,
                        item=item,
                        fail_axes=[f"weak_subject_title:{weak_subject_fallback.reason}"],
                        sample_title=draft_title or raw_title,
                    )
                continue
            _log_title_template_selected(logger, post_url, raw_title, draft_title, title_template_key, category, title_article_subtype)
            duplicate_guard_context = item.get("duplicate_guard_context")
            if isinstance(duplicate_guard_context, dict):
                duplicate_outcome = _evaluate_pre_gemini_duplicate_guard(
                    logger,
                    duplicate_guard_context,
                    duplicate_history=history,
                )
                if duplicate_outcome == "skip":
                    skip_filter += 1
                    skip_reason_counts["duplicate_news_pre_gemini_skip"] += 1
                    _append_skip_reason_sample(skip_reason_sample_titles, "duplicate_news_pre_gemini_skip", draft_title)
                    continue
            content, ai_body_for_x = build_news_block(
                title,
                summary,
                post_url,
                source_name,
                category,
                _og_url,
                0,
                extra_images=_article_images[1:],
                has_game=entry_has_game,
                article_ai_mode_override=args.article_ai_mode,
                source_links=item.get("source_links"),
                source_day_label=source_day_label,
                source_type=source_type,
                media_quotes=media_quotes,
                source_entry=item.get("entry"),
                post_context=item,
                published_at=item.get("published_at"),
                duplicate_guard_context=item.get("duplicate_guard_context"),
                duplicate_history=history,
                rewritten_title=draft_title,
                routing_context=routing_context,
            )
            body_article_subtype = str(routing_context.get("body_subtype") or body_article_subtype)
            validator_article_subtype = str(routing_context.get("validator_subtype") or validator_article_subtype)
            effective_story_category = str(
                routing_context.get("effective_generation_category") or effective_story_category
            )
            duplicate_guard_context = item.get("duplicate_guard_context")
            if isinstance(duplicate_guard_context, dict) and duplicate_guard_context.get("guard_outcome") == "skip":
                skip_filter += 1
                skip_reason_counts["duplicate_news_pre_gemini_skip"] += 1
                _append_skip_reason_sample(skip_reason_sample_titles, "duplicate_news_pre_gemini_skip", draft_title)
                continue
            strict_review_reason = (
                str(duplicate_guard_context.get("postgame_strict_review_reason") or "").strip()
                if isinstance(duplicate_guard_context, dict)
                else ""
            )
            if strict_review_reason:
                skip_filter += 1
                skip_reason_counts["post_gen_validate"] += 1
                _append_skip_reason_sample(skip_reason_sample_titles, "post_gen_validate", draft_title)
                _log_article_skipped_post_gen_validate(
                    logger,
                    title=draft_title,
                    source_title=raw_title,
                    post_url=post_url,
                    category=category,
                    article_subtype=title_article_subtype,
                    fail_axes=["postgame_strict_review"],
                    stop_reason=f"postgame_strict:{strict_review_reason}",
                )
                if _pre_post_gen_validate_skip_enabled():
                    _emit_pre_post_gen_validate_skip(
                        history,
                        post_url=post_url,
                        item=item,
                        fail_axes=["postgame_strict_review"],
                        sample_title=draft_title or raw_title,
                    )
                continue
            manager_quote_zero_review_reason = (
                str(duplicate_guard_context.get("manager_quote_zero_review_reason") or "").strip()
                if isinstance(duplicate_guard_context, dict)
                else ""
            )
            if manager_quote_zero_review_reason:
                skip_filter += 1
                skip_reason_counts["post_gen_validate"] += 1
                _append_skip_reason_sample(skip_reason_sample_titles, "post_gen_validate", draft_title)
                _log_article_skipped_post_gen_validate(
                    logger,
                    title=draft_title,
                    source_title=raw_title,
                    post_url=post_url,
                    category=category,
                    article_subtype=title_article_subtype,
                    fail_axes=["manager_quote_zero_review"],
                    stop_reason=f"manager_quote_zero_review:{manager_quote_zero_review_reason}",
                )
                if _pre_post_gen_validate_skip_enabled():
                    _emit_pre_post_gen_validate_skip(
                        history,
                        post_url=post_url,
                        item=item,
                        fail_axes=["manager_quote_zero_review"],
                        sample_title=draft_title or raw_title,
                    )
                continue
            fact_conflict_source_refs = {
                "title": draft_title,
                "source_title": raw_title,
                "source_summary": summary,
                "summary": summary,
                "source_name": source_name,
                "source_url": post_url,
                "source_type": source_type,
                "source_links": item.get("source_links"),
                "game_id": item.get("game_id"),
                "scoreline": item.get("scoreline") or item.get("score") or "",
                "team_result": item.get("team_result") or "",
                "opponent": item.get("opponent") or "",
            }
            body_contract_validate = _validate_body_candidate(
                ai_body_for_x,
                validator_article_subtype,
                rendered_html=content,
                source_context=fact_conflict_source_refs,
            )
            if not body_contract_validate["ok"]:
                fan_important_exempt = _fetcher_fan_important_narrow_exempt_context(
                    skip_kind="body_contract_validate",
                    post_meta=fan_important_post_meta,
                    source_url=post_url,
                    title=draft_title,
                    validation=body_contract_validate,
                )
                if fan_important_exempt:
                    _log_fetcher_fan_important_narrow_exempt(
                        logger,
                        skip_kind="body_contract_validate",
                        source_url=post_url,
                        title=draft_title,
                        context=fan_important_exempt,
                    )
                elif _post_gen_validate_trusted_bypass(post_url):
                    logger.info(json.dumps({
                        "event": "post_gen_validate_trusted_source_bypass",
                        "fail_axes": ["body_contract_validate"],
                        "stop_reason": "body_contract_validate",
                        "post_url": post_url,
                    }, ensure_ascii=False))
                    body_contract_validate = {"ok": True, "action": "pass"}
                else:
                    skip_filter += 1
                    skip_reason_counts["body_contract_validate"] += 1
                    _append_skip_reason_sample(skip_reason_sample_titles, "body_contract_validate", draft_title)
                    if body_contract_validate["action"] == "fail":
                        _log_body_validator_fail(
                            logger,
                            source_url=post_url,
                            category=category,
                            article_subtype=validator_article_subtype,
                            fail_axes=list(body_contract_validate["fail_axes"]),
                            expected_first_block=str(body_contract_validate.get("expected_first_block") or ""),
                            actual_first_block=str(body_contract_validate.get("actual_first_block") or ""),
                            has_source_block=bool(body_contract_validate.get("has_source_block", False)),
                            stop_reason=str(body_contract_validate.get("stop_reason") or ""),
                        )
                    else:
                        _log_body_validator_reroll(
                            logger,
                            source_url=post_url,
                            category=category,
                            article_subtype=validator_article_subtype,
                            fail_axes=list(body_contract_validate["fail_axes"]),
                            expected_first_block=str(body_contract_validate.get("expected_first_block") or ""),
                            actual_first_block=str(body_contract_validate.get("actual_first_block") or ""),
                            missing_required_blocks=list(body_contract_validate.get("missing_required_blocks") or []),
                            actual_block_order=list(body_contract_validate.get("actual_block_order") or []),
                        )
                    if _env_flag(BODY_CONTRACT_FAIL_LEDGER_ENV_FLAG, False):
                        body_contract_fail_ledger_path = str(
                            os.environ.get(BODY_CONTRACT_FAIL_LEDGER_PATH_ENV_FLAG, "")
                        ).strip()
                        record_body_contract_fail(
                            source_url=post_url,
                            source_title=raw_title,
                            generated_title=draft_title,
                            category=category,
                            article_subtype=validator_article_subtype,
                            validation_result=body_contract_validate,
                            validation_action=str(body_contract_validate.get("action") or "fail"),
                            body_excerpt=ai_body_for_x,
                            logger=logger,
                            ledger_path=body_contract_fail_ledger_path or None,
                        )
                    continue
            preview_body_html = _render_preview_body_html(ai_body_for_x)
            post_gen_validate = _evaluate_post_gen_validate(
                ai_body_for_x,
                article_subtype=validator_article_subtype,
                title=draft_title,
                source_refs=fact_conflict_source_refs,
                rendered_html=preview_body_html,
            )
            if (
                not post_gen_validate["ok"]
                and any(str(axis).startswith("entity_mismatch:") for axis in post_gen_validate["fail_axes"])
            ):
                repair_preview = _maybe_apply_entity_mismatch_repair(
                    title=draft_title,
                    body_text=ai_body_for_x,
                    body_html=content,
                    source_title=raw_title,
                    source_summary=summary,
                    article_subtype=validator_article_subtype,
                    source_refs=fact_conflict_source_refs,
                    logger=logger,
                    source_url=post_url,
                )
                if repair_preview is not None:
                    post_gen_validate = repair_preview["validation"]
                    if repair_preview["applied"]:
                        draft_title = str(repair_preview["title"] or draft_title)
                        ai_body_for_x = str(repair_preview["body_text"] or ai_body_for_x)
                        content = str(repair_preview["body_html"] or content)
                        fact_conflict_source_refs["title"] = draft_title
            if not post_gen_validate["ok"]:
                fan_important_exempt = _fetcher_fan_important_narrow_exempt_context(
                    skip_kind="post_gen_validate",
                    post_meta=fan_important_post_meta,
                    source_url=post_url,
                    title=draft_title,
                    validation=post_gen_validate,
                )
                if fan_important_exempt:
                    _log_fetcher_fan_important_narrow_exempt(
                        logger,
                        skip_kind="post_gen_validate",
                        source_url=post_url,
                        title=draft_title,
                        context=fan_important_exempt,
                    )
                elif _post_gen_validate_trusted_bypass_full(post_url):
                    # RELIABILITY-2026-05-08-D: trusted family の全 fail axes bypass。
                    # nikkansports / hochi / sponichi / sanspo / daily / giants_official /
                    # npb_official の RSS は close_marker / placeholder_body /
                    # duplicate_sentence / weak_subject_title / source_grounding_drift
                    # 全部 bypass で publish path に進む。X 系 / 非 trusted は通常 skip。
                    bypass_full_invocation_count += 1
                    logger.info(json.dumps({
                        "event": "post_gen_validate_trusted_source_bypass",
                        "fail_axes": list(post_gen_validate["fail_axes"]),
                        "stop_reason": str(post_gen_validate.get("stop_reason") or ""),
                        "post_url": post_url,
                        "scope": "full_axes",
                    }, ensure_ascii=False))
                    post_gen_validate = {
                        "ok": True,
                        "fail_axes": [],
                        "final_section_heading": post_gen_validate.get("final_section_heading", ""),
                        "final_section_text": post_gen_validate.get("final_section_text", ""),
                        "stop_reason": "",
                    }
                elif (
                    _post_gen_validate_review_draft_enabled()
                    and _is_review_eligible_fail_axes(list(post_gen_validate["fail_axes"]))
                ):
                    # RELIABILITY-2026-05-08-E: post_gen_validate fail を skip ではなく
                    # 「【要review｜post_gen_validate】」prefix 付き draft で残す。force
                    # draft (RUN_DRAFT_ONLY=0 でも publish しない) で安全側、user が WP
                    # 管理画面で本文 check + 手動 flip 判断できる。fail history 記録は
                    # 既存通り (TTL 24h dedup) 維持。
                    # E2 (2026-05-08 afternoon): 致命的軸 (placeholder_body /
                    # entity_mismatch / fact_conflict 系) を含む fail は review draft
                    # 化せず通常 skip path に流す。memory rule の限定 6 STOP gate を
                    # 維持 + review draft 蓄積を抑制。
                    review_title = _POST_GEN_VALIDATE_REVIEW_DRAFT_TITLE_PREFIX + draft_title
                    review_draft_created = False
                    review_post_id_logged: int | None = None
                    try:
                        review_cats = _resolve_draft_category_ids(wp, category, logger)
                        review_post_id_logged = _create_draft_with_same_fire_guard(
                            wp,
                            logger,
                            same_fire_source_urls,
                            same_fire_title_sources,
                            review_title,
                            content,
                            review_cats,
                            post_url,
                            featured_media=None,
                            force_status="draft",
                            enrichment_summary=summary,
                            enrichment_category=category,
                            enrichment_template_key=str(title_template_key or ""),
                            enrichment_source_name=source_name,
                            # 2026-05-14 fix: review path も raw_html を渡す。
                            # main path は raw_html を渡しているが review path
                            # (post_gen_validate fail で要review draft 化された
                            # 記事) では渡されておらず、引用 block が永続的に
                            # 出ない silent skip 原因の 1 つだった。
                            enrichment_raw_html=_article_raw_html,
                            enrichment_source_type=source_type,
                        )
                        if review_post_id_logged and review_post_id_logged > 0:
                            review_draft_created = True
                            review_drafts_created_count += 1
                            # axis prefix で集計 ("placeholder_body:empty_section" は
                            # "placeholder_body" 扱い)。E2 で critical 軸は来ないが、防御的に
                            # 全軸 record。
                            for _axis in post_gen_validate["fail_axes"]:
                                _axis_prefix = str(_axis or "").split(":", 1)[0].strip()
                                if _axis_prefix:
                                    review_drafts_axes_breakdown[_axis_prefix] += 1
                            logger.info(json.dumps({
                                "event": "post_gen_validate_review_draft_created",
                                "post_id": review_post_id_logged,
                                "fail_axes": list(post_gen_validate["fail_axes"]),
                                "stop_reason": str(post_gen_validate.get("stop_reason") or ""),
                                "post_url": post_url,
                                "title": review_title,
                            }, ensure_ascii=False))
                        else:
                            # RELIABILITY-2026-05-08-DUP-FIX: same-fire dedup で 0 が返った時、
                            # review_draft_created は False のまま下の skip_filter path に流す。
                            logger.info(
                                "review_draft_same_fire_duplicate_skip post_url=%s",
                                post_url,
                            )
                    except Exception as exc:  # noqa: BLE001
                        logger.warning(
                            "post_gen_validate_review_draft_creation_failed reason=%s post_url=%s",
                            exc,
                            post_url,
                        )
                    if not review_draft_created:
                        skip_filter += 1
                        skip_reason_counts["post_gen_validate"] += 1
                        _append_skip_reason_sample(skip_reason_sample_titles, "post_gen_validate", draft_title)
                        _log_article_skipped_post_gen_validate(
                            logger,
                            title=draft_title,
                            source_title=raw_title,
                            post_url=post_url,
                            category=category,
                            article_subtype=validator_article_subtype,
                            fail_axes=list(post_gen_validate["fail_axes"]),
                            stop_reason=str(post_gen_validate.get("stop_reason") or ""),
                        )
                    _record_post_gen_validate_failure(
                        history,
                        post_url=post_url,
                        x_status_id=_extract_x_status_id(post_url or ""),
                        entry_title_norm=item.get("entry_title_norm", "") or "",
                        fail_axes=list(post_gen_validate["fail_axes"]),
                    )
                    persist_history(history)
                    continue
                else:
                    skip_filter += 1
                    skip_reason_counts["post_gen_validate"] += 1
                    _append_skip_reason_sample(skip_reason_sample_titles, "post_gen_validate", draft_title)
                    _log_article_skipped_post_gen_validate(
                        logger,
                        title=draft_title,
                        source_title=raw_title,
                        post_url=post_url,
                        category=category,
                        article_subtype=validator_article_subtype,
                        fail_axes=list(post_gen_validate["fail_axes"]),
                        stop_reason=str(post_gen_validate.get("stop_reason") or ""),
                    )
                    # RSS-255: post_gen_validate fail を fail history に記録 (TTL 24h)。
                    # 次 cycle 以降、同じ x_status_id / source_url を early skip して
                    # Gemini call / Cloud Run 時間 / fetcher 詰まりを削減。
                    _record_post_gen_validate_failure(
                        history,
                        post_url=post_url,
                        x_status_id=_extract_x_status_id(post_url or ""),
                        entry_title_norm=item.get("entry_title_norm", "") or "",
                        fail_axes=list(post_gen_validate["fail_axes"]),
                    )
                    persist_history(history)
                    continue
        else:
            # RELIABILITY-2026-05-08-G: 13:04 JST incident 防止。
            # 非 X URL を build_oembed_block に渡すと <blockquote
            # class="twitter-tweet"> wrapper を生成、Twitter widgets.js は
            # 非 X URL を tweet 化できず thin body publish になる。
            # is_x_url で判定し、非 X URL は _build_body_for_news の
            # nomotoke-shell passthrough body (lead + 出典 + footer) を生成、
            # nomotoke-card- marker 入りで enrichment が走る形にする。
            from wp_draft_creator import is_x_url as _is_x_url
            # NEWS-BANNER-FIX-2026-05-15: passthrough 経路 (oembed / 非 X URL) は
            # build_news_block を通らないため、helper で banner を冒頭に prepend
            # し、build_news_block 経路と同じ赤紫グラデ banner で揃える。
            _passthrough_banner = _giants_news_banner_html(title, source_name, category)
            if _is_x_url(post_url):
                content = _passthrough_banner + build_oembed_block(post_url)
                _passthrough_label = "oembed_passthrough"
            else:
                from src.tools.manual_intake import _build_body_for_news
                content = _passthrough_banner + _build_body_for_news(
                    source_url=post_url,
                    title=title,
                    summary=summary or "",
                )
                _passthrough_label = "non_x_url_passthrough"
            ai_body_for_x = ""
            draft_title = title
            # 2026-05-12 hotfix(B、proper fix): else パスでも _article_images と
            # title_template_key を正規代入する。if-branch と同じ画像抽出
            # logic を mirror。これで try block(23856+)の _article_images
            # 参照(23895 eyecatch fallback / 24066 candidate_count log)が
            # else パス記事(tag_scrape / 非 X URL)でも実 candidate を見る。
            entry_obj_else = item.get("entry") if isinstance(item.get("entry"), dict) else {}
            _article_raw_html_else = ""
            if source_type == "tag_scrape":
                _article_raw_html_else = str(entry_obj_else.get("_html") or "")
                if not _article_raw_html_else:
                    _article_raw_html_else = _fetch_url_html(post_url, max_bytes=240000, timeout=12)
            # 2026-05-14 C body fix: tag_scrape (hochi / daily / tokyo-sports /
            # sponichi の web 記事) で取得した raw_html を後段の
            # _create_draft_with_same_fire_guard(enrichment_raw_html=...) にも
            # 反映する。直前まで _article_raw_html_else は image 抽出にしか
            # 使われず、excerpt insertion 用 _article_raw_html は空のまま
            # (no_raw_html silent skip の root cause だった)。
            _article_raw_html = _article_raw_html_else
            _article_images = _extract_source_article_image_urls(
                source_type,
                entry_obj_else,
                post_url,
                _article_raw_html_else,
                max_images=3,
            )
            _article_images = _filter_image_candidates(_article_images, post_url, logger)
            _article_images = _refetch_article_images_if_empty(_article_images, post_url, logger, max_images=3)
            title_template_key = _passthrough_label
            _log_title_template_selected(logger, post_url, raw_title, draft_title, _passthrough_label, category, title_article_subtype)
            if args.dry_run:
                print(f"  DRY: [{category}] {draft_title[:50]}")
                print(f"       {post_url}")
                success += 1
                continue

        try:
            _log_title_collision_if_needed(logger, history, post_url, draft_title)
            cats = _resolve_draft_category_ids(wp, category, logger)

            featured_media = 0
            # 2026-05-13 user-requested order: ① source og:image
            # → ② 保存選手写真 → ③ team fallback (巨人マーク).
            # まず recent media dedupe set を取得して source 候補に渡す。
            # kill switch: EYECATCH_DEDUPE_RECENT_DISABLED=1
            recent_used = _recently_used_featured_media_ids(
                wp,
                window_seconds=3600,
                logger=logger,
            )
            # ① source 由来 og:image を最優先。_article_images は if/else
            # 両分岐で populate 済(else は 24087+ hotfix B)。generic source
            # と recent dedupe は内部で skip されるので、全部落ちれば 0 を
            # 返して次段に進む。
            if _article_images:
                featured_media = _upload_featured_media_with_fallback(
                    wp,
                    _article_images,
                    post_url,
                    logger,
                    recent_used=recent_used,
                )
            # ② source が 0 のとき、title に巨人選手 1 人が確定するなら
            # 保存写真にフォールバック。kill switch:
            # EYECATCH_PLAYER_PRIORITY_DISABLED=1。さらに 0 のときは
            # 後段の wp_client.create_post 内 auto-eyecatch で
            # ③ team fallback (PLAYER_EYECATCH_TEAM_FALLBACK_MEDIA_ID,
            # 巨人マーク) が適用される。
            if featured_media == 0:
                featured_media = _resolve_high_confidence_player_media_id(
                    draft_title,
                    wp,
                    logger,
                )

            # 336-QA Phase 3: 報知 parent + raw_html 取得済なら 600字 excerpt を
            # payload.hochi_raw_html_excerpt に populate (render 前)。idempotent。
            if (
                item.get("subtype_hint") == "player_voice_digest"
                and isinstance(item.get("digest_cluster_payload"), dict)
                and item["digest_cluster_payload"].get("parent_family") == "hochi"
                and not item["digest_cluster_payload"].get("hochi_raw_html_excerpt")
                and _article_raw_html
            ):
                try:
                    from src.source_article_body_extractor import (
                        extract_article_body_excerpt,
                    )
                    _hochi_excerpt = extract_article_body_excerpt(
                        _article_raw_html,
                        source_url=post_url,
                        max_chars=600,
                        title=str(item.get("title") or ""),
                    )
                    if _hochi_excerpt:
                        item["digest_cluster_payload"][
                            "hochi_raw_html_excerpt"
                        ] = _hochi_excerpt
                        logger.info(
                            "digest_hochi_excerpt_populated url=%s len=%d",
                            post_url,
                            len(_hochi_excerpt),
                        )
                except Exception as _exc:  # noqa: BLE001
                    logger.warning(
                        "digest_hochi_excerpt_failed err=%s url=%s",
                        _exc,
                        post_url,
                    )

            # 334-QA Phase 3b: player_voice_digest subtype 検出時に body 全置換。
            # Phase 2c で item.subtype_hint + item.digest_cluster_payload が
            # 入っている場合のみ動く。render_player_voice_digest_body が空文字
            # を返した場合 (payload 不整合 etc) は通常 flow に fall-through。
            # 例外時は existing flow を絶対に壊さない (warning log のみ)。
            _digest_body_applied = False
            if item.get("subtype_hint") == "player_voice_digest" and isinstance(
                item.get("digest_cluster_payload"), dict
            ):
                try:
                    _digest_body = _render_player_voice_digest_body(item)
                except Exception as _digest_exc:  # noqa: BLE001
                    logger.warning(
                        "player_voice_digest_render_failed err=%s post_url=%s",
                        _digest_exc,
                        post_url,
                    )
                    _digest_body = ""
                if _digest_body:
                    # NEWS-BANNER-FIX-2026-05-15: digest 本文は build_news_block
                    # の出力を完全置換するため、そのまま代入すると赤紫グラデ
                    # banner が消える。helper で同じ banner を冒頭に prepend し、
                    # 全 publish 経路で content の先頭に banner が立つ状態を維持。
                    _digest_banner = _giants_news_banner_html(
                        draft_title or title, source_name, category
                    )
                    content = _digest_banner + _digest_body
                    _digest_body_applied = True
                    logger.info(json.dumps({
                        "event": "player_voice_digest_body_applied",
                        "post_url": post_url,
                        "body_len": len(_digest_body),
                    }, ensure_ascii=False))

            # 2026-05-13: ヨシラバー voice 構造化 prefix を postgame article の
            # 冒頭に prepend。事実 (スコア / 投球内容) を table + 箇条書き +
            # 短い fan-voice narrative で見せ、「大手新聞 imitation」から脱却。
            # 既存 content には触らず prefix 追加のみ (副作用最小)。
            # digest body 適用済の場合は prefix を skip (digest 自身が
            # ヨシラバーらしさ section A/B を含む完全 body のため)。
            if not _digest_body_applied:
                _yoshilover_prefix = _build_yoshilover_structured_prefix(
                    draft_title, summary, body_article_subtype
                )
                if _yoshilover_prefix:
                    content = _yoshilover_prefix + content
                    logger.info(json.dumps({
                        "event": "yoshilover_prefix_applied",
                        "post_url": post_url,
                        "subtype": body_article_subtype,
                    }, ensure_ascii=False))

            post_id = _create_draft_with_same_fire_guard(
                wp,
                logger,
                same_fire_source_urls,
                same_fire_title_sources,
                draft_title,
                content,
                cats,
                post_url,
                featured_media=featured_media,
                enrichment_summary=summary,
                enrichment_category=category,
                enrichment_template_key=str(title_template_key or ""),
                enrichment_source_name=source_name,
                enrichment_raw_html=_article_raw_html,
                enrichment_source_type=source_type,
            )
            if post_id <= 0:
                # RELIABILITY-2026-05-08-DUP-FIX: same-fire dedup で 0 が返った時、
                # 後続 wp.get_post / featured_media 解決を skip し skip_dup として計上。
                skip_dup += 1
                continue
            effective_featured_media = _resolve_effective_featured_media(wp, post_id, featured_media, logger)
            draft_post_data = wp.get_post(post_id)
            draft_article_url = draft_post_data.get("link", "") or post_url
            success += 1
            _record_duplicate_guard_success(item.get("duplicate_guard_context"), post_id)
            created_category_counts[category] += 1
            created_subtype_counts[title_article_subtype] += 1
            _log_media_xpost_evaluated(
                logger,
                post_id,
                draft_title,
                category,
                title_article_subtype,
                media_quote_evaluation.get("selector_type", "none"),
                bool(media_quote_evaluation.get("is_target")),
            )
            if media_quote_evaluation.get("skip_meta"):
                _log_media_xpost_skipped(
                    logger,
                    post_id,
                    draft_title,
                    category,
                    title_article_subtype,
                    media_quote_evaluation["skip_meta"],
                )
            if media_quotes:
                total_media_quotes = len(media_quotes[:2])
                for quote_index, media_quote in enumerate(media_quotes[:2], start=1):
                    _log_media_xpost_embedded(
                        logger,
                        post_id,
                        draft_title,
                        source_type,
                        media_quote.get("handle", ""),
                        media_quote.get("url", ""),
                        quote_account=media_quote.get("quote_account", ""),
                        embed_section_type=media_quote.get("section_label", ""),
                        match_reason=media_quote.get("match_reason", ""),
                        match_score=int(media_quote.get("match_score", 0) or 0),
                        quote_index=quote_index,
                        quote_count_in_article=total_media_quotes,
                    )
            if source_type == "social_news" and body_article_subtype == "social_news":
                _log_social_body_template_applied(
                    logger,
                    post_id,
                    draft_title,
                    category,
                    _infer_social_source_indicator(source_name, tweet_url=post_url),
                    _social_section_count(ai_body_for_x),
                    _social_quote_count(raw_title, summary, ai_body_for_x),
                )
            if effective_story_category == "首脳陣" and body_article_subtype == "manager":
                _log_manager_body_template_applied(
                    logger,
                    post_id,
                    draft_title,
                    _manager_quote_count(raw_title, summary),
                    _manager_section_count(ai_body_for_x),
                )
            if effective_story_category == "試合速報" and _is_game_template_subtype(body_article_subtype):
                _log_game_body_template_applied(
                    logger,
                    post_id,
                    draft_title,
                    body_article_subtype,
                    _game_section_count(ai_body_for_x, body_article_subtype),
                    _game_numeric_count(raw_title, summary, ai_body_for_x),
                    _game_name_count(raw_title, summary, ai_body_for_x),
                )
            if effective_story_category == "ドラフト・育成" and _is_farm_template_subtype(body_article_subtype):
                _log_farm_body_template_applied(
                    logger,
                    post_id,
                    draft_title,
                    body_article_subtype,
                    _farm_section_count(ai_body_for_x, body_article_subtype),
                    _farm_numeric_count(raw_title, summary, ai_body_for_x),
                    _farm_is_drafted_player_story(raw_title, summary),
                )
            if body_article_subtype == "player_recovery":
                recovery_subject = _extract_recovery_subject(raw_title, summary)
                _log_recovery_body_template_applied(
                    logger,
                    post_id,
                    draft_title,
                    _extract_recovery_injury_part(raw_title, summary, recovery_subject),
                    _extract_recovery_return_timing(raw_title, summary, recovery_subject),
                    _recovery_section_count(ai_body_for_x),
                )
            if body_article_subtype == "player_notice":
                _notice_subject, notice_type = _extract_notice_subject_and_type(raw_title, summary)
                _log_notice_body_template_applied(
                    logger,
                    post_id,
                    draft_title,
                    notice_type or _extract_notice_type_label(f"{raw_title} {summary}") or "公示",
                    _notice_section_count(ai_body_for_x),
                    _notice_has_player_name(ai_body_for_x, raw_title, summary),
                    _notice_has_numeric_record(ai_body_for_x),
                )
            tweet_preview_text, tweet_preview_meta = _build_x_post_preview_for_observation(
                logger=logger,
                history=history,
                today_str=today_str,
                x_post_daily_limit=x_post_daily_limit,
                post_id=post_id,
                title=draft_title,
                article_url=draft_article_url,
                category=category,
                summary=ai_body_for_x or summary,
                content_html=content,
                article_subtype=title_article_subtype,
                source_type=source_type,
                source_name=source_name,
            )
            time.sleep(1)

            publish_gate_subtype = resolve_publish_gate_subtype(
                raw_title,
                summary,
                category,
                title_article_subtype,
                source_type,
            )
            publish_observation_reasons = get_publish_observation_reasons(
                source_type=source_type,
                draft_only=args.draft_only,
                featured_media=effective_featured_media,
            )
            for reason in publish_observation_reasons:
                publish_observation_counts[reason] += 1
            if "featured_media_observation_missing" in publish_observation_reasons:
                _log_featured_media_observation_missing(
                    logger,
                    post_id,
                    draft_title,
                    publish_gate_subtype,
                    category,
                    primary_url=_og_url,
                    candidate_count=len(_article_images),
                    source_type=source_type,
                )
            publish_skip_reasons = get_publish_skip_reasons(
                source_type=source_type,
                draft_only=args.draft_only,
                featured_media=effective_featured_media,
                article_subtype=publish_gate_subtype,
            )
            # 344-INGEST 2026-05-14 lock 変更: 当初 YouTube は force-draft だったが
            # 「公開で mail でも OK、title prefix で識別できれば user 手動編集 前提」に
            # user 切替。force-draft gate を revert、title prefix で対応 (#7)。
            if source_type in {"news", "social_news"} and not args.draft_only:
                quality_guard = _evaluate_publish_quality_guard(
                    content_html=content,
                    article_subtype=publish_gate_subtype,
                )
                if not quality_guard["ok"]:
                    publish_skip_reasons.extend(list(quality_guard["reasons"]))
                    _log_publish_blocked_by_quality_guard(
                        logger,
                        post_id,
                        draft_title,
                        publish_gate_subtype,
                        category,
                        quality_guard,
                    )
            for reason in publish_skip_reasons:
                publish_skip_reason_counts[reason] += 1
            if "publish_disabled_for_subtype" in publish_skip_reasons:
                _log_publish_gate_skipped(
                    logger,
                    post_id,
                    draft_title,
                    publish_gate_subtype,
                    category,
                    "publish_disabled_for_subtype",
                )
            if "live_update_publish_disabled" in publish_skip_reasons:
                _log_publish_gate_skipped(
                    logger,
                    post_id,
                    draft_title,
                    publish_gate_subtype,
                    category,
                    "live_update_publish_disabled",
                )
            if publish_skip_reasons:
                logger.info(f"  [下書き止め] post_id={post_id} reason={','.join(publish_skip_reasons)}")
                published = False
            else:
                published = finalize_post_publication(
                    wp,
                    post_id,
                    post_url,
                    history,
                    entry_title_norm,
                    logger,
                    draft_only=False,
                )
            persist_processed_entry_history(
                history,
                item.get("history_urls", [post_url]),
                item.get("history_title_norms", [entry_title_norm] if entry_title_norm else []),
                rewritten_title=draft_title,
                original_title=raw_title,
                published=published,
                publish_skip_reasons=publish_skip_reasons,
                duplicate_guard_context=item.get("duplicate_guard_context"),
                post_id=post_id,
            )

            article_url = ""
            if published:
                wp_post_data = wp.get_post(post_id)
                article_url = wp_post_data.get("link", "")

            x_skip_reasons = get_auto_tweet_skip_reasons(
                source_type=source_type,
                category=category,
                article_subtype=publish_gate_subtype,
                draft_only=args.draft_only,
                x_post_count=x_post_count,
                x_post_daily_limit=x_post_daily_limit,
                featured_media=effective_featured_media,
                published=published,
                article_url=article_url,
            )
            for reason in x_skip_reasons:
                x_skip_reason_counts[reason] += 1
            if "x_post_disabled_for_subtype" in x_skip_reasons:
                _log_x_post_subtype_skipped(
                    logger,
                    post_id,
                    draft_title,
                    category,
                    publish_gate_subtype,
                    "x_post_disabled_for_subtype",
                )

            if not x_skip_reasons:
                try:
                    import tweepy
                    from dotenv import load_dotenv
                    load_dotenv(ROOT / ".env")
                    if tweet_preview_text:
                        tweet_text = tweet_preview_text
                        if draft_article_url and article_url and draft_article_url != article_url:
                            tweet_text = tweet_text.replace(draft_article_url, article_url, 1)
                    else:
                        tweet_text = build_x_post_text(
                            draft_title,
                            article_url,
                            category,
                            summary=ai_body_for_x or summary,
                            content_html=content,
                            article_subtype=title_article_subtype,
                            source_type=source_type,
                            source_name=source_name,
                        )
                    x_client = tweepy.Client(
                        bearer_token=os.environ.get("X_BEARER_TOKEN"),
                        consumer_key=os.environ.get("X_API_KEY"),
                        consumer_secret=os.environ.get("X_API_SECRET"),
                        access_token=os.environ.get("X_ACCESS_TOKEN"),
                        access_token_secret=os.environ.get("X_ACCESS_TOKEN_SECRET"),
                    )
                    resp = x_client.create_tweet(text=tweet_text)
                    tweet_id = resp.data["id"]
                    x_post_count += 1
                    history[f"x_post_count_{today_str}"] = x_post_count
                    persist_history(history)
                    logger.info(f"  [公開+X投稿] post_id={post_id} tweet_id={tweet_id} 本日{x_post_count}/{x_post_daily_limit}件")
                except Exception as xe:
                    logger.warning(f"  [X投稿失敗] post_id={post_id} {xe}")
                    logger.info(f"  [公開済み] post_id={post_id}")
            else:
                if published:
                    logger.info(f"  [X投稿スキップ] post_id={post_id} reason={','.join(x_skip_reasons)}")
                    logger.info(f"  [公開] post_id={post_id} image={'あり' if effective_featured_media else 'なし'}")
                else:
                    logger.info(
                        f"  [下書き維持] post_id={post_id} reason={','.join(publish_skip_reasons)} "
                        f"image={'あり' if effective_featured_media else 'なし'}"
                    )

        except Exception as e:
            logger.error(f"  [ERROR] 公開失敗: {e}")
            error += 1

    logger.info(
        f"=== 完了: 取得={total} / 投稿={success} / 重複スキップ={skip_dup} "
        f"/ フィルタスキップ={skip_filter} / エラー={error} ==="
    )
    run_summary_payload: dict[str, Any] = {
        "event": "rss_fetcher_run_summary",
        "dry_run": bool(args.dry_run),
        "draft_only": bool(args.draft_only),
        "has_game": bool(has_game),
        "opponent": opponent,
        "venue": venue,
        "entry_limit": args.limit,
        "total_entries": total,
        "drafts_created": success,
        "skip_duplicate": skip_dup,
        "skip_filter": skip_filter,
        "error_count": error,
        "x_post_count": x_post_count,
        "x_post_daily_limit": x_post_daily_limit,
        "x_ai_generation_count": history.get(f"x_ai_generation_count_{today_str}", x_ai_generation_count),
        "x_ai_generation_limit": x_post_daily_limit,
        # RELIABILITY-2026-05-08-T1: 1 fire 1 line で全観察項目を判定可能にする
        # telemetry block。5/9 朝検証で個別 grep を不要化。
        "review_drafts_created_count": review_drafts_created_count,
        "review_drafts_axes_breakdown": _counter_to_plain_dict(review_drafts_axes_breakdown),
        "bypass_full_invocation_count": bypass_full_invocation_count,
        "tag_scraper_per_source": _counter_to_plain_dict(tag_scraper_per_source),
        "scraper_fetch_failures": scraper_fetch_failures,
        "game_live_source_policy_active": game_live_source_policy_active,
        "game_live_source_policy_window": GAME_LIVE_SOURCE_POLICY_WINDOW_LABEL,
        "game_live_source_policy_skipped_sources": game_live_source_policy_skipped_sources,
    }
    if _fetcher_log_sampling_v1_enabled() or _pre_post_gen_validate_skip_enabled():
        run_summary_payload["log_sampling_v1"] = _build_log_sampling_summary()
    logger.info(json.dumps(run_summary_payload, ensure_ascii=False))
    logger.info(
        json.dumps(
            {
                "event": "rss_fetcher_flow_summary",
                "skip_reasons": _skip_reasons_with_samples(
                    skip_reason_counts,
                    not_giants_related_sample_titles=not_giants_related_sample_titles,
                    skip_reason_sample_titles=skip_reason_sample_titles,
                ),
                "prepared_category_counts": _counter_to_plain_dict(prepared_category_counts),
                "prepared_subtype_counts": _counter_to_plain_dict(prepared_subtype_counts),
                "created_category_counts": _counter_to_plain_dict(created_category_counts),
                "created_subtype_counts": _counter_to_plain_dict(created_subtype_counts),
                "publish_skip_reason_counts": _counter_to_plain_dict(publish_skip_reason_counts),
                "publish_observation_counts": _counter_to_plain_dict(publish_observation_counts),
                "x_skip_reason_counts": _counter_to_plain_dict(x_skip_reason_counts),
                "x_ai_generation_count": history.get(f"x_ai_generation_count_{today_str}", x_ai_generation_count),
                "x_ai_generation_limit": x_post_daily_limit,
            },
            ensure_ascii=False,
        )
    )


if __name__ == "__main__":
    main()
